COMMENT ON COLUMN canvas_projects.status IS '状态：1正常，0删除';
COMMENT ON COLUMN canvas_projects.created_at IS '创建时间';
COMMENT ON COLUMN canvas_projects.updated_at IS '更新时间';
CREATE INDEX idx_canvas_projects_user_status_updated ON canvas_projects(user_id, status, updated_at);

CREATE TABLE assets (
    id VARCHAR(64) PRIMARY KEY,
    user_id BIGINT NOT NULL,
    kind VARCHAR(20) NOT NULL,
    title VARCHAR(100) NOT NULL,
    asset_data JSONB NOT NULL,
    status INTEGER NOT NULL DEFAULT 1,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE assets IS '素材表';
COMMENT ON COLUMN assets.id IS '素材ID';
COMMENT ON COLUMN assets.user_id IS '用户ID';
COMMENT ON COLUMN assets.kind IS '素材类型：text/image/video';
COMMENT ON COLUMN assets.title IS '素材标题';
