COMMENT ON COLUMN assets.created_at IS '创建时间';
COMMENT ON COLUMN assets.updated_at IS '更新时间';
CREATE INDEX idx_assets_user_kind_updated ON assets(user_id, kind, updated_at);
CREATE INDEX idx_assets_user_status_updated ON assets(user_id, status, updated_at);

CREATE TABLE generation_logs (
    id VARCHAR(64) PRIMARY KEY,
    user_id BIGINT NOT NULL,
    log_type VARCHAR(20) NOT NULL,
    title VARCHAR(100) NOT NULL,
    log_data JSONB NOT NULL,
    status INTEGER NOT NULL DEFAULT 1,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE generation_logs IS '生成记录表';
COMMENT ON COLUMN generation_logs.id IS '生成记录ID';
COMMENT ON COLUMN generation_logs.user_id IS '用户ID';
COMMENT ON COLUMN generation_logs.log_type IS '记录类型：image/video';
