CREATE TABLE ai_generation_tasks (
    id VARCHAR(64) PRIMARY KEY,
    user_id BIGINT NOT NULL,
    task_type VARCHAR(20) NOT NULL,
    model VARCHAR(128) NOT NULL,
    provider VARCHAR(50) NOT NULL DEFAULT '',
