INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('便利店夜景', '在夏夜晚上 10 点的便利店门口，生成一张超写实的城市街头多人合影。3 到 4 个年轻人在门口短暂聊天，有人拿着饮料，有人坐在室外塑料椅上，有人站着看手机。玻璃门窗内透出明亮白光，外面有暖黄色路灯和远处汽车车灯。人物穿着日常服装：T 恤、衬衫、短裤、牛仔裤、运动鞋。不要网红造型。面部和姿态必须像真实路人，不能过度精修。环境中必须包含真实便利店元素：冰柜贴纸、促销海报、垃圾桶、门口地垫、玻璃反光、路边共享单车、地面上的饮料瓶水珠。整张图应像摄影师在城市里抓拍到的真实生活切片。重点测试自然的多人互动、夜间便利店光线、玻璃反射，以及普通人的生活氛围还原。', '', '', 'awesome-gpt-image', '["摄影","照片级写实"]'::jsonb, 'https://github.com/ZeroLu/awesome-gpt-image', 1, 1001);
