INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('宋朝社交媒体动态流', '“宋朝人的朋友圈” / “SONG DYNASTY SOCIAL MEDIA FEED”，采用古今穿越幽默融合的界面设计风格。画面模拟手机社交媒体界面，但内容全部是宋朝场景。头像是宋代文人的肖像，用户名为 “Su Dongpo SuShi_Official”，发帖内容为 “刚到黄州，被贬了但心态还行。今天自己做了东坡肉，味道绝了，附上做法：”。配图是一张工笔画风格的东坡肉特写。点赞列表为 “黄庭坚、秦观、佛印等 126 人”，评论区为 “王安石：呵呵” “司马光：还是那个味”。点赞图标等界面元素替换成宋代纹样。状态栏显示 “大宋移动 5G” 和 “元丰三年”。整体配色为手机深色模式搭配雅致宋韵色调，形成历史与社交媒体趣味碰撞的代表作。', '', '', 'awesome-gpt-image', '["ui","ux","社交媒体"]'::jsonb, 'https://github.com/ZeroLu/awesome-gpt-image', 1, 1018);
