INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('角色关系海报', '为 [主题] 生成一张高设计感的角色关系海报。这不应是一张普通插画，而应是一张融合信息可视化、叙事结构、海报级设计以及对原作风格高度还原的关系图。

自动完成以下事项：
- 识别原作及其核心设定
- 选出 6 到 12 位最具代表性的关键角色，必要时上限 15 位
- 识别并展示最重要的关系，例如血缘、爱情、友情、联盟、敌对、师徒、主仆、操控、背叛和隐藏关系
- 自动选择最合适的构图，如主角中心式、双核心对抗式、阵营布局、家谱式或时间演化结构
- 提取作品的风格 DNA，包括配色、世界观符号、材质语言、情绪气质、版式节奏和标志性母题
- 将这些风格元素转化为整张关系图的视觉设计，而不是简单复制官方海报
- 用不同颜色、线型和箭头区分不同关系类型，同时保持版面清晰可读
- 核心角色最突出，次要角色次之，边缘角色更弱，以形成明确的视觉层级
- 确保每个角色名都清晰易读，必要时可加上身份或阵营标签

最终成品应当：
- 让主要关系一眼就能看懂
- 强烈唤起原作的辨识度和世界设定
- 兼具信息图清晰度与高级海报设计感
- 整体统一、精致、完整，适合社交分享或海报展示
- 避免廉价流程图感、混乱或信息过载', 'https://pbs.twimg.com/media/HGXHhQcbAAAFcYA?format=jpg&name=large', '![](https://pbs.twimg.com/media/HGXHhQcbAAAFcYA?format=jpg&name=large)

![](https://pbs.twimg.com/media/HGXHhP8WsAAMvWm?format=jpg&name=large)

![](https://pbs.twimg.com/media/HGXHifHbUAAgLZO?format=jpg&name=large)

![](https://pbs.twimg.com/media/HGXHjggWgAAAGAG?format=jpg&name=large)', 'awesome-gpt-image', '["信息图","教育","文档"]'::jsonb, 'https://github.com/ZeroLu/awesome-gpt-image', 1, 1048);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('16 格动漫表情图', '创建一张 16 格表情图，主角是一位银发蓝眼的动漫少女。她的脸型、发型和服装必须在所有格子中保持高度一致。16 种表情应包含：开心、难过、生气、惊讶、害羞、无语、邪魅一笑、沉思、好奇、自豪、委屈、不屑、困惑、害怕、哭泣，以及爱心表情。', '', '', 'awesome-gpt-image', '["角色","一致性"]'::jsonb, 'https://github.com/ZeroLu/awesome-gpt-image', 1, 1049);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('官方角色设定参考页', '基于这个角色和背景，请创建一张类似官方设定资料的角色参考页。
- 包含三视图：正面、侧面和背面
- 添加角色的多种表情变化
- 拆解并展示服装与装备的细节部分
- 添加配色板
- 包含简短的世界观说明
- 整体采用规整版式（白底、插画风）', '', '', 'awesome-gpt-image', '["角色","一致性"]'::jsonb, 'https://github.com/ZeroLu/awesome-gpt-image', 1, 1050);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('宠物品牌联名海报', '主题：“77（猫的名字）X KFC” 联名海报。生成一张联名海报，主角是同一只宠物（外观与毛色必须绝对一致），并融入 KFC 品牌识别元素（红白配色、经典 Logo、餐厅场景等）。让这只猫穿着 KFC 员工制服、员工帽和名牌，站在柜台前售卖炸鸡、汉堡和套餐，并与全家桶、薯条、可乐等品牌元素互动。整体风格应活泼有趣，具有商业联名感，适合线上宣传和活动海报。海报文案中的中文内容可以自由发挥添加。', '', '', 'awesome-gpt-image', '["图像编辑","风格迁移"]'::jsonb, 'https://github.com/ZeroLu/awesome-gpt-image', 1, 1051);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('漫画页面上色与翻译', '给这页漫画上色，并把它翻译成中文。文字要放回原来的位置，同时保持构图和图像细节的一致性。', '', '', 'awesome-gpt-image', '["图像编辑","风格迁移"]'::jsonb, 'https://github.com/ZeroLu/awesome-gpt-image', 1, 1052);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('a premium claw machine', 'A high-end, hyper-realistic 3D render of a premium claw machine inspired by Milka branding. The machine is finished in glossy Milka lavender-purple with smooth, rounded edges, and set against a warm, minimal cream-toned backdrop. Inside, the claw machine is filled with meticulously detailed Milka chocolate bars, shiny golden hazelnuts, and soft plush cows with signature Milka purple patches. The front and top panels feature glowing, embossed Milka logos in white. The machine has crystal-clear glass panels, chrome control buttons, and a sleek joystick. Soft ambient lighting inside casts warm highlights on the prizes, creating a cozy, indulgent, and luxurious chocolate-themed arcade atmosphere. The focus is on elegance, brand immersion, and photorealistic product presentation.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1053);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('Q 版角色卡', '画一张带有圆角和柔和投影的现代 UI 卡片 2:3图片。卡片中央应展示一个上穿图片转换为的 3D 卡通风角色。姿势和服饰应该都是图片的 Q 版版本，在角色下方，包含一个加粗的黑色标题（“Reyna”）和一个字体更小、颜色更浅的副标题（“Valorant”）。使用干净、简约的白色或浅灰色背景。整体外观应感觉现代、有趣且富有科技感，适合创意应用或游戏界面。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1054);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('a luxurious wooden door', 'A close-up photograph of a luxurious wooden door with detailed paneling and rich grain texture. The door features a custom-shaped doorknob in the form of the [LOGO_NAME] logo, made of polished material (metal, brass, ceramic, etc.) to look realistic and tangible. The handle is mounted on an antique bronze base, with soft, ambient lighting emphasizing the reflections, shadows, and depth of both the knob and door.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1055);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('candy sculpture', 'a candy sculpture version of this portrait wrapped in transparent plastic and held by a hand, [background]', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1056);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('3D miniature scene inside a clear glass snow globe', 'Create a 3D miniature scene inside a clear glass snow globe, with a playful and cute child figurine in the center. The child is wearing beige overalls, a brown t-shirt, yellow shoes, and is smiling with a joyful expression. Surrounding the child are construction-themed items like a yellow crane, excavators, and traffic cones, all in a playful, cartoonish style. The base of the snow globe is inscribed with the word "FENDI" in bold letters, and there are small stones scattered around the base. The background is a soft beige color, enhancing the warm, playful vibe of the scene. The snow globe should have a glossy, realistic texture, and the entire scene should evoke a feeling of joy and fun.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1057);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('3D Emoji', '创建 [🧸] 的高分辨率 3D 渲染图，将其设计为一个可充气的蓬松物体。其形状应看起来柔软、圆润且充满空气——就像毛绒气球或充气玩具一样。

使用光滑的哑光纹理，并搭配细微的织物褶皱和缝线，以强调其充气效果。其形状应略微不规则且柔软，并配以柔和的阴影和灯光，以突出其体积感和真实感。将其放置在干净简约的背景（浅灰色或淡蓝色）上，并保持俏皮的雕塑美感。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1058);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('3D Emoji', 'Create a high-resolution 3D render of [] designed as an inflatable, puffy object. The shape should appear soft, rounded, and air-filled — like a plush balloon or blow-up toy. Use a smooth, matte texture with subtle fabric creases and stitching to emphasize the inflatable look. The form should be slightly irregular and squishy, with gentle shadows and soft lighting that highlight volume and realism. Place it on a clean, minimal background (light gray or pale blue), and maintain a playful, sculptural aesthetic.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1059);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('Blueprint schematic', 'A blueprint schematic of a retro-futuristic motorcycle, drawn in the style of early 20th-century industrial patents. Rendered in crisp blue ink with white technical lines, featuring exploded views, angular labels, and stamped diagram codes.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1060);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('A whimsical miniature Apple Store', 'A whimsical miniature Apple Store, designed to look like a giant Apple product box, complete with the iconic Apple logo and intricate details. The two-story building features large glass windows that clearly showcase a modern and high-end interior: minimalist display tables, bright and gentle lighting, and staff members assisting customers. On the street, adorable little figurines are strolling or relaxing, with benches, street lamps, and potted plants arranged around them, creating a charming corner of the city. The entire scene adopts an urban miniature landscape style, rich in detail and realism, with soft lighting that evokes a pleasant and relaxing afternoon atmosphere.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1061);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('迷你 3D 风格建筑', '3D Q版迷你风格，一个充满奇趣的迷你星巴克咖啡馆，外观就像一个巨大的外带咖啡杯，还有盖子和吸管。建筑共两层，大大的玻璃窗清晰地展示出内部温馨而精致的设计：木质的家具、温暖的灯光以及忙碌的咖啡师们。街道上有可爱的小人偶漫步或坐着，四周布置着长凳、街灯和植物盆栽，营造出迷人的城市一角。整体采用城市微缩景观风格，细节丰富、逼真，画面光线柔和、呈现出午后的惬意感受。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1062);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('Capsule胶囊', '创建3:2的图片，一个高高的、外观逼真且充满活力的胶囊体水平漂浮着。

它的左半边是标志性的星巴克绿色，标有“Starbucks – Uplifting the Everyday”字样以及经典的美人鱼（Siren）标志。

右半边是透明的，里面填充着漂浮的烘焙咖啡豆、细腻的奶泡漩涡、手绘咖啡杯图标以及代表社区连接的抽象暖色调线条，需要有背景色。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1063);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('Capsule', 'A tall, realistic cheerful capsule floats horizontally. The left side is rich green with a red stripe, labeled “GUCCI – ICON SERIES” in elegant serif. The right side is transparent, filled with tiny loafers, gold GG belt buckles, and silk scarf patterns — suspended like artifacts in a luxe archive', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1064);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('Capsule', 'A tall, realistic cheerful capsule floats horizontally. The left side is soft neutral beige, labeled “UNIQLO – ESSENTIAL FIT” with the classic red UNIQLO logo. The right half is transparent, filled with floating fabric swatches, puffer coat folds, thermal fiber textures, and line icons of wardrobe basics.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1065);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('Advertisement poster', 'I will send you a photo of a woman and a perfume bottle. Please don’t change the woman’s face or the perfume bottle, but you can change her outfit. Using these visuals, I’d like you to create a perfume advertisement poster for a fragrance called “Miilesus.”', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1066);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('物理破坏效果卡片', '一幅超写实、电影感的插画，描绘了劳拉·克劳馥动态地撞穿一张“考古探险”集换卡牌的边框。她正处于跳跃中或用绳索摆荡，穿着标志性的冒险装备，可能正在使用双枪射击，枪口的火焰帮助将卡牌古老的石雕边框震碎，在破口周围制造出可见的维度破裂效果，如能量裂纹和空间扭曲，使灰尘和碎片四散飞溅。她的身体充满活力地向前冲出，带有明显的运动深度，突破了卡牌的平面，卡牌内部（背景）描绘着茂密的丛林遗迹或布满陷阱的古墓内部。卡牌的碎屑与 crumbling 的石头、飞舞的藤蔓、古钱币碎片和用过的弹壳混合在一起。“考古探险”的标题和“劳拉·克劳馥”的名字（带有一个风格化的文物图标）在卡牌剩余的、布满裂纹和风化痕迹的部分上可见。充满冒险感的、动态的灯光突出了她的运动能力和危险的环境。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1067);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('dimensional break card', 'Generate a portrait ratio image with this prompt
A professional studio photo Panini soccer card featuring football legend Lionel Messi wearing his iconic Argentina blue and white striped jersey. In a dramatic moment, Messi kicks the ball with force, breaking through the boundary of the card—shattering it into fragments. The card explodes into reality as Messi emerges from the 2D surface into the 3D world. In the foreground, a football spins at high speed, blurring toward the viewer. The background reveals the torn remains of the card against a dark backdrop, while radiant aurora-like light beams burst outward from the broken card, creating a surreal and powerful dimensional crossover effect.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1068);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('poster', 'Create a Bauhaus style poster from this image and add the slogan [Good Morning] as the title.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1069);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('fashion magazine cover', 'A beautiful woman wearing a pink cheongsam, floral headwear with colorful flowers in her hair, and an elegant white lace collar around her neck. She is holding large butterflies in one hand. The photography style features high-definition details, resembling a fashion magazine cover design. The text "FASHION DESIGN" is displayed at the top center of the photo. The background is a minimalist, light gray solid color, designed to highlight the model.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1070);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('passport page', 'Create a realistic passport page with an entry stamp for [{City}, {Country}]. The stamp should say "Welcome to {City}" in bold English, designed in a round or oval shape with decorative borders. Include the word "ARRIVAL" and a fictional date like "15 APR 2025" Incorporate a subtle silhouette of {Main Landmark} as a background detail within the stamp. Use deep blue or red ink with light smudges for added realism. The stamp should appear slightly angled, as if hand-pressed. The passport page should show visible paper texture and security patterns.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1071);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('PSA', 'Pretend you are PSA, the Collectibles Authentication and Grading Service. Instead of cards, you will be grading the aura of the character in the image I provide. Be strict and objective when assigning a grade, using PSA’s official scale: PSA 1 = PR, PSA 1.5 = FR, PSA 2 = GOOD, PSA 3 = VG, PSA 4 = VG-EX, PSA 5 = EX, PSA 6 = EX-MT, PSA 7 = NM, PSA 8 = NM-MT, PSA 9 = MINT, PSA 10 = GEM MT. When done grading, create a PSA slab with the image provided, cropped to the size of a real card. The label at the top must follow the official PSA format. On the left, display the title "GNRLYXYZ" and directly below it, "1/1". Beneath that, place the PSA-style barcode only. On the right side of the label, stack the grade label from the PSA scale at the top, and the numeric grade from the PSA scale at the bottom. Below that, display the certification number. Ensure all text in the label is uniform in size and has balanced padding from the red border, exactly as seen on authentic PSA slabs. Place the slab on a white background and display the full slab. Do NOT add any text or labels on the card.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1072);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('keycap scene', 'A photorealistic ESC keycap scene shows a miniature cozy living room setup. Inside: a glowing red Netflix screen, a plush red couch, popcorn bowl, and throw blanket. A small figure lounges with feet up, watching content. The red “N” logo glows from behind like mood lighting. Outside: cool tech-blue reflections on F1, Shift, and Q keys. The word “ESC” is subtly present in a glassy fog on top of the cap.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1073);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('low poly', 'A low-poly 3D render of a camel, built from clean triangular facets with flat sandy beige and burnt orange surfaces. The environment is a stylized digital desert with minimal geometry and ambient occlusion.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1074);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('typographic portrait', 'Recreate the attached image as Typography Portrait. Subject is happiness.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1075);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('illustration', 'Transform a simple flat vector illustration of a swan into a soft, 3D fluffy object. Use the exact colors. The shape is fully covered in fur, with hyperrealistic hair texture and soft shadows. The object is centered on a clean, light gray background and floats gently in space. The style is surreal, tactile, and modern, evoking a sense of comfort and playfulness. Studio lighting, high-resolution render.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1076);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('Turn your profile image into a sculpture!', 'A photorealistic image of an ultra-detailed sculpture of the subject in image made of shining marble. The sculpture should display smooth and reflective marble surface, emphasizing its luster and artistic craftsmanship. The design is elegant, highlighting the beauty and depth of marble. The lighting in the image should enhance the sculpture''s contours and textures, creating a visually stunning and mesmerizing effect', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1077);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('Reality photo', 'Turn this drawings into reality photo', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1078);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('Turn  drawings into stunning photographs', 'Turn the drawings into stunning  photographs', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1079);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('讽刺漫画', '讽刺漫画，川普手上拿着扑克牌，显示扑克牌背面，马斯克正在对川普耳语，头顶有气泡文字（中文）
川普：我手里有牌
马斯克：别忘了你手里的牌是Made In China', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1080);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('拟人化的 3D 形象', '給【西北工业大学】画一个拟人化的3D Q版美少女形象，体现学校【航空航天航海三航】特色', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1081);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('微型立体场景呈现', '微型立体场景呈现，运用移轴摄影的技法，呈现出Q版《水浒传》电视剧里面潘金莲洗澡的场景', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1082);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('等距视角微缩场景', '绘制 3D 渲染的可爱C4D质感等距视角微缩场景，呈现出一个以 【XX】场景为核心的 Q 版角色世界。  场景采用温暖的电影感光线、柔和阴影与移轴模糊效果，材质上以哑光黏土与柔软塑胶为主。  环境叙事元素丰富，搭配有【XX】相关的等标志性道具与装饰性灯光，展现出生动细致的场景氛围。16:9 HDR', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1083);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('摊开的古书', '创作一个3D场景，展示一本摊开的古书，书页泛黄，边缘破损，放在木桌上。左页为密密麻麻的古文排版，右页呈现微缩场景，带有裸眼3D效果：一个庭院，庭院内有盛开的樱花树，粉色花瓣飘落，草地上站着一位身穿粉色汉服的女子，手持扫帚，正在清扫落花。庭院背景有一座传统中式建筑，红柱青瓦，周围有小树和岩石装饰。书页周围有微弱光晕，营造立体感，桌上散落几片樱花瓣，背景为柔和的米黄色，整体氛围充满古风诗意和历史感。细节精致，色彩淡雅，展现古书的沧桑感和庭院的宁静美感。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1084);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('泡罩药片包装图', '一个高度写实、细节丰富的泡罩药片包装图，药片以 2x5 的布局排列成两列共十颗。每一颗药丸代表一个不同的｛食物｝。
所有药丸封存在带有光泽的透明泡壳中，背景为带有细致斜纹的银色铝箔底板。整体视觉风格为极简主义的商业产品摄影风，采用柔和的环境光照，背景为中性色的米色，突出药片主体。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1085);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('Isometric view of a city', 'Isometric miniature-model view of {city} encapsulated within a cutaway box viewed from a clean, top-down 45° angle. {weather} weather effects subtly integrated into the scene, with {specific weather effects like snowflakes, clouds, fog, rain, sun etc.} softly interacting with the city above. The city’s base should appear thin and minimal, focusing on the city structures with a more delicate, less pronounced foundation. Physically-based rendering (PBR), realistic lighting. Solid-color background outside the box for clarity and minimalism. Centered composition, emphasizing a precise and delicate diorama aesthetic.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1086);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('泰坦尼克号经典场面', '将附图中的人物转换成可爱Q版3D造型
场景：在豪华游轮最顶尖的船头，船头是尖的。
男士带着女士站在泰坦尼克号船头，男士双手搂着女士的腰，女士双臂伸展穿着连衣裙，迎着风，脸上洋溢着自由与畅快。
此时天色呈现出黄昏的暖色调，大海在船下延展 。
除了人物用Q版3D造型以外，其他环境都是实物。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1087);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('立体浮雕风格', '将附图人物转换成立体镂空纸雕艺术风格。画面洁净，纸面平滑柔和。

画面中心：人物，古风装扮

背景：拱形纸雕，多层层叠，远近不同造型，柔和的光影从背景传来，将视觉引导到人物。整个画面有镂空纸雕边框。

风格：中国风立体纸雕艺术风格，利用分层切割和拼贴手法，塑造出具有强烈空间感与层次感的画面。

元素：融入古典中式元素；有繁茂盛开的花卉；远处是连绵树木；天空中有飞鸟点缀。

色彩：以鲜艳透明的橙、白为主调，鲜明且富有张力。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1088);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('Figure Box', 'portrait ratio, create a image, inspired by Funko pop figure box style in isometric style, adding a title "Real World Edition" to the box, featuring an exhausting graphic designer with accessories on his side(apple laptop, phone, glasses, hat, coffee),and demo the figure beside the box, with photorealistic style', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1089);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('Changer ages', 'make her [10, 20, 30, 40] years old', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1090);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('3D characters', 'Turn the real photo on the right into a stylized 3D character illustration like the character in the left image. Smooth, clay-like textures. Soft lighting with a subtle glow. Friendly and cartoonish expression. High attention to detail and personality.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1091);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('action figure', 'Draw an action figure toy (barbie doll) of the person in this photo. The figure should be full figure and displayed in it original blister pack packaging. On top of the box is the name of the toy "add name" with "headline" across a single line of text. In the blister pack packaging, next to the figure show the toy''s accessories including a - add accessories', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1092);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('fluffy logo', 'Transform a simple flat vector icon of Figma logo into a soft, 3D fluffy object. Use the exact colors. The shape is fully covered in fur, with hyperrealistic hair texture and soft shadows. The object is centered on a clean, light gray background and floats gently in space. The style is surreal, tactile, and modern, evoking a sense of comfort and playfulness. Studio lighting, high-resolution render.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1093);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('3D fluffy emojis', 'Transform a simple flat vector icon of [] into a soft, 3D fluffy object. The shape is fully covered in fur, with hyperrealistic hair texture and soft shadows. The object is centered on a clean, light gray background and floats gently in space. The style is surreal, tactile, and modern, evoking a sense of comfort and playfulness. Studio lighting, high-resolution render.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1094);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('影视剧的角色手办', 'Create a realistic and humorous action figure of Mr. Bean, the iconic British comedy character played by Rowan Atkinson. 

The figure should be designed as a collectible action toy, capturing his quirky personality and classic look.  
Key Elements:  

Character Design:  Accurately depict Mr. Bean’s exaggerated facial expression, distinctive features, and comedic body posture.  

Outfit: Signature brown tweed jacket, white shirt, thin red tie, dark trousers, and black shoes.  Include a slightly awkward or goofy pose that reflects his clumsy yet lovable charm.  Accessories:  Include miniature props that are instantly recognizable from the show, such as:  Teddy (his beloved stuffed bear)  A suitcase  His iconic lime green Mini car (as a miniature or on the box design)  A turkey (as a reference to the famous holiday episode)  A TV remote or random quirky objects that fit his antics  

Packaging Design:  Place the action figure inside a detailed, collectible toy box.  At the top of the box, display the title Mr. Bean in playful, bold lettering.  Beneath that, include the character name "Mr. Bean", possibly with a humorous tagline like “The Ultimate Oddball Collectible.”  The background design can feature a silly scene from the show (like his apartment or the car park).  

Visual Style:  Render the entire figure, accessories, and packaging in a highly realistic, slightly cartoonish style to capture the essence of the character while keeping a lifelike toy aesthetic.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1095);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('3D-style icons', 'minimalist 3D render, [Subject], soft matte finish, black and antique gold details, pristine white backdrop, isometric angle, ambient glow, feathered shadows, simple and elegant', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1096);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('3d avatar asset', 'Create a 3d avatar asset, 8 different profiles/poses, different actions, maintaining consistency in character, 16:9 aspect ratio', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1097);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('action figure pack', 'create action figure pack based on my conversations', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1098);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('3D character', 'A 3D-rendered digital illustration of a young man in his mid-20s with light skin and wavy reddish-brown hair, wearing a camel-colored blazer, an off-white sweater, dark blue jeans, and black sneakers. He stands against a clean, off-white background, showing a [{emotion}] expression with a [{body position}] posture, stylized in a semi-realistic cartoon style with soft lighting and high detail.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1099);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('claymation', 'A claymation-style grumpy wizard, sculpted with rough fingerprints, hand-painted imperfections, and smudges. Set in a diorama of earthy textures and pastel backdrops, giving it a tangible, handmade feel.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1100);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('Arcade diorama', 'Generate a portrait photo with this prompt
Creative composition, A minimalist 3D arcade game diorama, the huge arcade machine decorate with fake 90s fighting game style. Inside the screen, there is a room of 90s game theme, decorate with posters and console, crt tv. A kid figure sitting in the room playing, dressed with black band tshirt, blue jeans, converse sneakers, red cap. Small surroundings in the air by 90s kids favorite toy items. The bottom black matted stand is labeled “90s Kid” in bold san serif bronze text, the background is a gradient color: from dark to light. With white, blue and red color theme', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1101);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('黛玉葬花', '以微型立体场景呈现，运用移轴摄影的技法，呈现出梦幻而灵动的意境。画中乃《红楼梦》之林黛玉葬花一幕，场景细致而迷人，如童话般玲珑雅致。

细观画面，3D Q版黛玉亭亭玉立于微缩园林之间，一身素淡纱裙，手执小巧花锄，低眉含愁，眸中隐约泪光，姿态楚楚动人，面容带着忧郁与清冷之色。她身旁，盛花的小竹篮散落在地，粉红花瓣点缀于草丛，如碎玉纷飞；溪流如玻璃树脂般晶莹通透，涓涓细流折射着微光，环绕着整个场景，映衬出几分凄清与诗意。

园林里散落着细腻别致的假山石头，黛玉脚下的土地精雕细琢，犹如微缩盆景般细致逼真。树木、花丛皆精巧细致，枝叶轻盈透明，纤毫毕现。远处假山上隐约可见一座迷你版潇湘馆，精巧华丽的窗棂中透出微弱灯光。移轴镜头柔化了远近之间的距离，令黛玉的身影格外凸显，宛如置身童话世界之中央。

场景整体光影细腻温柔，透着朦胧的电影光效，如诗如画，既带着古典小说的雅致与哀婉，又有几分清新与纯真，令人一眼便沉醉其中。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1102);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('工作间手办', '使用此提示生成肖像比例照片：

竖版：4:3 比例

风格：一个Q版 可爱 3d 风格的立体模型

内容：展现了一位开朗的建筑师（图一），黑框眼镜，纯黑精致穿搭，他被放在一个哑光半透明的展示盒里，玻璃上贴着一张白色的小标签，上面写着“建筑如人生，人生如建筑”。自信地坐在一把设计大师设计的座椅上，手里拿着工作证，对着镜头微笑。这位建筑师的工作区配备了三台显示器，分别显示rhino建模、AI 和设计草图。这个极简主义的小隔间充满了结构主义+彼得库克archigram的融合风格设计：带有设计感的建筑模型、包豪斯风格的电脑桌和屏幕、画满草图的设计稿、一个毛绒绒的 CCS（图二） 吉祥物、建筑杂志、一个纯黑色锥形设计感玻璃杯，以及一块画着建筑图纸的迷你白板。一个小架子上放着一个ipadpro、一个建筑模型和一个微型 Zho（图三） 徽标。一幅镶框的建筑设计照片挂在色彩鲜艳的日历和旁边。场景采用柔和凉爽的自然光照明。整个场景使用了 包豪斯 配色方案', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1103);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('LinkedIn Photo', 'Generate a portrait ratio photo with this prompt A hyper-realistic diorama of a cheerful male office worker inside a matte translucent display box, with a small white label on the glass reading “Dream big, Stay positive.” He’s sitting confidently in a modern ergonomic office chair, smiling at the camera while holding his work ID badge. The worker’s desk setup features triple monitors showcasing Microsoft Excel, LinkedIn, and Outlook. The minimalist cubicle follows a professional aesthetic: a wireless keyboard and mouse, productivity sticky notes, printed reports, a blue ceramic coffee mug, a framed photo of his team, a small desk calendar, and a desktop organizer with pens and business cards. On the shelf, a stack of business books and a mini paperweight globe. A framed motivational quote hangs beside a monthly KPI tracker and meeting schedule. The scene is lit with soft, cool natural lighting. The entire setting uses a LinkedIn color theme—shades of blue, gray, and white—balancing a clean, focused, and modern professional atmosphere.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1104);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('把图片变成正在雕刻的雕塑', '按照以下要求为我生成： 

内容：微缩场景，雕塑家们在雕刻 Q版上传图片人物 的巨型雕塑 

风格：3D卡通Q版场景插画，1:1画幅，整体风格参考Pixar动画风，人物拥有夸张的大头比例，圆润的大眼睛、软萌的鼻子，脸上带有可爱的表情，整体质感光滑细腻，呈现出玩具般的柔软塑料感。背景为暗色纯色（如纯黑色），采用柔和棚拍光，没有明显阴影，风格干净、温暖、亲和，整体感觉超可爱、现代、数字插画感强烈', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1105);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('沙滩雕塑', '按照以下要求为我生成： 

内容：沙滩雕塑，雕塑家们在雕刻 Q版上传图片（图二）人物 的巨型雕塑

风格：参考图一参考图，真实场景插画，4:3画幅，一张极其平庸的 iPhone 照片，没有清晰的主体和取景——只是一张漫不经心的快照。照片略带运动模糊，由于阳光不均匀而略微曝光过度。角度很尴尬，构图毫无章法，整体效果极其平庸', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1106);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('速效快乐胶囊', '一颗上为星巴克绿下为透明的小药丸，上面印有星巴克logo，里面有很多咖啡豆

说明（小字）：请在悲伤难过时服用，一日三次，一次两粒

购买按钮 和 药丸颜色一致，下面价格：$9，请遵循医嘱酌情购买', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1107);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('“去 AI 感”密码', '把图片变成：一张极其平庸的 iPhone 照片，没有清晰的主体和取景——只是一张漫不经心的快照。照片略带运动模糊，由于阳光不均匀而略微曝光过度。角度很尴尬，构图毫无章法，整体效果极其平庸', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1108);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('微型立体场景', '微型立体场景呈现，运用移轴摄影的技法，呈现出Q版【孙悟空大闹天宫】场景', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1109);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('时尚杂志的封面', '《VOGUE》杂志封面：来自 League of Legends 的 Ashe - The Frost Archer 化身为高级时装模特。写实肖像，突出她标志性的白色长发、锐利蓝眼和冰霜女王般的冷艳气质。简约背景，专业摄影，身着融合了冰霜元素和高级定制风格的优雅紧身服饰。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1110);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('微观世界', '一个逼真且充满趣味的微型现代咖啡馆，热闹地呈现在一个盛满咖啡的马克杯里。这微缩咖啡馆包含一个迷你吧台，上面可能有微小的咖啡机和磨豆机，几张小桌子旁坐着微缩的顾客人偶，墙上（马克杯内壁）或许有迷你的菜单板或装饰画。真实的咖啡液面构成了咖啡馆的"地板"，上面可能还漂浮着微小的"拉花"图案。马克杯放在一张咖啡桌或吧台上，旁边可能是一个真实的羊角面包、笔记本电脑或糖罐，形成了微缩商业空间与日常饮品间的超现实对比。超写实风格、微距摄影、浅景深（焦点集中在咖啡馆内生动的场景和人物上）、明亮而柔和的、模拟咖啡馆的自然采光或室内灯光、高细节（体现在微缩设备的金属质感、人物的姿态和咖啡馆的装饰细节上）。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1111);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('3D 图标', '将这套图标转换为 C4D 渲染的 3D 图标，材质参考第二张图，所有图标都具有 3D 感和等距、体积感', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1112);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('微观世界', '一幅极简风格的等距 3D 插画，描绘了一个隐藏在老旧的米色电脑主机箱（典型的 90 年代末/2000 年代初办公室风格，ATX 结构）内部的微型、极致宁静的解压绿洲——一个日式枯山水庭院。整体感受： 带有轻微的 3D 质感和些许塑化感，如同一个藏在冰冷科技外壳下的温暖秘密、一个精巧的桌面立体模型。这个场景在象征着工作压力与束缚的电脑主机内部，构建了一个代表内心平静与精神自由的禅意空间，形成了强烈的视觉与情感对比。非常适合需要片刻宁静的现代都市人、办公室职员、微缩模型与日式美学爱好者，以及欣赏探讨工作、生活与内心世界关系的数字艺术作品的人们。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1113);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('3D 图标', '为第一张图片加上类似第二张的材质和光效，让他更像 C4D 渲染的结果', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1114);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('照片涂鸦玩法', '用蓝色画笔画一些可爱的涂鸦与画面主体产生互动，可以是人物也可以是动物或者其他东西，生成 2:3 图片，笔触的质感强一些', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1115);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('萌化电影剧照', '一个充满氛围感的电影中近景镜头，戏仿《The Godfather》中 Don Vito Corleone 在他昏暗办公室里的经典场景。一只体型稍大的泰迪熊，穿着深色西装，威严地坐在一张迷你办公桌后面，爪子里可能抱着一只更小的毛绒玩具（模仿猫）。房间光线昏暗，运用强烈的明暗对比（chiaroscuro），营造出一种既有权力感、沉思感，又不失泰迪熊固有可爱的奇特融合。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1116);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('明信片', '帮我把这张照片做成一张 3:2 的明信片，左边是一幅 扁平多色插画风格（参考某某图）的画面，插画内容参考这张照片，比如：建筑/风景/人物等细节，插画的边缘请做成 不规则异形边框，右边用手写风格英文写一句和「XX」相关的名言，并贴上一枚用原图生成的单色风格邮票，邮票右上角，邮编写 XXXX，盖上邮戳。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1117);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('邮票', 'Turn my 4 images into 4 classic, single-color postage stamps using detailed lines and shading. Give each their own color, Add a stamp value and fitting vintage-style text based on the subject. Make the image 3:4', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1118);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('照片涂鸦玩法', '生成图片，把它打印出来，然后用红墨水疯狂地加上手写中文批注、涂鸦、乱画，如果你想的话，还可以加点小剪贴画', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1119);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('主题键帽', '一幅极简风格的等距 3D 插画，展示了一个安装在定制键盘上的、Q 版"医师永真"造型的 3D 键帽。键盘采用温暖的浅棕色木纹外壳。此键帽严格控制在标准 1u 键位尺寸内。Q 版永真的造型紧凑地设计在键帽基座上，身体和头部构成了键帽的主体和主要的按压区域。她捧着的葫芦或持握的刀柄等细节被巧妙地融入整体轮廓，避免过多向侧面伸出。其姿态和服饰细节在有限空间内被精心还原。柔和的光线突显其文静气质。整体在展现角色温柔可爱的同时，确保了键帽的实用性和安装兼容性。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1120);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('主题键帽', '一幅等距3D插画描绘了被掀开的键盘键帽下，一个微型玩家正坐在迷你驾驶舱里打游戏，并将键帽内侧当作发光的屏幕。带有轻微的 3D 质感和些许塑化感，使整个场景如同一个为游戏玩家量身定做的、极其精巧的立体模型。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1121);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('手绘风格的信息图卡片', '创作一张手绘风格的信息图卡片，比例为9:16竖版。卡片主题鲜明，背景为带有纸质肌理的米色或米白色，整体设计体现质朴、亲切的手绘美感。 卡片上方以红黑相间、对比鲜明的大号毛笔草书字体突出标题，吸引视觉焦点。文字内容均采用中文草书，整体布局分为2至4个清晰的小节，每节以简短、精炼的中文短语表达核心要点。字体保持草书流畅的韵律感，既清晰可读又富有艺术气息。 卡片中点缀简单、有趣的手绘插画或图标，例如人物或象征符号，以增强视觉吸引力，引发读者思考与共鸣。 整体布局注意视觉平衡，预留足够的空白空间，确保画面简洁明了，易于阅读和理解。 <h1><span style=""color:red"">「认知」</span>决定上限 <span style=""color:red"">「圈子」</span>决定机会</h1> - 你赚不到「认知」以外的钱， - 也遇不到「圈子」以外的机会。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1122);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('手帐玩法', '请生成一张图片，模拟在一张略带纹理的纸张（比如米黄色或浅棕色）上手写的关于景区 [请在此处替换为景区名称] 的讲解笔记。图片应呈现旅行日志/拼贴画风格，包含以下元素：用手写字体（比如蓝色或棕色墨水）书写景区名称、地理位置、最佳游览季节、以及一两句吸引人的标语或简介。包含几个主要看点或特色的介绍，使用编号列表或项目符号（例如：[列举2-3个具体看点，如"奇特的岩石形态"，"古老的传说"，"独特的植物"等]），并配有简短的手写说明。用红色笔迹或其他亮色圈出或用箭头指向特别推荐的地点或活动（例如 [列举1-2个推荐项]）。穿插一些与景区特色相关的简单涂鸦式小图画（例如：[根据景区特色想1-2个代表性图画，如山峰轮廓、特色动植物、标志性建筑等]）。点缀几张关于该景区的、看起来像是贴上去的小幅照片（可以是风景照、细节照，风格可以略显复古或像宝丽来照片）。 整体感觉要像一份由热情导游或资深游客精心制作的、生动有趣的个人导览手记。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1123);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('手帐玩法', '生成一张图片，宽高比为 2:3，图片内的文字请使用英文。这张图片要模拟一位读者为小说《The Shadow over Innsmouth》制作的个人笔记页面。风格： 拼贴画/剪贴簿美学，手绘元素与粘贴物品混合，背景为有纹理的纸张（例如像 Moleskine 笔记本或牛皮纸）。请包含以下元素：手写引语： 几段来自小说的经典或有冲击力的英文句子，用清晰但带有个人风格的手写字体书写。人物涂鸦： 2-3位主要人物的简单涂鸦式头像速写，不必非常写实，更像是快速的印象捕捉。人物关系图： 在人物涂鸦之间绘制箭头，并附有简短的手写英文文字标签，说明他们之间的关系（例如："Siblings", "Lovers", "Mentor & Student", "Rivals"）。粘贴的书页一角： 一小块看起来很逼真的、模拟从实际小说书页上撕下或剪下的角落（上面能看到一些印刷的英文文字），看起来像是用胶带或胶水贴在笔记页面上的。（可选）批注： 可能在引语或人物旁边有一些小的手写笔记或问号。布局： 各元素应有机地排列，或许可以略微重叠，营造出一种经常使用的个人日记页面的感觉。整体感觉： 引人思考的，分析性的，个人化的，视觉上吸引人的。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1124);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('游戏角色', '双重曝光，融合，混合，叠加双重曝光图像，双重曝光风格，展现了智慧的兽人萨满萨尔（高尔）剪影的奇妙双重曝光构图，与他旅程中那些视觉冲击力强、标志性的艾泽拉斯景观和符号和谐地交织在一起。奥格瑞玛宏伟的红色尖塔和崎岖的峡谷，旋转天空下纳格兰翠绿的浮岛和先祖之魂，以及噼啪作响的元素能量（闪电、大地、水之漩涡）通过他形象的肌理向外回响。或许毁灭之锤那标志性的形状，或是部落/霜狼氏族的标志被巧妙地融入其中。这增添了领导者遗产、萨满之力以及部落韧性的层次感。背景保持着鲜明的对比，营造出美丽的张力，将所有焦点吸引到层次丰富的双重曝光上。其特点在于萨尔剪影内部丰富而略带粗犷的全彩色方案（大地色调、部落红、元素蓝与橙），以及用智慧与原始力量勾勒出每一处轮廓的有力而刻意的线条。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1125);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('手写笔记风格图片', 'Create concise, visually structured notes on the topic ''{{topic}}''. Notes must fit clearly within a {{orientation}} layout (horizontal/vertical), featuring:

- Moderate Font Size: Comfortable readability.
- Clear Structure:
  - Main points highlighted with "background colors" or "wavy underlines~".
  - Regular notes in standard ink.
  - Emphasis notes in a different ink color.
- Illustrations:
  - Include relevant sketches or hand-drawn style illustrations.
  - Allow fountain pen-style doodles or annotations directly on illustrations.
- Annotations:
  - Simulate notes, corrections, and additional quirky doodles resembling spontaneous annotations, using marker pen style.
  - Incorporate collage-style photo extracts relevant to the topic, annotated or doodled upon.
- Language Text Accuracy Constraint (Strict):
   - When generating text in ''{{language}}'', abide by recognized dictionaries and standard grammar rules.
   - For languages like 中文 (Chinese) or others with complex scripts:
     - Ensure each character or symbol is correct, standard, and used appropriately.
     - Double-check stroke order, avoid non-existent variants, and verify usage before finalizing the notes.

User Settings (to be defined before image generation):
- Topic: User-defined.
- Orientation: Horizontal or Vertical.
- Language: English/中文 or any chosen language.
- Color Scheme: Main notes, emphasis notes, highlight style.
- Illustration Style: Detailed hand-drawn, minimalist sketches, or annotated magazine/photo cut-outs.

Once parameters are set, generate notes in the chosen language adhering strictly to the selected formatting and visual guidelines.', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1126);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('旅游手账插画', '绘制一张色彩鲜艳、手绘风格的北京旅游手账插画，仿佛由一位充满好奇心的孩子用蜡笔精心创作。画面整体用柔和温暖的黄色背景，搭配鲜明的红色、蓝色、绿色等亮丽颜色，营造温馨而充满童趣的氛围。

插画中间绘制一条蜿蜒曲折的旅行路线，用箭头和虚线标记出各个经典地点，沿途包括：
- “第一站：吃碗老北京炸酱面！”
- “第二站：登顶景山，看紫禁城全景！”
- “第三站：逛逛神秘的故宫，注意：人超多！”
- “第四站：吃个冰糖葫芦，逛进胡同！”
- “第五站：去天坛，和爷爷奶奶一起晨练！”
- “第六站：到北海公园划船赏白塔！”
- “第七站：天安门前自拍打卡！”
- “第八站：去长城爬一爬，做个小勇士！”
- “最终站：尝一口地道的北京烤鸭，再买点纪念品回家！”

插画周围布满趣味元素：
- 拿着冰糖葫芦、吃着冰淇淋的开心小朋友；
- 指示牌：“小心迷路！”，“注意人流！”；
- 天安门、故宫、长城等经典地标用简单童趣风格画出；
- 贴纸式标语：“北京旅行记忆已解锁！”、“北京美食大冒险！”；
- 可爱的北京特色美食小图标（炸酱面、冰糖葫芦、烤鸭）；
- 欢乐的感叹：“原来北京这么好玩！”、“我还要再来一次！”

整体风格可爱而有趣，构图饱满生动，文字采用简洁可爱的手写体，仿佛带人进入一段童真又难忘的北京旅行回忆！', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1127);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('Q版中式婚礼', '将照片里的两个人转换成Q版 3D人物，中式古装婚礼，大红颜色，背景“囍”字剪纸风格图案。 服饰要求：写实，男士身着长袍马褂，主体为红色，上面以金色绣龙纹图案，彰显尊贵大气 ，胸前系着大红花，寓意喜庆吉祥。女士所穿是秀禾服，同样以红色为基调，饰有精美的金色花纹与凤凰刺绣，展现出典雅华丽之感 ，头上搭配花朵发饰，增添柔美温婉气质。二者皆为中式婚礼中经典着装，蕴含着对新人婚姻美满的祝福。 头饰要求： 男士：中式状元帽，主体红色，饰有金色纹样，帽顶有精致金饰，尽显传统儒雅庄重。 女士：凤冠造型，以红色花朵为中心，搭配金色立体装饰与垂坠流苏，华丽富贵，古典韵味十足。', '', '', 'awesome-gpt4o-image-prompts', '["gpt4o"]'::jsonb, 'https://github.com/ImgEdify/Awesome-GPT4o-Image-Prompts', 1, 1128);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('VR 头显爆炸视图海报', '{
  "type": "产品爆炸视图海报",
  "subject": "VR 头显",
  "style": "简洁的高科技 3D 渲染，摄影棚灯光，发光装饰",
  "background": "{argument name=\"background color\" default=\"柔和的紫蓝色渐变\"}",
  "header": {
    "logo": "∞ {argument name=\"product name\" default=\"Meta Quest 3\"}",
    "subtitle": "{argument name=\"main catchphrase\" default=\"以全新的结构，重塑全新的现实。\"}"
  },
  "layout": {
    "centerpiece": "VR 头显的垂直堆叠爆炸视图，展示了 9 层不同的内部组件：外壳、摄像头传感器、带芯片的主板、Pancake 透镜、内部框架、电池组、侧带、顶部头带和面部接口衬垫。",
    "callout_labels": {
      "count": 8,
      "left_side": [
        "Snapdragon® XR2 Gen 2\n卓越的处理性能，带来实时沉浸体验。",
        "可调节 IPD 机构\n为广大用户提供舒适的佩戴感。",
        "精密设计的头带\n追求舒适与稳定的工程学设计。"
      ],
      "right_side": [
        "前面板\n精致的设计与优化的重量平衡。",
        "追踪摄像头\n实现高精度的位置追踪与环境感知。",
        "Pancake 透镜\n轻薄设计，提供广阔视野与清晰画质。",
        "高性能电池\n优化电源设计，支持长时间续航。",
        "柔软的面部接口\n确保长时间佩戴依然舒适。"
      ]
    },
    "footer": {
      "left_text_block": {
        "headline": "{argument name=\"bottom headline\" default=\"体验，源于结构的进化。\"}",
        "body": "每一个零件都蕴含着支撑沉浸式体验的前沿科技与匠心设计。Meta Quest 3 从内部构建未来，为您带来超乎想象的体验。"
      },
      "right_logo": "∞ Meta"
    }
  }
}', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/⭐-Featured-gold)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1129);
