INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('动漫武术对决', '一幅极具动态感的动漫插画，描绘了两名少女在传统木质道场内进行激烈武术对决的场景。在前景中，一名留着 {argument name="character 1 hair" default="黑色高丸子头配红色丝带"} 的少女摆出强有力的低位武术架势，正奋力挥拳。她身穿 {argument name="character 1 outfit" default="带有红色流苏的白色中式上衣和红色宽松长裤"}，强烈的红色能量斩击环绕着她挥动的四肢。在右侧半空中，一名留着 {argument name="character 2 hair" default="浅紫色双丸子头"} 的少女优雅地跃起，自信地微笑着，身穿 {argument name="character 2 outfit" default="带有金色刺绣的深绿色连衣裙和黑色紧身裤"}，伴随着扫过的蓝色水流状能量轨迹。背景是质朴的木质寺庙内部，上方悬挂着一块写有“{argument name="sign text" default="武術会"}”的醒目招牌。场景充满了爆发性的动作感，飞扬的尘土、破碎的木质地板、发光的彩色粒子特效，以及将角色与精细背景完美区分开来的戏剧性低角度光影。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/⭐-Featured-gold)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1133);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('3D 石阶演化信息图', '{
  "type": "演化时间轴信息图",
  "instruction": "以 REFERENCE_0 作为结构基础，将平面矢量设计转化为高度逼真的 3D 信息图。将平滑的坡道替换为独特的石阶，并将所有生物升级为照片级真实的 3D 模型。",
  "style": {
    "background": "{argument name=\"background style\" default=\"复古纹理羊皮纸\"}",
    "staircase": "{argument name=\"staircase material\" default=\"逼真的纹理石块\"}",
    "subjects": "{argument name=\"organism style\" default=\"高度精细的照片级真实 3D 渲染\"}"
  },
  "layout": {
    "main_title": "{argument name=\"main title\" default=\"人类演化\"}",
    "sections": [
      {
        "position": "左侧边栏",
        "count": 8,
        "labels": ["L0: 单细胞生命", "L1: 多细胞生物", "L2: 动物界", "L3: 脊索动物", "L4: 上陆革命", "L5: 哺乳纲", "L6: 人科演化", "L7: 智人纪元"]
      },
      {
        "position": "右上角",
        "title": "获得的功能 / 失去的功能",
        "description": "带有加号和减号图标的图例"
      },
      {
        "position": "底部中心",
        "title": "演化关键里程碑",
        "count": 6,
        "description": "包含 6 个展示从猿到人演化剪影图形的时间轴"
      }
    ],
    "centerpiece": {
      "description": "蜿蜒的石阶，共有 25 个编号台阶，展示特定生物。",
      "count": 25,
      "notable_elements": [
        "第 07 阶: 水母",
        "第 09 阶: 菊石",
        "第 10 阶: 三叶虫",
        "第 24 阶: 直立行走的人类",
        "第 25 阶: {argument name=\"future evolution concept\" default=\"带有问号的发光宇宙剪影\"}"
      ]
    }
  }
}', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/⭐-Featured-gold)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1134);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - Q 版早安问候贴纸', '创作一张可爱的 Q 版动漫贴纸插画，背景为黑色，形状为带有厚白色外边框和细青色轮廓线的模切乙烯基贴纸。主体是一位充满活力的 Q 版虚拟歌手女孩，拥有 {argument name="hair color" default="青绿色双马尾"}，大而有神的青色眼睛，一只眼睛眨着，脸颊红润，嘴角带着灿烂的笑容。她戴着带有青色装饰的大号黑色耳机，右侧别着一个小向日葵发饰。她身穿白色连帽衫，袖口和下摆为青色，胸前有一个红绿相间的小徽章，双马尾上系着小小的桃色蝴蝶结，穿着白袜和青色鞋子。姿势设定为充满活力地漂浮着，一只手举起挥动，五指清晰可见，另一只手兴奋地握拳。在左下角前景处放置一个安装在吊杆上的黑色录音室麦克风，朝向她。在她身后，添加一个带有扇形云朵形状的大型圆形对话气泡标志，白色填充，青色边框，并点缀柔和的彩色纸屑。在气泡内，用暖橙黄色书写大号且圆润的日文文本 {argument name="greeting text" default="おはよー"}，并带有白色内轮廓、深棕色描边和柔和的阴影。在贴纸周围添加 8 个装饰性图案：左上角 1 个橙色爪印太阳，右上角 2 个黄色感叹射线，文本附近 1 个黄色闪光，以及右下角附近的 2 朵粉色花朵、1 朵青色花朵和 1 颗黄色星星。采用简洁的 Q 版吉祥物风格，圆润的比例，粗线条，柔和的赛璐珞阴影，光泽高光，营造俏皮的早安问候氛围，高分辨率，无水印，无多余文字。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1135);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - Q 版少女探头边框', '在干净的纯白背景上创作一张可爱的 Q 版动漫插画，中心留出大面积空白，仿佛角色正从页面边缘探出头来。使用 4 个相同的 Q 版少女形象，{argument name="character name" default="一只企鹅主题的银发 Q 版少女"}，每个角色都被画布边缘部分裁剪：1) 一个倒立的头部从左上方边缘探出，仅露出头部和一点衣领；2) 一个侧脸从左下象限边缘探出，一只小手比着剪刀手；3) 一个侧脸从右上象限边缘探出，发间可见一个小小的蓝黄配色企鹅配饰；4) 一个较大的正面 Q 版形象从底部中心探出，露出头部到举起的小手。少女拥有圆脸、巨大的蓝灰色亮眼、柔和的腮红、小巧的微笑嘴唇、短波波头 {argument name="hair color" default="银白色头发，发梢带有浅青蓝色"}、圆润顺滑的刘海以及精致的蓝色线条点缀。服装暗示应为深海军蓝和蓝色，带有水手服或企鹅风格，但大部分衣物被裁剪。风格：精致的日系动漫贴纸艺术、柔和的赛璐珞阴影、干净的细轮廓线、头发和眼睛上的光泽高光、淡蓝色点缀，营造出可爱俏皮的晨间问候氛围。构图应显得宽敞简约，无文字、无边框、无水印，除 4 个探头的 Q 版形象和小企鹅配饰外，不包含任何额外角色或物体。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1136);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 暗黑奢华红光肖像', '创作一张 {argument name="subject" default="一位自信的年轻女性"} 的超写实电影级摄影棚肖像，呈现暗黑奢华的红光美学。构图为垂直特写半身像，略微偏左居中，主体面向镜头，双肩微侧。她留着湿润、凌乱的齐肩 {argument name="hair color" default="深金色头发，带有浅金色挑染"}，皮肤质感自然，双唇微启，表情冷静而有力。佩戴一副时髦的黑色长方形深色墨镜，身穿质感厚实的黑色大廓形针织毛衣。背景使用近乎黑色的深红色摄影棚背景，背后和发丝周围环绕着极具戏剧性的深红色轮廓光，勾勒出鲜明的红色边缘和飞扬的发丝高光。面部保持自然的前侧光照明，具有柔和的电影级对比度，展现细腻的毛孔、真实的唇部质感和光泽的发丝。氛围：神秘、优雅、有力、高级时尚大片、暗黑奢华。相机风格：85mm 人像镜头，浅景深，面部和墨镜焦点清晰，阴影丰富，高动态范围，专业摄影棚布光，无文字，无水印，无多余物体。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1137);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 皮克斯风格 3D 角色贴纸网格', '目标：创作一张优质的皮克斯风格 3D 角色贴纸，主角为同一位具有辨识度的成年男性，设计参考高质量的即时通讯软件贴纸。

画布：垂直 4:5 构图，超高分辨率，干净的暖奶油色背景，柔和的摄影棚灯光，无文字，无水印。

布局：将 9 个独立的半身贴纸整齐地排列在 3×3 网格中，间距均匀。每个贴纸都有厚实的白色模切轮廓和细微的柔和投影，仿佛是贴在奶油色背景上的乙烯基贴纸。

角色细节：角色为 {argument name="character identity" default="一位具有辨识度的类似 Elon Musk 的中年男子"}，肤色白皙，留着短而蓬松的后梳 {argument name="hair color" default="深棕色头发"}，圆脸，留有轻微胡茬，眉毛生动，呈现出友好的皮克斯风格 3D 卡通形象。在所有 9 个贴纸中保持相同的面部结构、发型、年龄和身份特征。

贴纸数量与表情：包含 9 个贴纸，每个网格单元一个：
1. 左上：放松的闭嘴微笑，身穿黑色皮夹克。
2. 中上：张嘴大笑的表情，身穿黑色连帽衫。
3. 右上：戴着黑色太阳镜的酷炫自信表情，身穿黑色外套。
4. 左中：愤怒皱眉的表情，身穿深色衬衫。
5. 正中：双眼圆睁、小嘴微张的惊讶表情，身穿深色夹克内搭浅色衬衫。
6. 右中：向上侧方凝视的沉思姿态，一手托腮，身穿海军蓝毛衣。
7. 左下：俏皮的眨眼并带有轻微坏笑，身穿橄榄绿夹克。
8. 中下：充满爱意的表情，双眼为红色爱心，双手比出手指爱心手势，外加 2 个漂浮的小红心图标，两侧各一个。
9. 右下：友好的点赞手势并带有温和微笑，身穿棕色夹克。

视觉风格：优质精美的 3D 卡通渲染，皮克斯风格比例，平滑的皮肤阴影，写实但风格化的头发，明亮的眼睛，温暖的高光，清晰的贴纸边缘，柔和的阴影，迷人的表情包风格。

约束条件：在整个网格中保持一致的头部大小和裁剪风格；仅使用半身像；保持背景简洁；不要添加标题、标签、徽标、额外角色或其他贴纸。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1138);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 凝望巨大金月的女子', '创作一张照片级真实的电影感肖像，画面主体为 {argument name="character description" default="一位皮肤白皙哑光、留着超长直黑发、佩戴深色边框眼镜的年轻女性"}，半身侧面像，面向左侧，站在户外广袤的星空下。她身穿 {argument name="outfit" default="一件简约的白色修身短袖 T 恤和高腰深色长裤"}。她微微仰头，敬畏地凝视着身后左上方一轮巨大的发光 {argument name="moon color" default="金色"} 满月，月亮巨大，占据了大部分背景上方。月球细节需极度丰富，可见陨石坑、月海、表面纹理以及柔和的辐射光晕，在她的头发、眼镜、脸颊、肩膀和手臂上投射出温暖的轮廓光。使用深藏青色的太空背景，点缀无数繁星，左下方有淡淡的银河状星云。采用 3:4 竖构图，女子位于画面右侧，月亮占据左侧及上方中心。保持戏剧性且真实的灯光效果，冷蓝色阴影与暖金色高光形成对比，女子与月亮焦点清晰，具有微妙的景深感，皮肤纹理自然，画面中不含任何文字、Logo 或水印。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1139);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 基于姿势参考生成动漫角色', '以提供的参考图作为姿势和构图指南，重新生成一张精致的全身 2D 动漫插画。保持相同的害羞低头姿势：头部低垂，肩膀略微耸起，双手背在身后，双腿并拢，双脚朝前。保留参考图中的简约服装轮廓，并以精细的动漫风格进行渲染：一件带有抽绳和前袋的超大款 {argument name="hoodie color" default="白色"} 连帽衫、宽松的 {argument name="pants color" default="黑色"} 长裤以及厚底运动鞋。将块状的 3D 模型转化为精致的动漫少女，留着 {argument name="hair color" default="浅棕色"} 波波头，配以柔和的刘海、淡淡的腮红，以及向下注视的 {argument name="eye color" default="粉色"} 双眼。使用柔和的 {argument name="background color" default="淡粉色"} 背景，采用细腻的赛璐璐阴影、干净的线条、自然的布料褶皱以及淡淡的地面投影。保持摄像机视角略高于角色，使全身垂直居中。请勿添加文字、道具、额外角色或复杂的背景。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1140);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 温馨室内嘟嘴自拍人像', '创作一张逼真的竖版特写自拍人像，主角是一位年轻的东亚女性，留着 {argument name="hair color" default="深棕色"} 的齐肩微乱层次感发型，配有轻薄的空气刘海。她戴着透明圆框眼镜，佩戴珍珠耳钉，身穿简约的白色细肩带背心。她以略高的自拍视角正对镜头，构图紧凑，从上胸部到头顶居中拍摄。皮肤质感自然柔和，拥有一双棕色大眼睛，表情可爱且微微嘟嘴，脸颊鼓起，双唇紧闭，看起来有些担忧或闷闷不乐。场景设定在夜晚现代公寓或咖啡馆风格的厨房/客厅，采用温暖舒适的室内灯光，整体色调为奶油米色，背景中有模糊的吊灯光晕、柔软的沙发或椅子、木质橱柜，左侧点缀着一株绿植。背景需进行强烈的虚化处理，呈现浅景深效果，同时面部和眼镜细节清晰锐利。风格应为照片级逼真的智能手机自拍人像，暖色调，柔和的焦外成像，氛围亲密随性，无文字，无水印。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1141);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 黄金时刻特写人像', '超写实黄金时刻特写人像，拍摄对象为户外的一位 {argument name="subject" default="年轻女性"}，双眼轻闭，面带柔和宁静的微笑，脸庞微微向上仰起，迎向温暖的落日余晖，凌乱随风飘动的 {argument name="hair color" default="深棕色"} 发丝自然地拂过脸颊，被阳光亲吻的肌肤散发光泽，呈现出真实的纹理与细微的雀斑，妆容清透，双唇水润，身穿一件带有精致领口的 {argument name="clothing" default="宽松白色亚麻衬衫"}，电影级的暖琥珀色阳光勾勒出迷人的高光与柔和的阴影，浅景深效果，背景为纯净的蓝天，充满梦幻的夏日氛围，真实自然的表情，超精细皮肤纹理，高动态范围，85mm 人像镜头，f/1.8，专业时尚摄影，自然色彩分级，柔和对比度，编辑类生活方式美学，照片级真实感，8K 分辨率，RAW 原始画质。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1142);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 赛博俱乐部动漫时尚肖像', '创作一张时尚的竖版动漫肖像，主角为 {argument name="character name" default="一位时尚的年轻女性"}，构图从大腿上部到头部，居中于干净的白色摄影棚背景前。她拥有 {argument name="hair color" default="凌乱的黑色短发，带有电光蓝和紫罗兰色的挑染"}，肤色苍白发光，嘴唇光泽饱满，一只深邃的紫罗兰色眼睛被刘海半遮。她佩戴着大型金属质感赛博朋克头戴式耳机，耳机上反射着青色和洋红色的光芒；双手轻托着一副镜面飞行员墨镜，墨镜镜片中精确反射出拥挤的霓虹演唱会现场，包括举起的双手、舞台灯光、蓝紫色激光以及发光的城市轮廓。她的装束由 3 件核心服饰/配饰组成：一件修身黑色低领背心裙、一件超大款半透明虹彩全息夹克（带有拉链和圆形金属扣），以及那副反光飞行员墨镜。让她呈现出自信酷炫的表情，一只手抬起墨镜左侧，另一只手触碰耳机附近的右侧太阳穴；展示出修长且富有光泽的深色指甲。采用高定赛博俱乐部美学，超精细的精致数字动漫插画，线条锐利，皮肤渲染柔和，边缘光感明亮，呈现青色、紫罗兰色、粉色和银色的棱镜高光，高对比度，焦点清晰，编辑级特写构图，镜片反射外无额外角色，无可见文字，无水印。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1143);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 金色晨曦动漫卧室肖像', '创作一幅光影明亮、细节丰富的动漫插画，主角为 {argument name="character name" default="Kurōdo Shion"}，一位灵感源自 Claude 的原创角色，场景设定在柔和的清晨卧室中。角色是一位美丽的年轻女性，拥有 {argument name="hair color" default="长长的银金色秀发"}，发丝自然垂落，一侧带有编织发冠细节，琥珀金色的双眸，精致的腮红，以及温柔慵懒的微笑。她跪在凌乱的白色床铺上，身体微微前倾，姿态优雅放松，身穿一件超大款露肩白色缎面衬衫裙，深领口，宽松袖口，带有精致的金色滚边和优雅的金链装饰。画面中需包含 4 个清晰可见的珠宝元素：一条星形吊坠项链、一条十字架吊坠项链、一只星形垂坠耳环，以及别在衣物上的金链装饰。房间沐浴在身后大窗透入的温暖金色晨光中，配有透明窗帘、发光的尘埃微粒、奶油色高光和柔和的朦胧感。背景细节应包含 4 个卧室装饰元素：一个床头柜、一幅墙面挂画、一个花瓶或灯饰，以及窗边的一束白花。采用浪漫的象牙白、香槟金配色；绘画风格的动漫渲染；光泽感发丝；柔和的皮肤阴影；电影级背光；浅景深；梦幻空灵的氛围；垂直肖像构图。避免出现文字、水印、额外角色或现代杂物。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1144);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 低角度办公室时尚人像', '创作一张写实风格的全身时尚人像，拍摄对象为一名站在现代开放式办公室里的年轻日本上班族。采用极低的地面视角拍摄，配合轻微的广角透视，使她的腿部显得修长，天花板和办公桌在背景中呈现出强烈的纵深感。她留着 {argument name="hair color" default="深棕色"} 的头发，梳成随性柔和的盘发并配有轻薄的刘海，面带温柔友好的微笑，妆容自然，佩戴着精致的项链。服装：浅灰色 V 领针织衫内搭干练的白色翻领衬衫，挂着蓝白相间的 YouMind 员工工牌，下身穿着白色短款百褶裙，搭配黑色透明丝袜和黑色亮面高跟鞋。让她自信地站立，一只手轻触裙边，另一只手臂自然垂在身后，直视镜头。办公室背景应包括成排的办公桌、黑色旋转办公椅、白色抽屉柜、大窗户、荧光天花板面板和空调通风口，所有背景元素均经过柔化处理，呈现浅景深效果。采用写实光影、柔和的室内自然光、细腻的背景虚化，主体细节丰富，皮肤纹理自然，织物褶皱真实，营造出整洁的企业氛围。采用 2:3 竖构图，主体居中，全身可见（从头部到鞋子），画面中无其他人物，除模糊的工牌外无任何可读文字。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1145);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 高角度生活化卧室自拍', '超写实生活化自拍，一位美丽的年轻女性（面部参考提供的图像）坐在白色床上，从高角度手持相机拍摄，面带柔和温暖的微笑直视镜头。{argument name="hair style" default="长波浪深棕色头发"} 垂在一侧肩头，自然的透亮肌肤，精致淡妆，金色椭圆形耳环，精致项链，{argument name="outfit" default="黑色罗纹无袖背心，白色休闲短裤"}。{argument name="setting" default="舒适的现代卧室"}，背景是白色枕头和奶油色墙板。柔和的晨光透过窗户洒入，温暖的金色调，浅景深，真实的皮肤纹理，电影级摄影，35mm 镜头，f/2.0，高细节，照片级真实感，奢华生活美学，8K。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1146);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 复古宝丽来咖啡馆快照', 'create image 4:5
一张呈现为逼真复古宝丽来即时成像照片的美学自然咖啡馆快照，画面中一位 {argument name="subject" default="年轻女性"} 正坐在餐桌旁的木椅上，背靠咖啡馆的大窗户，身穿 {argument name="outfit" default="修身无袖深炭灰色针织短上衣，高腰深蓝色牛仔裤"}，佩戴着粗款金色手镯。她双手自然地在胸前拿着汉堡，身体朝向餐桌，头部转向镜头，双眼微睁，嘴唇微张，仿佛被拍照的人意外捕捉到。短发层次感波浪卷发，凌乱的碎发随风飘动，部分遮住了一只眼睛，自然的高级感妆容，带有光泽的自然唇色。温暖的复古咖啡馆内饰，深绿色墙壁，深红色窗框，明亮的过曝窗户，窗外模糊的树木和车辆，木质餐桌上摆放着饮料、盘子和调味品，柔和的背景虚化营造出深度感。平视视角自然手持构图，温暖的电影感日光，细腻的轮廓光，微妙的胶片颗粒，哑光即时成像胶片质感，怀旧的大地色调。印制为带有干净白边和底部较宽边框的真实宝丽来照片。底部边框上有黑色墨水手写文字：“my favorite view ♡”。右下角带有小型复古日期戳：“{argument name="date" default="06.26.2026"}”', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1147);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 山顶上的女孩', '创作一张方形电影胶片质感的照片，主角是一位 8 到 10 岁左右的东亚小女孩，她站在高山或山顶的户外，背景是广阔的开阔景观。她留着 {argument name="hair color" default="黑色短波波头，配有轻盈的刘海"}，表情平静略带忧郁，正转过头越过肩膀直视镜头。她穿着 {argument name="dress style" default="一件简约的奶油白色短袖棉质连衣裙，腰部收褶，领口带有小荷叶边"}。构图上，将她置于画面中心偏左的位置，采用从大腿中部向上的中景肖像，身体侧转，脸部面向观众。背景应展示远方朦胧的海岸线或海平线、下方深色的起伏田野和山丘，以及极其广阔且充满戏剧性的天空，云层呈蓝灰色层叠，传达出 {argument name="mood" default="开阔之地、静谧孤独以及午后宁静"} 的氛围。利用黄金时刻的暖阳从侧面照亮她的脸庞和裙子，阴影柔和，景深为浅至中等，头发带有自然的微风吹拂感，肤色真实，并呈现出怀旧的模拟胶片质感，带有柔和的颗粒感、轻微的模糊、柔和的对比度以及复古的调色风格。画面中无文字、无水印、无无关人员、前景中无建筑物。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1148);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - Q 版角色花园咖啡馆场景', '使用我的参考图片。保留其确切的面部、五官、笑容、肤色和身份特征。将主体转换为可爱的 3D 皮克斯/迪士尼风格 Q 版角色，体型为 {argument name="ethnicity" default="中等身材菲律宾裔"}，身穿她的标志性服装：{argument name="outfit top" default="棕色无袖上衣"}、{argument name="outfit bottom" default="带白色饰边的黑色短裤"} 以及白色运动鞋。

在金色的日出时分，创建一个温馨舒适的户外花园咖啡馆场景。在质朴的木桌上放置一个巨大的优雅奶油色陶瓷咖啡杯，高度与角色大致相同。Main Ingrid 站在杯子旁边，一只手轻轻靠在杯柄上，另一只手开心地挥舞着，脸上带着温暖愉悦的笑容。

咖啡冒着热气，旋转的魔法蒸汽优雅地升入空中，自然地形成了优雅的手写文字“GoodMorning”。保持“GoodMorning”文字悬浮在蒸汽上方并留有小间隙，使其保持清晰、易读且视觉效果突出。

用黄油牛角面包、曲奇饼干、散落的烘焙咖啡豆和一把小木勺装饰桌面。添加微小的蝴蝶、漂浮的闪光、发光的尘埃颗粒、柔和的焦外成像效果，以及透过茂密绿色植物和花朵射入的温暖阳光，营造出宁静而神奇的早晨氛围。

超精细 3D CGI，皮克斯动画风格，电影级构图，柔和的全局光照，温暖的金色光线，逼真的纹理，浅景深，鲜艳的色彩，高级渲染，8K，杰作，温馨，优雅，令人振奋，构图简洁，高视觉叙事性，标志性的 Mini Ingrid Universe HQ 美学。

负面提示词：模糊，低质量，多余的肢体，畸形的解剖结构，重复的对象，扭曲的面部，头部过大，斗鸡眼，糟糕的手部，主体被裁剪，水印，标志，随机文字，杂乱的构图，暗光，阴郁的氛围，色彩过饱和。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1149);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 优雅动漫女性肖像', '创作一张精致的动漫风格肖像，主角是一位美丽的年轻女性，留着 {argument name="hair color" default="暖栗棕色"} 的头发，梳成高高的凌乱丸子头，带有几缕松散的发丝和柔和的直刘海。她有着大而温暖的棕色眼睛、长睫毛、精致的妆容、红润的双颊、光泽的嘴唇，正视镜头并带着温柔自信的微笑。画面呈现她从大腿中部以上的半身像，姿态柔美而优雅，身体微微前倾，双手背在身后。她穿着一件修身的米色罗纹裹身短款上衣，短袖设计，深 V 领口，带有扇形饰边，侧面系有蝴蝶结，搭配一条高腰灰粉色半身裙。佩戴一条带有小吊坠的精致金项链。背景是一个极简明亮的房间，墙面为灰白色，左侧挂着透明窗帘，温暖的自然窗光洒入，在她的脸部、头发和衣物上形成柔和的高光。采用高细节的半写实动漫渲染，皮肤光滑，线条精炼，发丝光泽感强，阴影柔和，色调为柔和的中性色，采用 2:3 纵向构图，浅景深，氛围干净优雅，无文字，无水印。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1150);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 月下仙侠汉服肖像', '创作一张电影感竖屏特写肖像，主角为 {argument name="character name" default="一位气质空灵的东亚年轻女性"}，身着中国古代仙侠风格服饰，静坐在深夜月光笼罩的庭院中。她拥有如瓷器般白皙的皮肤、精致的五官、柔和的红唇、低垂且沉思的双眼，以及一头 {argument name="hair color" default="乌黑亮丽"} 的长发，发型半盘，几缕发丝轻垂于脸颊。额头正中点缀一朵小巧的红色五瓣花钿。她身着一件飘逸的 {argument name="robe color" default="银白色"} 汉服，面料带有细腻的提花刺绣，呈现绸缎光泽，领口层叠，袖口宽大；长袍上映衬着冷蓝色的高光。她的右手轻抬至下颌，指甲修长白皙，姿态静谧而深沉。背景极其深邃且经过柔焦处理，左侧仅可见一枝开满小白花的树枝，呈现出梦幻的虚化效果。采用情绪化的低调照明，左上方投射下冷蓝灰色的月光，伴有柔和的阴影，浅景深，真实的皮肤质感，优雅的奇幻剧风格，高端杂志摄影质感，9:16 竖构图，面部位于右上中心，无文字，无水印，无现代配饰。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1151);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - Y2K 复古胶片风车内人像', '100% 还原附件中的面部特征——眼睛、鼻子、嘴巴和脸型保持不变。{argument name="subject description" default="娇小女性，苗条身材"}。白皙、光滑、细腻、透亮的皮肤——看起来健康、有光泽感、质感柔和。轮廓分明的肩膀和锁骨。自然的素颜肤质，可见真实的皮肤纹理，光滑白皙且带有轻微质感。两颊和鼻尖晕染着柔和的粉色腮红，呈现自然的红润感。强调大而圆的浅棕色眼睛。柔粉色渐变唇妆——内侧颜色较深，向外逐渐变淡，呈现水润妆效。长款 {argument name="hair color" default="深栗棕色"} 波浪卷发，自然随性。姿势：{argument name="pose" default="坐在车内后仰，车门打开，一条腿抬起搭在车门框上"}，眼神柔和、深邃且略带浪漫，凝视镜头。窗外是深暗的红紫色夜空。直闪光照明，Y2K 胶片/数码相机风格，明亮透亮的皮肤，锐利的阴影，高对比度，深红橙色调，轻微胶片颗粒感，复古氛围。深色背景与主体形成强烈对比。半身至部分全身特写，轻微动态角度，35mm 或 50mm 镜头，浅景深，面部焦点清晰，色彩鲜艳，电影感。超写实，4K，胶片颗粒，光泽感皮肤，锐利高光，深邃阴影。纵横比 9:16 竖屏。
Negative: 动漫，卡通，3D 渲染，绘画，明亮的摄影棚灯光，塑料质感皮肤，不自然的手部姿势，手指扭曲，多指，肢体漂浮', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1152);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 都市生活男性肖像', '超写实电影感肖像，主角为 {argument name="subject" default="英俊的年轻男子"}，留着浓密且略显凌乱的深棕色头发，下颌线轮廓分明，留着淡淡的胡茬，眉毛英挺，深棕色的双眼略微看向镜头外，表情沉稳自信。他站在户外，背景是 {argument name="setting" default="现代奢华建筑"}，配有高大的混凝土立柱和深色玻璃窗。他身穿 {argument name="clothing" default="剪裁完美的纯黑色圆领 T 恤"}，凸显出他健硕的肌肉线条，佩戴着一条极简风格的银色链式项链（带有小巧的长方形吊坠）以及一块黑色不锈钢腕表。他双臂自然交叉于胸前，突显出结实的二头肌和前臂。温暖的黄金时刻阳光照亮了他面部和身体的左侧，营造出柔和的高光和真实的皮肤质感。背景采用浅景深效果，呈现奶油般的虚化感，使建筑背景保持柔和模糊。编辑级奢华时尚摄影，高级生活方式美学，超精细皮肤毛孔，逼真的发丝，细腻的面部纹理，自然色彩分级，HDR，85mm 镜头，f/1.8，平视构图，居中取景，面部焦点清晰，照片级真实感，8K，高对比度，顶级杂志画质，无文字，无水印，无畸变。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1153);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 动漫双人 Q 版肖像', '创作一张纯白色背景的方形全出血数字插画，展示动漫双人转换布局。主体是一个位于画布中心及右侧的可爱极简 Q 版动漫女孩，呈现头部到上半身的构图，拥有超大头部、窄肩、非常大的深棕色亮眼、柔和的桃色皮肤、红润的脸颊、小巧的鼻尖高光以及微张的平静小嘴。她留着 {argument name="hair color" default="深棕色近乎黑色"} 凌乱的短波波头，发丝微卷且带有碎发，中分偏分，左肩垂下一条粗松的侧辫。在辫子下端别上 1 个小巧的粉色五瓣花发夹。她穿着 {argument name="top color" default="黑色"} 极简吊带背心，带有 2 条细肩带和浅 V 领。表情应显得害羞、平静且如玩偶般精致，采用细腻的线条、柔和的水彩风格阴影、微妙的腮红渐变以及精美的动漫渲染。在左上角，包含 1 个带有细深色边框的小型圆角矩形嵌入式相框，展示同一年轻女性的写实肖像作为源参考：凌乱的深色短卷发、自然妆容、黑色吊带背心，坐在车内，面对镜头，表情平静。嵌入框宽度约为画布的四分之一，距离顶部和左侧边缘留有小间距。保持背景完全纯白，无文字、无水印、无额外配饰，且无其他角色。采用简洁的高分辨率社交媒体头像风格，使写实嵌入图与大型动漫版本在发型、服装和氛围上保持视觉一致。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","个人资料","头像"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1154);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('社交媒体帖子 - Patchouli Yukkuri 宠物店展示', '目标：创作一张写实、暖色调的照片风格图像，展示一个宠物店展示柜，里面有一只微型的 yukkuri 风格 Patchouli 角色，像小型宠物吉祥物一样骄傲地坐在书本上。

画布：横向 4:3 图像，透过透明亚克力宠物展示柜的平视视角，具有浅景深。背景显示在柔和的室内商店灯光下模糊的宠物店货架和相邻的展示柜。

主体：在展示柜中央放置一个微型圆形 Q 版头部角色，{argument name="character name" default="Patchouli"}，有着半睁的睡眼、紫色头发、粉色荷叶边睡帽，帽子上有一个橙色的小月牙装饰。她直接坐在一本深绿色、看起来很古老且带有金色装饰线条和泛黄书页的大书上，表情显得自鸣得意。

展示柜与道具：展示一个清晰的亚克力笼子隔间，可见透明面板、接缝、铰链和圆形的螺丝状连接点。地板铺着一块奶油色的毛绒垫子。包含六个清晰可见的散落笼内物品：1) 左侧一个揉皱的报纸窝，2) 左前方一个黄色编织球，3) 右侧一个揉皱的报纸窝，4) 右侧报纸上放着一把小草扫帚，5) 相邻右侧区域有一个米色格子甜甜圈宠物床，以及 6) 右边缘附近的一个蓝色编织球。保持展示柜整洁，呈现商店陈列感。

文本元素：添加四个日文文本元素作为印刷或叠加文字。1) 角色上方的一个小型漫画拟声词，读作「むきゅっ」，使用带有白色描边的粗体圆润黑色字体。2) 笼子右上方的一个矩形警告标签，写着「叩いたら\nゆんやー！」。3) 笼子左下方的一个价格牌，写着「ぱちゅりーちゃん\n当ショップ生まれ\n¥1,980」，价格居中且字号较大。4) 最右侧一个带有黑色边框的垂直白色叙述框，写着「お兄さんは\nこのぱちゅりーに\n何かを感じた」。请完全按照所示内容使用日文文本。

视觉风格：照片级真实的微缩模型，融合了微妙的动漫角色，具有真实的亚克力反光、略带深褐色的室内灯光、柔焦背景、柔和的暗角、细腻的报纸纹理，以及舒适但具有商业感的宠物店氛围。

约束条件：仅使用一个角色、一本书、一个笼子隔间作为主要焦点，以及列出的六个可见散落物品。不要添加额外的动物、人类、手部、对话气泡、标志、水印或额外的可读文本。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","社交媒体帖子"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1155);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('社交媒体帖子 - 雨中伞下的时尚封面', '创作一张方形 1:1 的时尚杂志封面肖像，主角是 {argument name="character name" default="一位开朗的日本年轻女性"}，她站在户外的小雨中，对着镜头温暖地微笑，身后撑着一把橙色雨伞。她留着直发双马尾，配有柔和的刘海和小红花发饰，妆容自然，表情如偶像般温柔。她身穿一件深翡翠绿色的中式挂脖旗袍上衣，带有金色云朵和花卉刺绣，搭配黑色蕾丝露肩袖和黑色蕾丝手套；蕾丝质感应清晰且华丽。她的双手握着伞柄，置于胸前。背景为浅景深的雨中城市街道，行人模糊，色调为冷淡的绿色和蓝色，与温暖的橙色伞面形成对比。构图为半身特写肖像，略微倾斜，脸部位于右上三分之一处，雨伞填满背景。添加 4 个可见的文字元素：1) 顶部横跨巨大的蓝色截断式刊头文字 {argument name="masthead text" default="AMEZON"}，部分被主体遮挡；2) 右上角小的手写蓝色文字 {argument name="small cover note" default="cover"}；3) 左下角白色 Logo 文字 {argument name="left footer text" default="Z-IMAGE TURBO"}，带有细下划线和微小的副标题“SINCE 2025”；4) 底部中/右侧白色 Logo 文字 {argument name="right footer text" default="GPT-IMAGE-2"}，带有细下划线和微小的副标题“SINCE 2026”。视觉风格：逼真的高质量 AI 时尚摄影，柔和的电影级布光，略微去饱和的雨天氛围，杂志编辑质感，干净的皮肤细节，锐利的蕾丝和刺绣，焦点内无其他人物，无水印，无额外文字。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","社交媒体帖子"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1156);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('社交媒体帖子 - 日落时分悬崖上的跑车', '创作一幅世界尽头的电影级写实风景场景：一辆流线型的 {argument name="car color" default="银白色"} 高性能跑车停在左侧前景的湿润黑色火山岩悬崖边缘，采用低角度四分之三后视图，车尾灯发出红光，车身反射着光泽。悬崖右侧陡峭地坠入广阔的海洋，伴有锯齿状的黑色岩壁、稀疏的草丛、从下方升起的海雾，以及远方拍打岩石的白色浪花。远处，崎岖的海岸山脉沿着左侧地平线延伸。太阳在右中地平线附近低垂，在水面上投射出灿烂的橙金色反光路径，天空布满了厚重的深蓝色风暴云，被温暖的火光穿透。强调优雅与力量感、孤独感、极致高度、电影级规模、忧郁氛围、超精细纹理、写实光影、高动态范围、广角构图，以及冷蓝色阴影与温暖日落余晖之间的戏剧性对比。画面中无人、无文字、无水印。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","社交媒体帖子"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1157);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('社交媒体帖子 - 空灵羽翼天使摄影棚肖像', '[主体] 图像 1 [签名] 在右下角放置一个小型的 {argument name="platform logo" default="Threads"} 标志，其上方用白色小号草书写着类似签名的 "{argument name="signature" default="CHAse"}"。 [主体姿势与表情] 坐在神秘的青色摄影棚空间地板上，身体微微后倾，直视镜头。右手撑地，双腿自然收拢于一侧，清澈纯净的眼神与静态的表情营造出一种梦幻而神秘的天使氛围。 [主体服饰] 身着纯白色露肩迷你裙，带有精致的蕾丝细节和荷叶边装饰。胸部和躯干部分采用微妙的半透明透视蕾丝与束腰设计，裙摆部分层叠着轻盈而丰富的褶皱，尽显优雅。背部展开一对巨大且精致的白色羽毛天使翅膀，呈现出梦幻般的视觉效果。 [发型与妆容细节] 自然整洁的黑色长发。几缕发丝顺着脸颊和肩线自然垂落，增添纯净感。妆容以白皙清透的瓷肌为底，双颊大面积强调鲜明生动的粉色腮红以增添活力，水润的粉色调嘴唇突显出透明且神秘的特质。 [灯光与布光] 柔和且具有戏剧性的背光，最大限度地展现了摄影棚的梦幻氛围。强烈的白光在背后的天使翅膀边缘闪耀，在翼尖处形成耀眼的轮廓光效果。柔和的漫射光从前方渗透，轻柔而透明地照亮了主体的皮肤和裙子的蕾丝质感。 [质感与色彩氛围] 背景深邃神秘的青色绿松石色调与天使翅膀及服饰的纯白色形成鲜明对比，营造出极其梦幻的奇幻氛围。每一片羽毛柔软舒适的质感、裙子蕾丝细腻的织物纹理，以及空气中漂浮的轻盈羽毛质感相结合，创造出如童话场景般的视觉美感。 [胶片与相机景深、角度] 使用 50mm 标准定焦镜头拍摄，参数为 f/2.0, 1/160s, ISO 200。采用略高于视线的俯拍角度，以稳定地捕捉坐在地板上的主体。应用浅景深效果，使主体和华丽的天使翅膀清晰对焦，而空中飘落的白色羽毛则呈现柔和的虚化效果，增添了神秘的空间感。 [背景元素（可选）] 干净的哑光青色摄影棚背景，无任何人工结构。白色绒毛（羽毛碎片）在主体头部周围及空气中轻柔飘落，加倍了奇幻氛围。在图像底部中心，用简洁的白色粗体字写着标志文本 "{argument name="logo text" default="ANGEL"}"。', 'https://img.shields.io/badge/Language-KO-blue', '![](https://img.shields.io/badge/Language-KO-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","社交媒体帖子"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1158);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('社交媒体帖子 - 黄金射手女神摄影棚肖像', '创建图像 [主体] 图像 1 [签名] 在右下角放置一个小型的 {argument name="platform logo" default="Threads"} 标志，并在其上方用白色小号草书写着“{argument name="signature" default="CHAse"}”作为签名。 [主体的姿势与表情] 令人着迷的上半身姿势，让人联想到神秘的女神或神话中的射手。手持一把精雕细琢的大型金弓，右手轻轻拉动弓弦，平静地注视着手部和弓。专注而冷静优雅的表情最大程度地烘托出古老的神话氛围。 [主体的服装] 身着一件带有丰富立体细节的高定礼服。上身是质感粗犷、闪烁着光泽的重工青铜金金属紧身胸衣，下身是 {argument name="outfit color" default="奶油白"} 的丝绸缎面裙，垂坠感优雅。背部有呈天使翅膀形状的白色织物装饰，结构感十足；长款华丽的金耳环和左手腕纤细的金属袖口手镯增添了神秘感。 [发型与妆容细节] 极长的深棕色发型，发量丰盈且带有浪漫的波浪卷。头发顺滑地垂在一侧肩头并延伸至背部，增添了古典美。妆容以适合柔和摄影棚灯光的透明哑光肤质为基础，深邃的阴影妆容强调了五官，搭配沉稳的干枯玫瑰色裸唇。 [灯光与指导] 精致的摄影棚漫射光从主体左上方柔和地照射下来。这种光线立体地照亮了紧身胸衣复杂的金属质感和璀璨金弓的轮廓，在主体的面部和锁骨线条上营造出柔和、平滑的高光。主体右后方投射出微妙的阴影，增加了深度。 [质感与色彩氛围] 弓和紧身胸衣粗犷、坚硬闪耀的古金金属质感与礼服丝滑、柔软的缎面质感形成奇妙对比。背景沉稳的蓝灰色调与服装的金白色调相协调，营造出一种既精致又神秘、宏大的奇幻画报氛围。 [胶片与相机景深、角度] 使用 85mm 定焦镜头拍摄，参数为 f/2.8, 1/200s, ISO 100。采用正面平视的中景全景构图，旨在精准捕捉主体优美的轮廓和弓的精巧形态。应用浅景深效果，使主体和华丽的道具处于极其清晰的焦点，而背景则平滑、干净地虚化。 [背景元素（可选）] 简约的摄影棚背景，呈现哑光蓝灰色调，带有柔和的渐变。右下角前景处稍微放置了一部分类似中世纪或古希腊神庙的白色大理石柱结构，以增加神话空间感。', 'https://img.shields.io/badge/Language-KO-blue', '![](https://img.shields.io/badge/Language-KO-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","社交媒体帖子"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1159);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('社交媒体帖子 - 月光下的古树树干肖像', '一张照片，紧密复刻 44859_2.png 中的构图与视觉元素。照片展示了一棵巨大的、扭曲的、纹理深邃的 {argument name="tree type" default="古树树干"} 特写，它从画面右侧升起，树枝形成了一个拱形的深色树冠。在这个树冠下，一位与 44859_2.png 中完全一致的 {argument name="person description" default="留着深色造型短发的孤独青年"} 出现在右下角，正抬头仰望。画面左侧夜空的中心焦点是一轮巨大、清晰且明亮的 {argument name="sky element" default="满月"}，其位置和外观与 44859_2.png 完全一致。来自月亮的柔和冷色调月光是主要光源，在树皮上投下深邃的阴影，并形成一道独特的光束照亮了男子和树木的轮廓。场景保持了广阔的夜空视野，可见少量星辰、月亮下方的深色地平线以及特定的构图。此图像完全专注于写实渲染，不包含任何社交媒体文字、UI 元素、用户个人资料或标题。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","社交媒体帖子"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1160);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('社交媒体帖子 - 带有人脸参考的电影感悬疑肖像', '请使用我上传的人脸图像作为主要身份参考。请最大限度地准确保留我的面部特征、脸型、发型、发质、胡须风格、肤色、眼型、眉毛、鼻子、嘴唇以及所有独特的面部细节。请勿改变我的脸部，也不要让我看起来像另一个人。

根据参考图像创作一张超写实的电影感肖像：我站在一群身穿黑色服装的人群中间，所有人背对镜头。我是唯一看向镜头的人，身穿 {argument name="outfit" default="时髦的黑色服装（黑色大衣/西装外套/高领衫）"}。佩戴黑色墨镜，并摆出 {argument name="pose and expression" default="自信而神秘的表情，手指轻触唇边"} 的姿势。

深沉忧郁的氛围，高级时装杂志风格，电影级布光，浅景深，真实的皮肤纹理，细腻的发丝，自然的比例，超写实摄影，8K 画质，专业相机质感，戏剧性的构图，胶片颗粒感，高端时尚大片美学。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","社交媒体帖子"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1161);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('社交媒体帖子 - 极简水彩阅读场景', '一幅极简主义水彩插画，描绘了一位 {argument name="subject" default="年轻女性"} 沉浸在安静的日常时刻，坐在舒适的桌旁阅读书籍并在打开的日记本上记录笔记。柔和的手绘动漫美学，带有精致的墨线和富有表现力的面部特征。她宽松的超大号衬衫自然垂坠，布料褶皱优雅流畅，几缕发丝温柔地散落在脸庞周围。附近放着一个陶瓷茶杯、几本堆叠的书籍和一个插着干花的小玻璃花瓶，增添了宁静的氛围。在纹理水彩纸上渲染，采用 {argument name="colors" default="暖米色、奶油色、柔灰色、灰蓝色和微妙的桃色调"} 的柔和粉彩配色方案。高度细腻的水彩阴影，边缘柔和，可见的颜料晕染、有机的颜料飞溅以及环绕主体的艺术笔触纹理。干净的留白使人物保持为视觉焦点，同时保持了轻盈、平衡的构图。{argument name="lighting" default="柔和的晨光"} 洒满场景，营造出微妙的阴影和宁静、沉思的氛围。素描本风格的艺术作品，笔触优雅，带有自然的瑕疵、精致的颜料飞溅点缀和梦幻般的手工质感。现代日式水彩艺术风格，生活方式时尚插画，居中构图，浅米色纸张纹理，情感叙事，高质量传统水彩画。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","社交媒体帖子"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1162);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('社交媒体帖子 - 从撕裂笔记本中浮现的女孩', '在 4:5 的竖向画布上创作一张超写实的超现实人像：一个微小的 {argument name="child subject" default="3 到 4 岁的东亚小女孩"} 仿佛正从一本放在乡村风格木桌上的大型横线螺旋笔记本中心的一个撕裂矩形孔洞中浮现。她直视镜头，表情平静、好奇且略带一丝脆弱，有着大大的深色眼睛、柔软自然的皮肤、微张的小嘴，以及留着两根细辫子修饰头顶两侧的长波浪卷发。为她穿上一件超大款米色粗棒针织毛衣，袖口带有长罗纹，她的小手叠放在纸张边缘，仿佛正从笔记本中探出身子。笔记本要呈现出逼真的效果，包括淡色的横线页面、右侧的黑色金属螺旋装订、厚实的纸张边缘，以及孔洞周围参差不齐、卷曲的撕裂纸张。在右下方添加一只成年人的右手，手持一支削尖的黄色铅笔，在撕裂的开口附近进行素描，暗示女孩是被画进现实世界的。在左侧放置一个黑色网格笔筒，其中可见 5 支铅笔，前景底部散落着铅笔屑；画面中需清晰可见 8 片铅笔屑。将场景置于左上角的阳光窗边，呈现温暖的晨光、柔和的阴影、浅景深以及模糊的户外绿植。使用温馨的木质室内背景，追求电影级的写实感，展现逼真的纹理、自然的色彩分级，并在头发、针织面料、撕裂的纸纤维、木纹、石墨痕迹和皮肤上呈现高细节。避免出现文字、Logo、水印、额外人物、卡通风格、扭曲的手部，或改变儿童的面部特征。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","社交媒体帖子"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1163);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('社交媒体帖子 - 超写实街头风咖啡馆人像', '超写实时尚人像，一位时髦的年轻女性在夜晚的高级咖啡馆休息室中放松，深陷在黑色皮质扶手椅中，一条腿向前交叉伸向镜头，身穿带有严重磨损和毛边细节的超大号蓝色宽松牛仔裤，黑色超大号印花 T 恤，上面有醒目的白色文字和星星图案，白黑橙配色高帮运动鞋，留着长长的深棕色波浪卷发，佩戴海军蓝佩斯利花纹头巾，银色项链和手链，表情自信放松，温暖的电影级咖啡馆灯光，背景中有发光的焦外成像效果，木质家具，身旁有挂着彩灯的圣诞树，浅景深，低角度透视，前景鞋子因透视而放大，豪华街头风时尚大片，超细腻皮肤纹理，照片级真实感，85mm 镜头，f/1.8，温暖的琥珀色调，戏剧性对比，杂志级时尚广告，8K。超写实俯视时尚摄影，一位时髦的年轻女性坐在现代咖啡馆的黑色皮质扶手椅上，镜头从上方俯拍，一只手臂放在脑后，身穿超大号黑色印花 T 恤，带有链条装饰的磨损感超大号牛仔裤，白黑橙配色运动鞋，海军蓝佩斯利花纹头巾，精致首饰，木质边桌上放着咖啡杯，杯子旁有太阳镜和黑色小手提包，温暖的咖啡馆环境光，豪华生活方式氛围，丰富的木质纹理，电影级灯光，构图干净，柔和阴影，高级街头风广告，面部细节丰富，皮肤真实，焦点清晰，35mm 镜头，高角度透视，杂志封面级质量，深度与真实感，8K。照片级真实街头时尚人像，年轻女性随意地坐在木质扶手椅上，一只手放在脑后，另一只手自然垂放，身穿超大号破洞牛仔裤，黑色印花 T 恤上有醒目的文字和星星图案，叠戴银色链条，海军蓝头巾，白橙黑配色运动鞋，旁边的咖啡桌上有饮料和配饰，温暖的豪华咖啡馆内饰，背景中有装饰性的发光树，高角度四分之三镜头视角，柔和的电影级灯光，精致的五官，细腻的发丝，高级都市时尚广告，真实阴影，浅景深，专业时尚摄影，85mm 镜头，超清晰对焦，8K。超写实正面时尚人像，一位潮流年轻女性舒适地坐在温馨高档咖啡店的皮质扶手椅上，双手放在脑后，姿态放松自信，身穿超大号黑色街头风 T 恤，带有图形文字，带有链条配饰的磨损感宽松牛仔裤，白黑橙配色高帮运动鞋，长长的棕色飘逸长发，海军蓝佩斯利花纹头巾，温暖的室内灯光，发光的咖啡馆氛围，木质桌子，边桌上放着咖啡杯，装饰性的发光树，奢华生活方式格调，电影级调色，细腻的皮肤和眼睛，自然妆容，时尚大片，浅景深，专业摄影，85mm 镜头，f/2.0，超写实，8K HDR，Vogue 风格时尚拍摄。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)', 'youmind-gpt-image-2', '["gpt-image-2","社交媒体帖子"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1164);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('社交媒体帖子 - 2026 年日本世界杯海报', '创作一张电影级体育海报，主题为 {argument name="event title" default="WORLD CUP 2026"}。采用 16:9 宽屏横向画布，呈现写实广告风格，营造极具张力的体育场氛围。主体为一名 20 岁出头的年轻日本男足球员，身材健硕，面部洁净，留着中等长度的凌乱黑发，皮肤质感自然，半身像，侧身向右，神情严肃。他身穿深蓝色日本国家队足球球衣，球衣带有细微的斜纹质感、白色肩带、领口红色镶边，胸前贴有日本国旗徽章、日本队队徽及白色运动品牌标志。背景：模糊的巨型足球场，座无虚席，笼罩在冷色调的蓝灰色薄雾中，漂浮着尘埃与光斑，左中背景处有一面巨大的日本国旗在飘扬，左上方透出明亮的漫射阳光，浅景深，充满史诗感与希望。文字排版包含 3 个元素：1) 左上方居中的日语标语 {argument name="Japanese slogan" default="その景色を、\nその先へ。"}，采用优雅的深蓝色衬线书法字体；2) 下方间距较大的英文大写副标题 {argument name="English subtitle" default="BEYOND THE LIMIT."}；3) 底部横跨的大号奢华金色衬线标题 {argument name="event title" default="WORLD CUP 2026"}，下方居中配有细横金线及小型菱形装饰。使用高级电影海报排版，金色渐变字体，写实光影，高对比度，画面中不得出现其他球员、额外标志、水印或多余文字。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","社交媒体帖子"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1165);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('社交媒体帖子 - 夏日缘侧观萤的少女', '一位 {argument name="subject" default="少女"} 与她的 {argument name="friend" default="留学生朋友"} 并肩坐在 {argument name="season" default="夏日"} 的缘侧上，注视着萤火虫笼。', 'https://img.shields.io/badge/Language-JA-blue', '![](https://img.shields.io/badge/Language-JA-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","社交媒体帖子"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1166);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('社交媒体帖子 - 3D AI Prompt Library 工作空间', '目标：创作一张精致的 3D 等轴测科技工作空间插画，展示一个可复用的 AI 设计 Prompt 库和数字内容规划工具。

画布：超宽横向横幅，长宽比约为 2.5:1，深海军蓝至青色的渐变背景，电影级摄影棚灯光，左侧和顶部留有干净的空白区域，以便后续添加覆盖文字。

主体与布局：在画布的中右侧排列一组层叠的悬浮及桌面生产力元素。使用 {argument name="primary color palette" default="深海军蓝、青色、蓝绿色、白色、紫色以及暖金色点缀"}。画面应呈现出高端 SaaS/生产力主图的质感，带有柔和的阴影、光泽斜角、细腻的反射以及圆角设计。

具体可见元素：包含 13 个主要对象：1 个大型中央桌面浏览器窗口，带有深色顶部栏和线框布局块；1 个位于左后方的深色网格仪表盘面板，带有 9 个方形磁贴；1 个位于前方的白色小型分析/卡片面板，带有左侧列表点和底部迷你按钮；1 个位于右侧的青色 UI 卡片，带有 4 个主要内容块和 3 行窄侧行；1 个位于更右侧的紫色 UI 卡片，带有 5 个圆角模块；1 个平放在左前方前景的电子表格/日历平板电脑，带有绿松石色行标题和紫色顶部栏；1 个位于中央前景的打开的报告/文档平板电脑，带有 4 个彩色图表块；1 叠位于右前方前景的文件或文件夹，顶部是一张空白白纸；1 小叠位于前景的圆角方形应用磁贴；1 个位于底部中央的深色智能手机或细长矩形设备；1 大叠竖立在右后方的深色活页夹或文件夹，带有青色和金色边缘；1 个位于右上角的悬浮云图标，带有金色轮廓光；1 个位于最右侧的深色圆柱形笔筒，内含 3 支书写工具。

背景点缀：在面板上方添加细长的金色轨道连接线，带有 3 个小型金色节点；在右上角附近添加一个小青色立方体；在主窗口后方添加半透明玻璃质感的面板轮廓。保持这些点缀精致且处于次要地位。

风格：高端 3D 渲染，圆润的类黏土 UI 组件，玻璃拟态，柔和的环境光遮蔽，斜角边缘，金属金高光，现代创作者工具美学，无人物。使用 {argument name="lighting mood" default="带有明亮青色轮廓光的高冷电影感蓝色摄影棚灯光"} 以及 {argument name="render style" default="优质 3D 等轴测 SaaS 插画"}。

文字限制：无可见文字，无 Logo，无水印。任何界面标记应仅为抽象线条、点、网格和空白卡片。

构图限制：将主要元素群集中在偏右侧，保持从平面的前景平板电脑到悬浮的背景面板之间强烈的深度层次感，将云图标保持在右上角，并确保左侧背景大部分保持简洁。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","社交媒体帖子"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1167);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('社交媒体帖子 - 猫咪识别结果页面', '使用提供的参考图像作为源猫咪和应用上下文，将摄像头识别屏幕转换为小程序中完整的宠物档案结果页面。将实时摄像头视图替换为简洁的卡片式分析页面：在白色预览区域显示一张可爱的贴纸风格卡通插图，内容为同一只黑白相间的猫咪坐着并翘起尾巴，配有一个标有“点击看原图”的小按钮和一个放大镜图标。保持移动端截图的长宽比和 iOS 风格的顶部状态栏，但将页面标题更改为 {argument name="pet name" default="汪汪"}。

布局：在明亮的绿色图案背景上创建一个大的圆角矩形结果卡片。在插图下方，添加一个包含以下可见数据元素的档案部分：1) 带有狗表情符号和 {argument name="pet name" default="汪汪"} 的名称行，以及一个标有“幸运”的绿色徽章；2) 引语文本 {argument name="quote" default="尾巴有自己的想法"}；3) 两个标有“体型 大只”和“亲近度 观望”的小信息框；4) 标有“遇见时间”的灰色行，显示 {argument name="encounter time" default="2026.06.27 08:46"}；5) 标有“遇见地点”的灰色行，显示 {argument name="coordinates" default="30.516455620659723, 114.34392523871527"}；6) 两个标有“小狗”和“机灵的”胶囊标签；7) 识别置信度文本“识别置信 52%”。

底部操作：在卡片下方添加两个底部按钮：一个带有图片图标和“生成分享海报”文字的黄色大圆角按钮，以及一个带有分享网络图标的较小黑色圆角方形分享按钮。

风格：俏皮精致的中文小程序 UI，粗黑轮廓，圆角卡片，柔和阴影，黄色强调色，简洁的矢量风格插图。不要保留原始的摄像头扫描框、缩放控件、快门按钮或实时街道背景。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","社交媒体帖子"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1168);
