INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 皮克斯风格信息图故事板海报', '创建一个清晰、简洁的信息图故事板海报，主题为 {argument name="subject" default="THE MILKSHAKE MAKER"}。宽屏 16:9 布局，白色背景，黑色边框，粗体黑色排版，高级皮克斯 3D 风格渲染，明亮生动的色彩 — {argument name="color scheme" default="奶油香草白，鲜艳红"}', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

