INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 日式金蛋设计 Slides', '创建一张深色演示文稿风格的社交媒体图片，主题为日式金蛋设计变体。画布：宽屏 16:9 比例，黑色/炭灰色背景 (#181818)，简洁现代的排版，右侧留有充足的负空间。顶部文字：在左上方放置一行大的日文句子「まず imagegenで作った金の卵12案 です。」，其中“imagegen”和“金の卵12案”使用粗体白色，其余部分使用常规白色。主体视觉：在标题下方的左侧，绘制一张圆角矩形的深海军蓝黑色卡片，带有细微的边框和柔和的阴影。卡片内展示 12 个金蛋概念设计，排列为 4 列 3 行的网格。这 12 个蛋分别是：1) 光滑直立的亮面金蛋，2) 带有凸起边缘/轮廓的椭圆形蛋（图标风格），3) 多面低多边形宝石蛋，4) 带有小阴影的平滑金属金蛋，5) 带有大面积白色高光的扁平亮黄色蛋，6) 有纹理/拉丝质感的金蛋，7) 右上角带有星形闪烁的光滑金蛋，8) 带有明亮边缘光的深色发光金蛋，9) 矮圆型金蛋，10) 修长光滑的金蛋，11) 深青铜色反光金蛋，12) 简单的哑光黄金色蛋剪影。底部文字：在左下方放置一行较长的日文句子「それを参考に、ファームのコード描画プリミティブで近似する12案 を作りました。」，其中核心短语「ファームのコード描画プリミティブで近似する12案」使用粗体白色，其余部分使用常规白色。在底部中右侧添加一个半透明的圆形向下箭头叠加层，模拟社交媒体查看器控件。视觉风格：简洁的截图式构图，高对比度，金蛋采用写实的亮面金色渲染，细微的卡片边框，无多余的 Logo 或水印。可自定义文本槽：顶部句子可使用 {argument name="top Japanese text" default="まず imagegenで作った金の卵12案 です。"}；底部句子可使用 {argument name="bottom Japanese text" default="それを参考に、ファームのコード描画プリミティブで近似する12案 を作りました。"}；主体对象可使用 {argument name="object theme" default="golden egg"}。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1171);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 中式书法品牌形象海报', '目标：为书法字标创作一张精致的中式形象设计展示海报，以两个大型黑色水墨书法汉字 {argument name="main Chinese logotype" default="晓峰"} 为核心，采用优雅的品牌案例研究布局及说明性标注图形。

画布：3:4 比例的竖版海报，温暖的米白色宣纸背景，带有细腻的纤维纹理和浅米灰色陈旧感，留白充足，呈现极简的高级编辑排版风格。

主体构图：将巨大的黑色书法字标置于中心偏左位置，占据页面中部。笔触应富有表现力、棱角分明且具有建筑感，呈现干笔渐变、粗糙的墨迹边缘、锋利的钩笔末端以及笔画内细微的留白。在字标下方中心附近添加一枚红色方形印章。

文字层级：在主字标下方，设置间距宽阔的拼音 {argument name="romanized name" default="XIAO FENG"}，随后是一条细长的水平分割线，两侧为较小的中文名称，再下方是小号大写英文字体 {argument name="English subtitle" default="DAWN PEAK"}。保持排版精致、字间距宽、灰色且低调。

左上角标识区：在左上角添加一个小型垂直对齐的品牌标题，包含中文和英文行。包含 4 行可见文字：“学生万象”、一条短横线、“品牌标识提案”以及“IDENTITY DESIGN”。使用微小的灰色衬线体或宋体。

右上角座右铭区：在右上角添加一段狭长的垂直中文短语 {argument name="vertical motto" default="晓启乾坤  峰立云间"}，下方配有一枚小红印。

右侧标注系统：在字标右侧创建 3 个分析元素。首先，用一个细红圈高亮显示第二个字的顶部笔锋，通过红色引导线连接至标签“细节解析”。其次，一个红色轮廓的方形插图显示该笔锋的放大细节，下方标注“提气笔”及小字“峰顶意象”。第三，在其下方放置一张带有浅色边框的矩形说明卡，标题为“设计说明”，包含一段紧凑的中文段落和 4 个带红色圆圈编号的要点。

左下角细节标注：添加 1 个圆形放大插图，展示第一个字左下角内部的笔画细节，带有精细的黑色构造线和浅色半圆高亮。其右侧放置小标题“设计说明”及一段微小的灰色中文说明文字。

右下角结构标注：添加 1 个淡雅的技术构造图，标注为“字形结构”，下方附带英文“STRUCTURE”，展示细线条的几何辅助线及低透明度的字标轮廓。

视觉风格：高端中式品牌展示，学术性形象设计提案，克制的红色标注线，灰色微型排版，黑色水墨书法，细腻的印章红点缀，精致的网格状说明细节，博物馆目录般的静谧留白。

约束条件：使用 2 个主要中式书法汉字，2 枚红色印章，3 个右侧分析元素，1 个左下角圆形插图，以及 1 个右下角结构图。所有标注需保持精巧准确，避免现代 UI 风格，避免鲜艳色彩，避免杂乱，并保留海报优雅的留白。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1172);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 纽约浪漫场景调色对比', '目标：创建一张电影感并排对比图，展示不同的调色约束如何影响同一个纽约市夜间浪漫场景。

画布：超宽横向对比图，比例约为 4:1，带有细黑色外边框，两个相等的全景面板之间有黑色分隔线。

布局：使用 2 个并排面板。左侧面板左上角标注：“A 无技能：普通纽约浪漫调色”，下方附带较小的副标题：“正常饱和度 / 更亮的夜空感 / 现代夜景质感”。右侧面板左上角标注：“B 使用 eterna-image2image：标准 ETERNA”，下方附带较小的副标题：“柔和夜色 / 柔光高光 / 更深邃且清晰的阴影”。标签需保持小巧、简洁、白色且不突兀，类似于电影测试样片。

场景内容：两个面板展示相同的构图：正好 2 位人物，女性在左，男性在右，站在雨中纽约的夜晚街道上，面对面站立。女性外观 {argument name="woman appearance" default="深色齐肩发带刘海，浅米色羊毛大衣，柔和自然妆容"}。男性外观 {argument name="man appearance" default="深色卷发，戴眼镜，海军蓝西装外套，白衬衫"}。他们侧身站立，情感内敛，仿佛正在进行一场安静的浪漫对话。街道湿润且具有反光感，背景中有模糊的车流、店面、路灯、建筑窗户和远处的一辆黄色出租车。背景中包含从街道上升起的可见蒸汽或薄雾。

左侧面板外观：通用的现代纽约浪漫调色，阴影更亮，面部和外套上有略微夸张的冷色调月光高光，饱和度较高，湿润路面的反光感强，可见光斑（bokeh），呈现出更精致的数字夜景感。女性和男性位于前景较近处，半身构图，女性靠近左侧三分之一处，男性靠近右侧三分之一处。

右侧面板外观：更内敛的富士 ETERNA 风格电影调色，使用柔和的色彩、柔和的高光、更深邃但依然清晰的阴影、较低的饱和度、自然的实用路灯暖色、更少的人造蓝光溢出、更平滑的色调过渡，以及更扎实的电影感夜间氛围。构图比左侧面板稍宽，留白更多，可见更多的路面、柱子、出租车、蒸汽和湿润的街道环境。女性和男性保持侧面对视，位于面板中央。

视觉风格：写实电影剧照，变形宽银幕感，自然的雨后湿滑路面，浅景深，真实的肤色，柔和的实用照明，细腻的胶片颗粒，克制的对比度，无奇幻元素。

约束：使用 2 个面板，每个面板正好 2 个人物，仅包含上述 2 个面板标签和 2 个副标题，无额外说明文字，无 Logo，无水印，无 UI 控件，前景中无其他人物。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1173);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 黄金分割摄影构图海报', '创建一个 {argument name="style" default="高级黑白教育类摄影构图海报"}，主题为 {argument name="subject" default="视觉叙事中的黄金分割"}。将海报设计为垂直电影感拼贴画，采用深炭灰色背景、细白边框、写实纪录片摄影风格、柔和的胶片颗粒感、高对比度单色光影以及简洁的编辑排版。使用四个照片面板。顶部大面板：展示孩子们在乡村土路上骑自行车和行走，背景为田野、树木、山脉和柔和的阴天。将孩子们置于画面左侧。叠加一个大型简洁的白色黄金螺旋和黄金分割网格，螺旋向孩子们卷曲，作为主要焦点。添加黄色标题文字：“GOLDEN SPIRAL”。在右侧添加白色注释文字：“SECONDARY OBJECT ON THE CURVE”，并用细蓝色箭头指向螺旋曲线上的模糊物体。左下方面板：展示一张特写黑白肖像，聚焦于一个小男孩的脸部，采用戏剧性光影，以一只眼睛为主要焦点。叠加一个白色黄金矩形网格，并在眼睛周围嵌套矩形。添加黄色标题文字：“GOLDEN RECTANGLE”。添加白色说明文字：“THE LEFT EYE WAS CHOSEN AS THE CENTRE OF INTEREST”。右下方上部面板：展示一张母亲抱着孩子的感人黑白肖像。使用电影级纪录片光影。叠加白色对角线黄金三角构图线，使其穿过母亲的眼睛或鼻梁附近。添加黄色标题文字：“GOLDEN TRIANGLE”。添加白色注释文字：“PLACE THE CENTRE OF INTEREST ON THE INTERSECTING POINT, THE EYE OR BRIDGE OF NOSE IS IDEAL”。右下方下部面板：展示一张戴着传统斗笠的人的黑白肖像，背景为风景或开阔的山谷。将脸部置于黄金螺旋焦点附近。叠加一个白色黄金螺旋和黄金分割网格。添加黄色标题文字：“GOLDEN SPIRAL”。添加白色说明文字：“THE FACE WAS PLACED INSIDE THE SPIRAL TO AVOID CROPPING TOO MUCH OFF THE TOP”。整体风格：专业摄影大师课海报，写实黑白照片，简洁的白色构图叠加，黄色章节标题，易读的教育性文字，细网格线，优雅的布局，无 Logo，无水印，高分辨率海报设计。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1174);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 历史战役可视化长卷', '生成一个 [经典战役可视化长卷]，单张完整图像，无拼贴、无网格、无分栏，水平 3:1 比例。

战役主题：[{argument name="battle theme" default="赤壁之战"}]
标题：[{argument name="title" default="赤壁之战"}]
副标题：[{argument name="subtitle" default="用一句话总结关键转折点"}]
核心内容：[战场地形 / 对阵双方 / 主要进攻路线]', 'https://img.shields.io/badge/Language-ZH-blue', '![](https://img.shields.io/badge/Language-ZH-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1175);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 韩语版人机协作团队信息图', '目标：制作一张竖版韩语信息图海报，总结 Anthropic 关于构建高效人机协作团队的课程，页面 {argument name="page number" default="1/2"}，采用简洁的米色编辑科技风格，并带有编号的课程章节。

画布：2:3 竖版海报，米白色暖色背景，细边圆角卡片，橙色编号圆圈，黑色韩语字体，微妙的灰色分割线，小型线条艺术插图，以及类似 Anthropic 的极简品牌标识。采用类似于博客摘要信息图的密集但易读的布局。

页眉：大号粗体韩语标题：“Anthropic 的教训：构建高效的 Human-Agent Team”。下方为小号副标题：“从一个人与一个 AI 工作的时代，迈向人与 Agent 在同一工作空间协作的团队时代”。元数据行：“原文摘要 | Claude Tag | 2026.06.24”。右上角有一个小巧的圆角页面徽章“1/2”，以及一幅手将积木放入三个橙色抽屉的插图；抽屉上显示着人类、机器人和目标的简单图标。

布局：本页使用 5 个主要的编号章节，以清晰的网格堆叠。第 1 和第 2 章节位于页眉下方并排显示。第 3 章节是一个宽带，分为三个参与卡片和一个模拟聊天截图。第 4 章节是一个全宽课程卡片。第 5 章节是另一个全宽课程卡片。底部设有导航条、来源条和页脚品牌标识。

第 1 章节：编号徽章“1”，标题“有什么不同？”。展示一个包含 2 个面板的对比图：左侧面板标记为“单人模式”，显示 1 个人类图标 ↔ 1 个 AI 机器人图标，配文“1 名人类 ↔ 1 个 AI”；右侧面板标记为“多人模式”，显示多个人类剪影 + 多个机器人图标 + 一个目标图标，配文“多人 + 多个 Agent + 共同目标”。添加底部标注：“现在的 AI 协作更接近团队工作，而非个人任务”。

第 2 章节：编号徽章“2”，标题“什么是多人模式 Agent？”。包含 3 个带图标的定义行：机器人图标行“与多个人类同时工作的 AI Agent”；大脑图标行“拥有自主记忆 (memory)、技能 (skills) 和凭证 (credentials)”；类似 Slack 标志的彩色图标行“驻留在 Slack 等协作空间中支持团队目标”。底部示例胶囊：“例如：在团队频道中共同进行数据分析”。

第 3 章节：编号徽章“3”，标题“如何高效参与团队”。左侧包含 3 个圆角卡片：卡片 1（带头像和便签图标），标题“持续记忆”，描述“记住目标并调整执行”；卡片 2（带盾牌和钥匙图标），标题“与人类分离的凭证”，描述“安全的权限和可预测的护栏”；卡片 3（带数据库和放大镜图标），标题“广泛且持续的信息访问”，描述“理解并遵循组织期望的行为方式”。在这些卡片下方添加一个星形标注：“仅有技术是不够的 → 还需要团队的运营方式和共同规范”。右侧显示一个类似 Slack 的聊天截图，标题为“# data-analysis”，带有紫色侧边栏，并显示来自以下发送者的 5 条聊天消息：“민지 (分析主管)”、“Claude (Data Analyst)”、“호준 (PM)”、“Claude (Data Analyst)”以及一个小型的最终状态/消息区域。包含微小的头像和时间戳，但保持文本清晰紧凑。

第 4 章节：编号徽章“4”，标题“Lesson 1. 公开工作，并为 Agent 提供广泛的背景信息”。左侧插图：3 个人坐在笔记本电脑前，周围环绕着包含文档、聊天和代码图标的虚线共享工作空间图。中间的要点区域解释说，Agent 应该在 Slack、Jira、文档和存储库等可见空间中工作；私聊会隐藏背景信息；Agent 需要访问记录的对话和工件。添加两个侧边卡片：卡片标题“为什么重要？”（带橙色星形图标，要点包括记忆不是自动的、缺失背景会降低输出质量、共享背景可改善建议）；卡片标题“Anthropic 式运营方式”（带齿轮图标，要点包括共享频道、公开分享工作成果、将有用的私聊移至共享空间、记录易读的摘要）。底部锁定标注：“敏感对话可以通过 DM、Claude.ai 和 Claude Code 等独立空间处理”。

第 5 章节：编号徽章“5”，标题“Lesson 2. 为所有人及 Agent 明确分配角色和工具”。包含一个简短的韩语要点列表，关于分配明确的角色、工具、凭证和期望。左下方创建 2 个小表格：“Human (人类)”表格（包含 4 行人类队友及其角色）；“Agents (Agent)”表格（包含 4 行：“Claude (Data Analyst)”、“Claude (Design Critic)”、“Claude (Research Synthesizer)”、“Claude (QA Tester)”）。右侧是一个绿色边框的清单卡片，标题为“高效团队的样子”，包含 5 个清单项：“达成共识的 Task Set”、“人类和 Agent 在同一线程中协作”、“记录各角色的范围和责任”、“个人不再由 AI 代替，团队共享相同的背景和数据”，以及最后一项关于共享工具和权限的简洁说明。

底部导航：添加橙色箭头图标和文字：“下一页：Lesson 3 复杂性设置 · Lesson 4 建立信任 · 清单 · 结论”，右侧带有小的“1/2”徽章。来源条包含两个带图标的项目：“来源 URL: https://claude.com/blog/building-effective-human-agent-teams”和“原文标题: Building effective human-agent teams”。右下角大字标“ANTHROPIC”。左下角版权“© 2026 Gonnecter”。右下角添加一个微小的彩色抽象标志。

视觉风格：现代韩语商业信息图，清晰的矢量线条艺术，暖奶油色背景，橙色点缀，聊天模拟图使用柔和的紫色，成功清单使用绿色，精确对齐，高信息密度，易读的韩语文本，无照片写实感，除微妙的卡片深度外无阴影。

约束：保持 5 个编号主章节，2 个对比面板，3 个定义行，3 个参与卡片，5 条聊天消息，2 个角色表格，以及 5 个清单项。不要添加额外的页面、额外的课程编号、水印或不相关的图标。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1176);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 极端天气电视记者生成系统', '[输入项] 参考图像：1，天气类型：热浪 / 台风 / 暴风雪，长宽比：必填（例如 1:1）[推荐参考图像] 请使用人物特征、发型、发色、年龄、体型和服装风格清晰的图像。建议使用显示头部到上半身或全身的图像。简单的背景最为理想。[主要指令] 将所附参考图像中的人物描绘为一名在虚构电视广播中从极端天气现场进行报道的户外记者。忠实地保持参考图像中的特征、发型、发色、眼睛印象、年龄、体型、氛围和表情格式，确保人物具有辨识度。将真人图像重建为高质量的写实风格，将动漫或插画重建为保持原有艺术风格、线条、配色和质感的图像。不要继承参考图像中的背景、光照、构图或原始姿势。在尽可能保持原有颜色和氛围的同时，自然地调整服装以匹配输入的天气。人物是一名手持广播麦克风并向镜头报道情况的当地记者。描绘他们不仅仅是平静地站着，而是被极端天气吹袭，疯狂而拼命地继续广播的瞬间。使头发、服装、面部表情、姿势、身体倾斜度、手部动作和随身物品对天气做出自然反应，使人物看起来确实身处现场。面部表情要足够夸张以传达情况的严重性，但不要使其成为仅表现恐惧或痛苦的严肃表情。使其成为在社交媒体上脱颖而出的震撼现场报道。然而，这种吸引力应通过人物的反应和极端天气的力量来表达，而不是通过 UI 装饰。在屏幕上叠加一个简单的虚构电视广播 UI。UI 在所有天气类型中应保持相同的形状和位置，不得有繁杂的装饰、天气图、复杂的数字或长文本。在屏幕顶部，放置左右对称的小型固定 UI 元素。左上角显示红色横幅内的白色“LIVE”文字。右上角显示红白相间的警告三角形图标，以及与左上角位置、高度和设计风格相同的小型“ALERT”白色文字横幅。对齐左右 UI 元素与顶部和边缘的距离，并根据内容自然调整宽度。在屏幕底部，放置一个水平的简单广播条。在底部栏中，仅显示与输入天气类型完全一致的文本，且要大而清晰。如果输入为“Heatwave”，显示“猛暑”。如果为“Typhoon”，显示“台風”。如果为“Blizzard”，显示“猛吹雪”。文本仅限于顶部 UI 中的“LIVE”和“ALERT”以及底部栏中的天气类型显示。不要显示除指定天气名称以外的任何文本，例如地区名称、电视台名称、节目名称、真实徽标、企业徽标或额外的滚动字幕。在背景中，不要显示可读的标志、广告、指南牌、路标文字、描述、英文字符、日语或数字。[天气特定表达] ■ 热浪：使用盛夏烈日下的城市街角作为背景。使其一眼就能看出是危险的热浪，而不是普通的晴天。使路面呈现白色漂白、干燥、哑光、无光泽的沥青质感。通过细微的裂纹、干燥的灰尘、轮廓清晰的强阴影以及远处路面上可见的轻微热浪来表现干燥的极端高温。不要包含湿路面、水坑、洪水、镜面反射、雨后质感、水花、雾气或蒸汽状外观。人物的前额和颈部应有大量汗水，面部略微潮红，在报道时忍受着高温和强光。一只手拿着麦克风，另一只手用手帕或小毛巾擦汗。头发因高温而略显凌乱，在继续报道时显得慌乱。汗水主要表现在皮肤上；不要让头发或衣服看起来像被雨淋透了一样。保持服装基本干燥。■ 台风：使用天空昏暗、暴雨倾盆、狂风大作、水花四溅、路面潮湿且树木剧烈摇晃的户外现场作为背景。使风雨横穿屏幕，以便一眼就能看出台风的强度。人物在报道时应身体倾斜，双脚稳稳站立。头发被强风吹得凌乱不堪，衣服被雨水打湿并随风飘动。一只手用力握住麦克风，另一只手支撑身体或衣服。如有必要，自然地添加保留原有服装氛围的简单雨具或兜帽。不要使用雨伞。保持姿势动态，但在新闻广播屏幕易于看清面部、手部和麦克风的范围内。■ 暴风雪：使用被大雪和强风包围的冬季街道作为背景。雪应横向猛烈吹拂，能见度模糊且呈白色，道路和周围环境有厚厚的积雪。明确这不仅是普通的降雪，而是连站立都困难的暴风雪。人物应穿厚重的冬装大衣、围巾、手套，必要时戴上兜帽，身体前倾，因寒冷而瑟缩。雪应附着在头发、肩膀和冬装上，表现出他们眯着眼睛拼命继续广播的样子。冬装的颜色和印象应自然地与参考图像中的服装及人物氛围相匹配。[构图与完成] 使人物成为中景电视广播构图的主体，从头顶到膝盖以上清晰可见。将人物置于屏幕中央，构图应使面部、手部、麦克风、对天气做出反应的姿势、背景中的极端天气、顶部 UI 和底部 UI 都易于阅读。人物的大小应自然地置于顶部和底部 UI 之间，并作为电视广播屏幕显得稳定。避免极端的广角、极端的宣传画式构图，或人物占据屏幕过多的构图。强烈且夸张地表现天气，但不要完全遮挡人物的面部或身体。不要描绘血液、伤口、倒塌、撤离人员或严重的灾难破坏；将其完成为具有现场感和社交媒体上脱颖而出的幽默感的夸张地方广播。不要让 UI 条或文本与人物、麦克风、手部或面部重叠。正确描绘人物的身体、手指和麦克风，不要生成重复的人物、不同的人物、多余的肢体、多余的麦克风、乱码文本、无意义的字符或现实世界的徽标。', 'https://img.shields.io/badge/Language-JA-blue', '![](https://img.shields.io/badge/Language-JA-blue)', 'youmind-gpt-image-2', '["gpt-image-2","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1177);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 白斑河鲀科学图鉴', '目标：制作一张 4:5 纵向比例的微距科学图鉴信息图，主题为 {argument name="animal name" default="白斑河鲀"}，将该动物呈现为极具视觉冲击力的全出血珊瑚礁景观，并采用信息丰富的杂志排版。

画布：4:5 纵向比例，深青色海洋背景，将高分辨率写实野生动物微距摄影与简洁的矢量信息图板块相结合。使用奶油色、沙色、柔和的黄色、水蓝色和珊瑚橙色作为点缀。添加细微的气泡、珊瑚礁纹理和圆角板块边框。

主体：一条大型写实白斑河鲀，{argument name="scientific name" default="Arothron hispidus"}，位于画面中下方偏右，面向右侧，身体充气呈圆形，覆盖着密集的白斑，拥有带有黄色光环的明亮眼睛、微噘的小嘴、半透明的鳍，背景可见珊瑚礁。鱼类应像景观标本一样占据中心位置。

顶部标题区：大型压缩大写奶油色标题，内容为 {argument name="headline text" default="白斑河鲀"}。下方添加斜体黄色学名“Arothron hispidus”，随后是一行简短的分类信息“辐鳍鱼纲 / 鲀形目 / 四齿鲀科”，以及一段简短描述：“一种迷人的珊瑚礁居民，拥有强大的防御能力和缓慢的游动姿态——可爱、聪明且具有潜在危险。”

左侧栏：创建一个名为“防御特征”的纵向板块，包含 6 张带编号的特征卡片，每张卡片配有小幅照片剪裁和文字。6 张卡片分别为：1) “充气”：展示充气后的河鲀面部，解释其通过快速吸入水或空气使身体膨胀成一个大圆球；2) “棘刺”：展示近距离观察下竖起的尖锐皮肤棘刺，解释其在充气时会从皮肤中竖起；3) “坚韧皮肤”：展示皮革般的斑点皮肤，解释其带有凸起和鳞片的厚实皮肤提供了机械性保护；4) “喙状牙齿”：展示嘴部，解释其融合的强力牙齿可以压碎螃蟹、蜗牛和海胆等带壳猎物；5) “毒素风险”：展示带有生物危害标志和黄色警告三角的河鲀，解释河鲀毒素可能致命且无解药；6) “警告姿态”：展示完全充气的带刺河鲀，解释受威胁的动物会充气、竖起棘刺并展示鲜明的对比图案。

右侧栏：创建堆叠的圆角科学板块。顶部为分类卡片，包含 3 行内容及图标：“纲：辐鳍鱼纲 (Actinopterygii)”、“目：鲀形目 (Tetraodontiformes)”、“科：四齿鲀科 (Tetraodontidae)”。下方为“分布范围”板块，展示青色背景上的米色世界地图，并以橙色高亮显示印度洋-太平洋分布区，标注为“印度洋-太平洋：东非至琉球群岛，南至澳大利亚，东至法属波利尼西亚。”下方创建 3 张生态卡片：“捕食者”配以鲨鱼、石斑鱼、海鳗和海鸟图像；“饮食”配以螃蟹、蜗牛和海胆图像；“行为”配以小型河鲀肖像，描述其缓慢放松的游动方式，常在珊瑚礁附近徘徊，独居或成对，除非受到挑衅否则不具攻击性。

中下部信息带：在鱼类附近添加一张“栖息地”小卡片，配有珊瑚图标，介绍其在清澈热带水域的珊瑚礁和泻湖中生活，通常靠近斜坡和避风区域，深度可达 40 米。在中心区域底部，添加 5 个带有图标的度量瓷砖：“体型：最大 50 厘米 (20 英寸)”、“重量：最大 2.5 公斤 (5.5 磅)”、“速度：最快 8 公里/小时 (5 英里/小时)”、“寿命：野生环境下 10–15 年”、“保护状况：无危 (LC)，IUCN 红色名录”。

底部区域：创建两个大型圆角板块。左侧板块标题为“关键适应性”，包含 7 个绿色勾选符号的要点：具有可快速充气的弹性胃；通过肌肉控制竖起的棘刺；用于物理防御的坚韧带刺皮肤；用于压碎硬壳猎物的强力喙；作为化学防御的河鲀毒素；与珊瑚和沙地融为一体的卓越伪装；用于精确机动的强壮胸鳍。包含一张带刺充气河鲀的圆形内嵌图像。右侧板块标题为“3 个惊人的事实”，包含 3 条带编号的事实：1) 它们可以使用胸鳍在海底“行走”；2) 河鲀毒素并非由鱼类自身产生，而是来自其饮食中的细菌，并随地点和季节而变化；3) 尽管看起来行动迟缓，但它们是优秀的解题者，拥有良好的记忆力。添加三张小型辅助插图：行走中的河鲀、绿色细菌和蓝色大脑。

页脚：添加一个带有相机图标的窄长圆角横幅，包含保护信息 {argument name="footer message" default="只可远观，不可触碰。拍照留念，切勿惊扰。这些神奇的防御机制属于海洋。"}，随后是一个蓝色小爱心。

约束条件：使用列出的准确板块数量和编号项目。保持所有文字为英文，清晰易读，并对齐到精致的教育海报网格中。避免添加额外的动物或不相关的标签。无水印，无二维码，无 Logo。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1178);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 网球拍爆炸图蓝图', '目标：创建一个简洁的技术蓝图风格爆炸图，展示 {argument name="sports equipment" default="网球拍和网球"}，并像说明书插图一样进行标注。

画布：3:4 纵向构图，采用米白色纸张背景，留有大量负空间。使用纤细的钴蓝色线条、单线绘图笔触，仅在必要处使用淡蓝色半透明填充，并带有细微的印刷纹理。除球核处有极淡的平铺蓝色填充外，无其他阴影。

布局：将爆炸的网球拍垂直放置在画布左侧三分之二处，各部件沿中心垂直轴分离。将爆炸的网球横截面放置在右侧中部。添加虚线垂直引导线以框定每个爆炸组件，并添加虚线水平引出线指向各部件右侧的标签。使用小型全大写等宽蓝图字体。

页眉和页脚文本：在左上角放置 "FIG.002"。在右上角放置 "[ RACQUET AND BALL ]"。在右下角放置 "COPYRIGHT 2026"。

离散元素：总共显示 13 个主要可见组件：7 个球拍组件和 6 个球体/标注相关组件。7 个球拍组件从上到下依次为：1) FRAME（拍框），带有均匀间隔小孔的椭圆形拍头边缘及局部叉状连接；2) STRING BED（拍面），由密集的对角交叉线组成的独立椭圆形网状插件，带有微小的周边节点；3) THROAT（拍喉），带有开放式切口的叉状三角形连接件；4) SHAFT（拍杆），带有矩形嵌入细节和圆形末端开口的短圆柱形连接件；5) GRIP（手柄），带有螺旋带的加长缠绕式圆柱形手柄；6) BUTT CAP（拍柄底盖），手柄下方的小型六角形端盖；7) 环绕球拍组件的虚线对齐框和标注构造线。6 个球体/标注相关组件为：1) 顶部白色弧形 FELT（毛毡）外壳片；2) 顶部带有圆形环状轮廓的中央蓝色球形 CORE（球核）；3) 底部白色弧形 FELT（毛毡）外壳片；4) 环绕球体组件的虚线垂直引导线；5) 指向 FELT 的虚线水平标签线；6) 指向 CORE 的虚线水平标签线。

标签：添加 7 个蓝色大写文本标注：FRAME、STRING BED、THROAT、SHAFT、GRIP、BUTT CAP、FELT 和 CORE。将球拍标签放置在球拍部件右侧，球体标签放置在球体部件右侧。保持标签对齐且简洁。

视觉风格：极简未来主义技术插图、产品爆炸示意图、精确的矢量几何图形、纤细的蓝色轮廓、拍面使用淡蓝色阴影/网格，无照片级真实感，无人像，无球场，无额外装饰。

约束：保持拍头在顶部略微倾斜，拍面悬浮于其下方，所有手柄部件向下堆叠并留有可见间隙。球体应呈现为简单的剖面图，包含两个分离的毛毡外壳半球和一个蓝色球核。在 {argument name="background color" default="暖米色"} 纸张上使用 {argument name="line color" default="钴蓝色"} 线条，并标注 {argument name="figure number" default="FIG.002"} 和 {argument name="copyright text" default="COPYRIGHT 2026"}。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1179);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 城市双重曝光宣传海报', '{argument name="event" default="2026 年春节"} {argument name="city" default="广州"} 城市宣传海报，9:16 竖版，既有节日氛围又不失优雅。采用 S 型流线构图的双重曝光效果，背景为纯白纹理纸质感。右下角：一位身着传统中式服装的微缩人物挥舞着长长的红绸带，绸带幻化为连绵的山峦与江水，从中显现出层次分明的广州全景，包括广州塔、珠江新城天际线、珠江游船、古建筑以及白云山。左下角排版：“SPRING 2026” 横向排列，配以竖排汉字“千年商都，魅力广州”。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1180);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - Claude Code 速报信息图', '目标：创建一张日式手绘风格的速报信息图，主题为 {argument name="headline topic" default="Claude Code 实现用于 X 速报帖子的信息图生成功能"}。

画布：16:9 横向图片，深蓝色黑板背景，粗糙的马克笔和粉笔质感，采用高对比度的红色、橙色、黄色、白色和奶油色。使用不规则的手写字体、草图轮廓、笔触和涂鸦图标。拒绝照片级真实感。

布局：左侧设有一个带白色边框的竖长红色速报横幅，垂直堆叠白色大号日文「速报」字样，底部附近有一个黄色闪电图标。顶部中央设有一个宽大的红橙渐变笔触标题横幅，左侧配有 1 个黄色闪电图标，右侧配有 1 个扩音器图标。下方是一个圆角来源栏。中间主要区域包含 2 个垂直堆叠的大型圆角矩形信息面板。右侧包含 2 个垂直堆叠的小型圆角卡片：上方为来源信息卡，下方为日期/时间卡。底部一行包含 3 个标签胶囊。

文本内容：顶部标题横幅文字：第一行「Claude Code」，第二行「インフォグラフィック画像生成機能を」，第三行「X速報投稿に実装」。来源栏文字：「SOURCE: zenn-blog-automation PR #217」。右侧来源卡文字：「情報源:」然后是「zenn-blog-automation」和「PR #217」。第一个主面板文字：「GPT-IMAGE-2で」、「breaking_newsテーマの」、「インフォグラフィックを生成し」、「X速報投稿に添付できるようになった。」在图像缩略图图标上包含一个写有「GPT-IMAGE-2」的小型橙色标签。第二个主面板文字：「画像生成失敗時は」、「テキストのみ投稿にフォールバック。」日期/时间卡文字：「検出日時:」然后是 {argument name="timestamp" default="2026/06/24 19:15 JST"}。底部标签胶囊必须包含 3 个标签：{argument name="hashtag one" default="#claudecode"}、{argument name="hashtag two" default="#anthropic"} 以及 {argument name="hashtag three" default="#ai"}。

需包含的离散视觉元素：1 个左侧竖向横幅、1 个顶部标题笔触横幅、1 个来源栏、2 个主信息面板、2 个右侧卡片、3 个标签胶囊、共 2 个黄色闪电图标、1 个扩音器、1 个文档图标、1 个时钟图标、1 个带山脉图案的图像缩略图图标、2 个指向右侧的橙色箭头图标、1 个带 X 的云朵失败图标，以及 1 个带三个点的对话气泡。

视觉风格：充满活力的日式速报信息图，马克笔海报外观，略显不规则的白色手写字体，橙色圆角边框，重要短语下方有黄色下划线高亮，扩音器、横幅和标签周围有小型装饰性放射状强调标记。保持构图紧凑但易读，具有强烈的层级感和戏剧性的紧急新闻氛围。

约束：严格使用指定的日文文本，不要添加额外的部分或标签，所有图标保持手绘风格，避免使用 Logo，避免水印，并全程保持粗糙的粉笔和颜料质感。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1181);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 皮克斯风格信息图故事板', '创建一个清晰、简洁的信息图故事板海报，主题为 {argument name="title" default="THE DONUT MAKER"}。采用 16:9 宽屏布局，白色背景，黑色边框，粗体黑色排版，{argument name="style" default="高级皮克斯 3D 风格渲染"}，明亮鲜艳的色彩——金黄色的油炸面团，浓郁的巧克力', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1182);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 扁平涂鸦风格照片转换', '使用提供的参考图，将其转换为简洁的涂鸦 / 扁平插画。精确保留原始构图、摄像机角度、房间布局、主体位置、室内外框架以及整体场景：即从客厅内透过落地玻璃门看向露台餐桌的视角。

风格：将照片转换为精致的扁平矢量风格卡通插画，使用简单形状、干净的黑色轮廓、中等粗细的线条、平涂色彩，且不含任何写实阴影或渐变。在保持所有主要物体可辨识的前提下，简化纹理和细节。

人物与布局：在户外餐桌周围保留与参考图中相对位置完全一致的 6 个人：左侧 1 位老年男性，桌后 1 位站立的成年人，中心附近 1 位老人，中右侧 1 位儿童，右侧 1 位儿童，以及最右侧 1 位成年女性。保持餐桌、椅子、食物、杯子、露台植物、玻璃门、窗帘、带靠垫的沙发、地毯和躺椅在原始位置。

色彩处理：使用受照片启发且温暖友好的平涂色彩：米色窗帘、奶油色沙发、红色装饰靠垫、条纹地毯、黑色窗框、棕色露台家具、灰色露台地面、黄色花园墙壁以及明亮的绿色植物和树木。

约束条件：禁止写实风格、禁止绘画笔触、禁止阴影、禁止排线、禁止增加人物、禁止添加文字、禁止水印。最终图像应呈现为基于参考照片制作的简洁编辑类扁平插画。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)', 'youmind-gpt-image-2', '["gpt-image-2","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1183);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 历史发明可视化公式', 'innovation_ripple_effect_for_{argument name="invention" default="[historical_invention]"} = ( mechanical_anatomy_exploded_view_of_{argument name="invention" default="[historical_invention]"} * 1.8 ) + ( information_velocity_graph_years_to_spread_idea_pre_vs_post_invention * 2.0 ) + ( cognitive_load_shift_diagram_how_society_processed_information_differently * 1.6 ) + ( economic_disruption_matrix_guilds_vs_industry_labor_shift * 1.4 ) + ( material_supply_chain_sourcing_map_for_the_invention * 1.3 ) - ( dusty_museum_artifact_photos / 3.0 ) - ( inventor_as_lone_genius_trope / 3.8 ) - ( boring_patent_office_drawings / 3.5 )', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1184);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 远征规划战略项目', '为正在规划 {argument name="mission type" default="[旅程 / 任务]"} 前往 {argument name="location" default="[目的地 / 时代]"} 的远征队长提供的战略指挥项目。左侧面板：详细的地形路线图，标注了航点、危险区域，边缘处设有时间轴。中央面板：所有装备的俯视平铺图，按整齐的行排列，每件物品均标注了重量和功能，标记了冗余项，不包含任何多余物品。右侧面板：远征进行中或抵达目的地时的场景，广阔景观中点缀着渺小的人物，比例感鲜明。视觉语言从制图的精确性，过渡到功能性清单记录，再到宏大的史诗级环境摄影。标题栏显示：“{argument name="expedition name" default="[远征名称]"} — [路线], [日期], [目标]”。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1185);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('YouTube 缩略图 - 身披铠甲的女战士与黑豹', '创作一张电影感暗黑奇幻肖像，主角为 {argument name="character name" default="Luna and me"}：一位年轻的女战士，双腿分开，强有力地站在画面中央，守护着身前坐着的一只黑豹。女战士拥有 {argument name="hair color" default="随风飘逸的长金发"}，神情沉稳自信，身穿饰有雕花纹路的镜面抛光银色全身板甲，配有层叠的肩甲、护手、胫甲以及一件深色的飘逸斗篷。黑豹是一只体型硕大、毛发油亮、双眼闪烁琥珀色光芒的黑豹，脖子上戴着精致的金色链条项圈，警觉地坐在女战士的双脚之间。她们身后，巨大的破损深红色丝绸旗帜如戏剧性的战旗般斜掠过天空，上面绣着隐约的金色图案。背景是一个宏伟的废弃仪式广场或战场，有黑暗的尖塔、零星的火光、漂浮的余烬、湿润且带有倒影的石地，以及乌云密布、偶尔透出亮光的蓝黑色风暴天空。采用低角度英雄式构图、中心对称，超精细写实奇幻艺术风格，高对比度光影，铬合金铠甲上的蓝色高光，旗帜带来的红色背光，雨水浸润的倒影，体积感氛围，聚焦于女性和黑豹，营造强烈的电影海报氛围。无文字，无水印，无额外动物，无额外人物。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","youtube 缩略图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1186);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('YouTube 缩略图 - 震惊的龙打开了散寿司', '创作一张电影级、高度细节化的奇幻写实图像，主角是 {argument name="character name" default="一位年迈的龙宫龙经理"}，场景设定在温馨的传统日式餐厅或龙宫午餐室，它在打开一个高级散寿司漆盒时感到震惊。主体是一条巨大的象牙白东方龙，拥有长长的蛇形身体、蓬松的白鬃、金色的角、金色的胡须、红色的腹部鳞片、锋利的爪子、惊恐突出的眼睛以及张开的焦虑嘴巴，正俯身在一张低矮的木桌上。龙用一只爪子举起黑红相间的漆器便当盖，因难以置信而僵住。方形漆盒内装满了丰富的散寿司：清晰可见 9 种主要的配料或食物元素，包括三文鱼片、白肉鱼、虾、红金枪鱼、黄瓜片、橙色鲑鱼籽、蛋丝、米饭，以及中心处一个蜷缩着的粉色小龙/章鱼状生物，作为意想不到的神秘物品。在盒子上方添加一个巨大的白色漫画标点符号，内容为 {argument name="reaction text" default="!?"}。背景应包括带有温暖夕阳余晖的障子窗、摆放陶瓷的木架、悬挂的日本书法卷轴和灯笼，桌上铺着蓝色花纹的桌旗，左侧放着瓷制清酒瓶和酒杯，右侧放着陶瓷茶壶和调味品托盘，以及包裹在花纹纸套中的筷子。使用浓郁的琥珀色光影、浅景深、逼真的质感、精细的鳞片、诱人光泽的食物、奇幻的惊喜感，以及 16:9 的宽画幅构图。在右下角添加一个蓝色的小型水印风格标题，内容为 {argument name="watermark text" default="Dragon''s Heaven"}。避免出现多余的角色，避免现代物品，并将场景聚焦于龙对寿司盒中小生物的震惊反应。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","youtube 缩略图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1187);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('YouTube 缩略图 - 吸睛的 AI 外貌咨询销售横幅', '目标：制作一款吸睛的日式社交媒体销售横幅，用于推广 AI 外貌咨询提示词包，设计风格参考高转化率的 X/Twitter 促销缩略图。

画布：宽屏 16:9 横幅，超高饱和度，光泽感，电影级广告设计。背景为爆炸式的金粉色金钱喷溅效果，伴有飞舞的日元硬币、纸币、火花轨迹、五彩纸屑和强烈的镜头光晕。

布局：左侧三分之一处设有一个可爱的吉祥物角色，身穿白色连帽衫和白色长裤，向前奔跑或倾身，双手向观众伸出。该角色拥有圆形的白色头盔状头部、黑色的 X 型眼睛和一张大大的黑色笑脸，类似于友好的无脸吉祥物。吉祥物上方有一个白色对话气泡，写着「今日から」，旁边配有一对巨大的红色感叹号。左下角设有一个黑金色的月桂徽章，写着「累計 5億」。

中心：视觉焦点是巨大的 3D 金属金色字体，带有戏剧性的斜面、阴影和发光高光。在顶部中心放置一个紫色丝带标签，写着「1件あたり」。下方展示主要价格堆叠：第一行「¥10,000〜」，第二行「¥20,000」，字体极大且呈金色。在价格下方，添加一条金色丝带，写着「今日から売れる」。

产品元素：在中心周围包含 3 个盒装产品/包装模型：1) 左中位置的一个深红色盒子，标注为「提案資料 一式」，带有一个小型文档预览；2) 中心左下方的一个较小的深红色盒子，标注为「プロンプト集」，带有一个聊天气泡图标；3) 右侧的一个深红色盒子，标注为「Before/After 画像」，展示两张女性侧面照片，并带有小的英文标签“BEFORE”和“AFTER”。

右侧：在右上角添加一个倾斜的红色橡胶印章图形，上面用英文写着“SOLD OUT”，带有透明的白色印章背景和做旧纹理。

底部排版：在底部横贯巨大的红金渐变 3D 日文字体，带有白色高光和深色投影，写着「1〜2万円／今日から売れる」。在其上方，在一条白金相间的横幅上，放置紫色文字「AI 外見コンサル完全プロンプト」。

视觉风格：极具冲击力的日本网络营销缩略图，奢华的金色、红色、紫色和洋红色调，高对比度，夸张的 3D 文字，发光轮廓，闪光效果，动态感，构图紧凑，营造出庆祝性的“金钱爆炸”氛围。

文字自定义：除非另有说明，否则请使用指定的日文文案：{argument name="main price text" default="¥10,000〜 ¥20,000"}, {argument name="bottom headline" default="1〜2万円／今日から売れる"}, {argument name="product name" default="AI 外見コンサル完全プロンプト"}, {argument name="top ribbon text" default="1件あたり"}, {argument name="stamp text" default="SOLD OUT"}.

限制：保持所有文字清晰易读，严格保留 3 个产品盒、1 个吉祥物、1 个对话气泡、1 个徽章和 1 个售罄印章。不要添加额外的徽标、水印或无关字符。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","youtube 缩略图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1188);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('YouTube 缩略图 - 电影感郊区追逐场景', '电影级超写实近距离追逐场景，摄像机位于逃跑丈夫前方不到一米处，极度特写视角，{argument name="man expression" default="惊恐"} 男子占据画面 80%，皮肤上的汗水、清晰可见的毛孔、充血的双眼、颈部青筋暴起，嘴巴大张发出惊恐的尖叫，凌乱的头发因奔跑向后飞扬，穿着皱巴巴的深色睡衣，丢了一只拖鞋。在他身后，背景略微失焦但清晰可见，愤怒的妻子穿着 {argument name="wife outfit" default="浴袍和毛绒拖鞋"} 从前门冲出，手中挥舞着高举过头的沉重铸铁平底锅，面部因无法抑制的愤怒而扭曲，头发向四面八方狂乱飞舞。早餐的混乱在两人之间爆发，破碎的咖啡杯、飞溅的吐司、炒蛋、凝固在空中的橙汁液滴，细小的碎片在阳光下闪烁。真实的郊区房屋入口、混凝土人行道、前草坪，地道的住宅区环境。使用 {argument name="camera model" default="Arri Alexa 35"} 拍摄，搭配 Zeiss Supreme Prime 35mm T1.5 镜头，摄影师在丈夫正前方倒退奔跑，电影级追逐摄影，仅在四肢和背景处保留真实的动态模糊，焦点锁定在丈夫惊恐的面部。黄金时刻的侧向晨光，物理级精准的皮肤渲染，次表面散射，自然阴影，眼中真实的倒影，纪录片风格的写实感，好莱坞喜剧电影画面，实用照明，Kodak Vision3 胶片模拟，细腻的胶片颗粒感，超写实，极致细节，RAW 照片画质，照片级真实，无 CGI，无卡通感，无 AI 感，无过度处理的 HDR，8K，杰作，屡获殊荣的电影摄影，动态荷兰式倾斜构图，极强的速度感与紧迫感，竖构图 --ar 9:16 --style raw --v 8', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","youtube 缩略图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1189);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('YouTube 缩略图 - 日式开发者评论横幅', '创建一个用于短视频叠加的透明背景装饰性日式下三分之一横幅。画布：宽横向 3:1 比例，约 1200×400 像素，艺术作品后方带有浅灰色棋盘格透明预览。主体：一个米白色圆角矩形对话气泡牌，横跨大部分宽度，带有分层偏移阴影以及细金线和淡蓝色轮廓描边，呈现出轻微的复古文具风格。布局：在牌子左上角放置一个小标签，内含一个带有代码括号的笔记本电脑圆形图标，标签文字为 {argument name="category label" default="开发人员评论"}；将主标题居中放置，使用优雅的大号日式明朝体书法，文字为 {argument name="headline text" default="如何删除 Heine"}，其中“删除”二字为柔和的蓝色，其余为黑色。在牌子内部左侧，包含 1 个面向右侧的水彩风格海豚插图，颜色为淡蓝灰色。在右上角，与牌子重叠处，添加 1 个带有扇形边缘的漫画爆破贴纸，米色轮廓，手写文字为 {argument name="sound effect text" default="叮"}，外加 2 个感叹号射线。装饰细节：在海豚、标题和右边缘周围分布 6 个小闪烁星；标题下方有 1 条细蓝色波浪下划线；右下中心附近有 4 个微小圆点；左右两侧有微妙的米色半调网点斑块；角落有精致的金色装饰花纹。视觉风格：柔和的奶油色、灰蓝色、柔和的金色，简洁的日式 YouTube Shorts 字幕图形，柔和的投影，清晰的矢量边缘与轻微的水彩质感相结合。约束：无人物或角色，无额外文字，保持横幅清晰易读并留有充足的空白空间，保留透明 PNG 叠加感。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","youtube 缩略图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1190);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('YouTube 缩略图 - Netflix 原创剧集电影感海报', '{argument name="platform" default="Netflix"} 原创剧集海报，特写肖像，表情强烈，电影级调色，戏剧性氛围，细腻胶片颗粒感，高端流媒体剧集美学，浅景深，超精细面部细节，获奖级摄影作品，8K 分辨率。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","youtube 缩略图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1191);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('YouTube 缩略图 - Reinecke Undine 森林标题卡', '为关于 {argument name="composer and work" default="Reinecke: Undine"} 的古典音乐视频制作一张电影质感的横向标题卡。使用 16:9 宽屏画布。场景设定为夜晚深邃的浪漫主义森林，弥漫着蓝灰色的雾气和水汽，底部边缘有一汪浅浅的倒影池。一道强烈的冷色月光从右上角斜射而下，照亮了位于画面中下方的一位幽灵般的水精灵（Undine），她身形娇小，留着极长的浅金色长发，身穿与雾气和水色融为一体的半透明银蓝色长裙。前景中需准确构图 9 棵醒目的黑色树干：左侧簇拥 5 棵，右侧 4 棵，顶部带有细长的垂枝和苔藓。整体氛围应充满神秘感、神话色彩和歌剧感，色调以深绿、黑、青蓝色雾霾为主，并辅以柔和的体积光。在左上角添加醒目的标题文本：共 2 行，第 1 行显示 {argument name="top title text" default="Reinecke:"}，使用白色、较小的粗体无衬线字体；第 2 行显示 {argument name="main title text" default="Undine"}，使用大号亮黄色粗体无衬线字体，并带有微妙的深色阴影。保持排版整洁且高度易读，画面其余部分不添加任何文字，无 Logo，无水印。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","youtube 缩略图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1192);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('YouTube 缩略图 - 巴库火焰塔航拍场景', '俯瞰 {argument name="landmark" default="火焰塔"} 的旅程。 {argument name="city" default="阿塞拜疆首都巴库"}。 一 {argument name="flock" default="群飞鸟"} 缓缓掠过海风。 其中混入了一只 {argument name="hidden character" default="白鹅"}。', 'https://img.shields.io/badge/Language-JA-blue', '![](https://img.shields.io/badge/Language-JA-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","youtube 缩略图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1193);
