INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('漫画 / 故事板 - 未来感动漫战术概念设计图', '超精细未来感动漫角色设计图，将 {argument name="character theme" default="龙珠 Z 红缎带军团人造人"} 重构为现代赛博朋克战术特工。全身正面视图，时尚概念艺术，超大款机能风夹克，工装裤，作战靴，多功能绑带，搭扣，战术背带，工业标签，编号补丁，红缎带军团徽章，单色系服装搭配各人造人专属的醒目点缀色（16 号为绿色，17 号为黑/橙色，18 号为蓝/白色，8 号为海军蓝，13-15 号为军橄榄色）。{argument name="background style" default="干净的白色海报背景，带有喷溅油漆效果"}，技术图解，条形码图形，排版设计，日文文本，警告标签，角色数据，杂志封面布局，产品设计图美学。锐利的动漫脸部轮廓，高细节织物，逼真的褶皱，高级运动鞋设计，电影级光效，清晰的线条，动态姿势，高对比度，颗粒感纹理，都市军事风，高级概念插画，ArtStation 品质，AAA 游戏概念艺术，超精细，8k，构图平衡。
风格关键词
未来感机能风
赛博朋克军事风
动漫 × 街头服饰
工业图形设计
战术时尚
红缎带军团美学
角色概念设计图
白色极简海报
油漆喷溅图形
杂志封面布局
高级时尚插画
高度精细的服装
