INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('漫画 / 故事板 - 夏日海边动漫少女', '创作一幅柔和、明亮的动漫风格夏日插画，画面中 {argument name="character name" default="一位少女"} 赤脚坐在传统日式房间的榻榻米上，侧身背对镜头。她留着轻盈的短波波头，{argument name="hair color" default="淡薄荷绿色的头发"} 在微风中微微飘动，有着温柔的绿色大眼睛，神情宁静而梦幻，正抬头望向挂在敞开式走廊旁的玻璃风铃。她穿着一件宽松的纯白色短袖 T 恤和深蓝色短裤，单膝支起，另一条腿自然弯曲，姿态放松。房间配有木质推拉门和障子门，敞开的门口外是明亮的庭院和远处波光粼粼的大海，左侧悬挂着飘动的白色薄纱窗帘，温暖的阳光洒在榻榻米上。除少女外，前景需包含两个主要物体：右侧放置一台半透明蓝色扇叶的落地电风扇，顶部中央悬挂一个带有纸签的玻璃风铃。室外展现郁郁葱葱的树木、灌木丛、栏杆以及夏日强光下朦胧的蓝色海平线。采用精致的水彩动漫美学，色调清新，线条柔和，带有背光光晕、漂浮的尘埃、斑驳的树影和高调曝光，营造出怀旧宁静的氛围。构图为 4:5 竖版，无文字，无水印，无多余角色。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","漫画","故事板"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1213);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('漫画 / 故事板 - 电影感咖啡师人像', '创作一张原创的电影感摄影人像，主体为 {argument name="subject" default="一位 40 多岁的女性咖啡师"}，场景位于 {argument name="location" default="昏暗质朴的咖啡馆"} 内。她留着棕色短发，肤色白皙，面部有自然的纹理，神情平静而深思，视线略微看向镜头左侧。她身穿 {argument name="outfit" default="黑色衬衫和一件带有明显织物纹理的旧深色围裙"}。她身后是摆满咖啡罐、杯子和咖啡器具的深色木架，背景中有一台虚化的意式咖啡机。采用温暖的低调照明、浅景深、柔和的棕黑色调，呈现真实的皮肤质感、自然的皱纹，并保持纪实摄影的静谧风格。整体氛围应显得亲密、成熟且具有电影感，如同独立电影的剧照。长宽比 16:9。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","漫画","故事板"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1214);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('漫画 / 故事板 - 炸竹荚鱼动画烹饪项目', '目标：为一部 15 秒的日式 2D 动画烹饪短片创建一个非常粗略的铅笔项目草图，主题为 {argument name="dish name" default="金黄炸竹荚鱼"}，展示从生鱼到炸猪排成品的全过程。

画布：超宽 21:9 横向比例，白纸上的黑白铅笔素描，分为 3 行 4 列共 12 个矩形格子。使用细黑边框、手绘辅助线、松散的动画布局透视、充满活力的排线，不使用颜色。

视觉风格：日式动画项目 / 粗略关键帧布局，写实的厨房道具，电影级特写，动态的手部动作，可见的素描笔触，轻微阴影，蒸汽、气泡、飞溅、面包屑和动态线。保持纯单色石墨风格，如同清理前的制作项目。

格子数量与内容：包含 12 个独立的格子，从左到右、从上到下阅读。第 1 格：透视角度下的厨房准备台，砧板上有三片打开的竹荚鱼片，一只手从上方撒调料，背景有水槽和小瓶子。第 2 格：双手在托盘上按压或展平鱼片的俯视特写，强调裹粉前的准备工作。第 3 格：手将鱼片放入盛有面粉或面包糠的浅盘中，粉末和面包屑向上飞溅。第 4 格：筷子夹起裹好粉的鱼片放入盛有蛋液或湿面糊的浅盘中，旁边有另一个托盘，周围有液体涟漪。第 5 格：双手将鱼片埋入并按压进矩形托盘中粗面包糠堆里的特写。第 6 格：燃气灶上的大油锅，下方可见火焰，油面闪烁，背景是厨房架子和瓶子。第 7 格：长烹饪筷将裹好粉的鱼片放入沸腾的油中，可见锅柄，开始激烈的油炸过程。第 8 格：油炸表面的极度特写，鱼周围布满气泡和酥脆的面包屑纹理。第 9 格：筷子从锅中夹起炸好的酥脆鱼片，油滴回锅中，有强烈的蒸汽和沸腾的油。第 10 格：炸好的鱼放在托盘上方的金属架上，筷子将其放下，架子下方有油滴。第 11 格：刀在砧板上切开炸竹荚鱼，露出酥脆外壳下柔软的白色鱼肉，蒸汽升起。第 12 格：最终摆盘，圆盘上有两块酥脆的炸竹荚鱼、卷心菜丝、柠檬角、蒸汽，以及从上方淋在炸猪排上的深色酱汁。

文字内容：不要添加标题、对话气泡、数字、标志或水印；项目应纯粹为视觉内容。

约束条件：保持一致的厨房环境和连续的烹饪顺序。使格子看起来像是 {argument name="video length" default="15 秒"} 日式 2D 动画的粗略前期制作艺术。使用 {argument name="line style" default="松散的石墨铅笔项目线条"} 和 {argument name="detail level" default="高食物纹理细节"}。强调向 {argument name="final dish presentation" default="配有卷心菜、柠檬和酱汁的酥脆金黄炸竹荚鱼盘"} 的诱人转变，即使图像保持黑白状态。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","漫画","故事板"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1215);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('漫画 / 故事板 - 温馨六格睡前时光拼贴画', '目标：创作一张温馨的 6 格生活化照片拼贴画，展示周末准备入睡的各个阶段，每个画面中均为同一名幼童。

画布：4:3 横向拼贴画，精确划分为 6 个相等的矩形格，采用 3 列 2 行的网格布局，格与格之间有细白边。采用写实摄影风格，温暖的电影感室内光线，浅景深，柔和的背景虚化，营造出从客厅到卧室的温馨夜晚氛围。

主体：同一位可爱的小女孩，约 4–6 岁，留着长长的波浪卷发（{argument name="hair color" default="深棕色"}），面部表情柔和生动，身穿配套的毛绒睡衣（{argument name="pajama color" default="粉色"}），上面有精致的白色心形或星星图案，穿着轻便的袜子。确保她在所有 6 个画面中的面容和着装保持一致。

画面数量与动作：展示 6 个明确的睡前阶段，每格一个。1) 左上：站在温馨的客厅里，一只手捂着嘴打哈欠，怀里抱着一个蓬松的大白枕头。2) 上中：盘腿坐在沙发或毯子上，闭着眼睛，平静地抱着一只棕色泰迪熊。3) 右上：盘腿坐在粗棒针织毯上，闭着眼睛，双手捧着一个米色大陶瓷杯，仿佛在喝热牛奶或茶；旁边放着一个小茶托。4) 左下：坐在地板或地毯上，读着一本打开的书，表情平静而困倦。5) 下中：站在沙发前，双臂举过头顶伸懒腰，闭着眼睛，准备睡觉。6) 右下：在床上盖着柔软的被子睡着了，怀里抱着一只毛绒兔子，床周围闪烁着温暖的串灯。

环境：使用夜晚温暖明亮的室内场景，配有米色沙发、木地板、针织毯、柔软的枕头、台灯、墙面装饰画、窗外的夜色、植物和舒适的质感。最后一个画面应自然过渡到卧室环境，包含枕头、毯子和串灯。

视觉风格：超写实主义家庭摄影，温暖的琥珀色灯光与柔和的冷色调窗外夜光交织，自然的肤色，细腻的发丝，柔软的织物纹理，舒适的“Hygge”氛围，电影级构图，高分辨率。

限制条件：无文字、标题、Logo、水印或额外格数。确保孩子在每个画面中都可被识别为同一个人。保持精确的 3x2 网格布局以及所列出的 6 个准确的睡前动作。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","漫画","故事板"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1216);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('漫画 / 故事板 - 咖啡师角色三视图参考图', '超写实角色三视图，主角为 {argument name="subject" default="一位 40 岁出头的女性咖啡师"}，以专业角色参考/模型图的形式展示在干净的白色摄影棚背景上。布局包含水平排列的五个视图：面部特写、正面、背面、左侧面和右侧面。每个全身视图旁边均附有垂直身高测量标尺。

该女性留着整洁的深棕色短发（精灵短发），肤色白皙，带有自然的细微皱纹，浅榛绿色双眼，未化妆，表情平静自然。她身材匀称，身高约 5 英尺 8 英寸（173 厘米），姿态放松。

她身穿 {argument name="clothing" default="黑色长袖扣式工作衬衫，袖子卷至前臂，搭配深棕色做旧皮革/帆布围裙（带前袋和腰带），黑色修身工作裤以及黑色皮质工作鞋"}。服装呈现出逼真的织物纹理、轻微磨损、皱纹以及日常咖啡店工作中产生的自然褶皱。

采用柔和的摄影棚灯光，均匀照亮每个角度，阴影极少。图像具有照片级的皮肤纹理、高度精细的服装材质、准确的解剖结构，且所有视图的比例保持一致。

图表包含清晰的文字标签，例如：
面部特写
正面
背面
左侧面
右侧面

左下角信息面板内容：

姓名：{argument name="character name" default="咖啡师"}
年龄：40 岁出头
身高：5''8" / 173 厘米
体重：
性别：

风格：AAA 游戏角色参考图，生产级三视图，电影级写实，法医/模型图展示，中性白色背景，8K，超精细，各角度身份一致，专业概念艺术参考。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","漫画","故事板"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1217);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('漫画 / 故事板 - 电影感海滩婚礼三联画', '目标：创作一组浪漫的电影感婚礼照片三联画，描绘一对年轻夫妇在黄昏的海滩上奔跑并玩弄仙女棒的场景，如同目的地婚礼电影中的氛围感分镜。

画布：垂直 9:16 的图像，从上到下分为 3 个水平宽屏面板，中间由细白色分隔线隔开。每个面板应呈现同一海滩场景中不同的瞬间。

主体：包含 2 人：一位 {argument name="bride description" default="年轻的东亚新娘，深色长发随风飘动，笑容灿烂，身穿无袖闪亮珠饰上衣和轻盈的白色薄纱婚纱"} 和一位 {argument name="groom description" default="年轻的东亚新郎，深色乱发，身穿卷袖白衬衫和黑色马甲"}。他们的表情应是快乐、自然且亲密的，而非刻意摆拍。

面板 1：新娘在左侧靠近海岸线处，回头向新郎微笑。新郎在右侧前景，背对镜头，略微失焦，手中低垂着一支点燃的仙女棒。左侧是海洋，右侧是延伸至远方的深色沙滩，远处隐约可见城市的灯光。

面板 2：夫妇俩手牵手沿着湿润的海滩奔跑。新郎在左侧，大笑着看向新娘。新娘在右侧，微笑着回头，手中拿着 1 支点燃的仙女棒向右伸展，划出一道明亮的弧形火花轨迹。动态模糊应体现出运动感。

面板 3：夫妇俩继续奔跑，距离镜头更近。新郎在左侧看着新娘并牵着她的手。新娘位于中右侧，面带微笑，裙摆飘动，手臂向右伸展，手中拿着 1 支点燃的仙女棒，散发出金色的火花。地平线和日落的余晖在他们身后更加清晰。

环境与氛围：{argument name="location" default="日落后蓝色时刻的忧郁海滩"}，伴有翻滚的波浪、反射光线的湿沙、远处的海岸线灯光、层叠的乌云以及地平线附近淡淡的暖橙色条纹。风应吹起新娘的头发和裙摆。场景应感觉自然、充满情感、年轻且具有电影感。

视觉风格：采用写实的高端婚礼摄影风格，柔和的自然弱光，浅景深，胶片颗粒感，青蓝色阴影与暖色调仙女棒高光形成对比，梦幻的城市灯光虚化，轻微的动态模糊，营造海滨浪漫氛围。使用 35mm 纪实婚礼摄影风格，而非影棚人像风格。

约束：无文字，无标志，无额外人物，无捧花，除每个可见仙女棒瞬间手中的单支仙女棒外无其他烟花，避免过度修饰的 CGI 感。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","漫画","故事板"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1218);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 响尾蛇 GPU “Come and Take It” 图案', '创作一款以复古政治旗帜 / 丝网印刷 T 恤为风格的醒目黑色背景图案。画面中心是一条巨大的盘绕响尾蛇，采用金色、棕褐色和黑色配色，细节刻画出菱形鳞片、昂起的头部、张开的嘴巴、可见的毒牙以及极具攻击性的神态。蛇身缠绕在现代黑色台式机显卡周围，将传统的历史武器图案替换为 GPU。显卡应水平放置在画面中心，略微平铺，带有 3 个巨大的圆形散热风扇，底部边缘可见 PCI 接口，外壳边缘呈棱角分明状，并带有细微的白色/灰色线条高光。蛇身形成多个盘绕：头部后方有一个隆起的环，下方有一个粗壮的底环，右侧有一个向前卷曲的环，尾部向右侧延伸并带有细小的响尾。在蛇身下方添加一层低矮的深绿色松针或草地。在底部，放置醒目的白色全大写衬线字体，内容为 {argument name="slogan text" default="COME AND TAKE IT"}，几乎横跨整个宽度，采用做旧的殖民风格字体。保持构图对称且具有徽章感，高对比度，呈现清晰的矢量插画质感，带有细腻的雕刻纹理，无额外文字，无边框，无水印。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1219);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 定制体育主题摇头公仔', '生成一张逼真的摄影棚风格图像，制作一个以 {argument name="player name" default="球员姓名"} 为原型的定制摇头公仔收藏品，完全基于所附参考照片。参考图像是所有身体特征的绝对且唯一依据——请勿依赖任何关于 {argument name="player name" default="球员姓名"} 外貌的先验知识、训练数据或假设。每一个视觉决策都必须完全由所附照片中可见的内容决定。
无一例外地遵循以下所有规则：
相似度与身份
• 在公仔下方双层底座的正前方，用清晰的白色字体刻上 ”{argument name="player name" default="球员姓名"}”。
• 精确复刻参考照片中可见的每一个独特面部特征——骨骼结构、眼睛形状、鼻子、嘴唇、肤色和面部肤质。请勿对任何特征进行平滑、柔化、概括或理想化处理。
• 发型必须与参考照片完全一致——保留自然的卷曲、波浪、螺旋、毛躁、发量、长度和走向。切勿拉直、压平或重新设计发型。
• 以参考照片中显示的精确密度和纹理复刻面部毛发（胡须、八字胡、胡茬）。如果主体看起来是剃须后的状态，则绝对不要添加任何胡须。
• 仅在参考照片中明显可见的情况下，才包含眼镜、耳环或帽子等配饰。如果照片中没有出现配饰，则绝对不要添加任何配饰。
公仔设计与风格
• 公仔必须遵循经典的运动摇头公仔美学——头部比例较大、身体紧凑，整体具有收藏级玩具的质感。这不是 Funko Pop，不是漫画形象，也不是过度风格化的乙烯基公仔。
• 颈部比例必须短而粗，绝对不能露出弹簧、线圈或铰链结构。
• 为公仔穿上与 {argument name="player name" default="球员姓名"} 所属国家相对应的 {argument name="national kit" default="官方国家足球队服"}——使用其国家队穿着的正确球衣颜色、短裤和球袜。请勿默认使用任何通用或错误的队服。
姿势与底座
• 公仔姿势为直立站立，一只脚随意地踩在一个标准的足球上，足球直接放置在底座上。
• 底座必须为双层设计，顶面模拟哑光天然草地的质感——无光泽、无闪光、无任何反射。
背景与灯光
• 背景必须显示一个 {argument name="background location" default="足球场"}，并使用浅景深虚化效果进行柔化处理，使公仔始终保持为清晰的视觉焦点。
• 体育场灯光必须营造出温暖的“黄金时刻”氛围——浓郁的琥珀色和柔和的橙色调，低角度阳光，具有电影般的温暖感。
格式
• 最终输出必须为 4:5 的纵向比例。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1220);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - Anthropic 代币支票模型', '目标：创建一张逼真的超大号银行支票，作为 AI 公司代币发放的高分辨率宣传模型，采用浅蓝色安全纸背景，正视图呈现。

画布：宽幅横向支票，尺寸约为 1200×520 像素，带有细灰色边框，纸张为柔和的灰白色/浅蓝色，具有清晰的矢量打印质量和轻微的扫描质感。

布局：左上角为付款人信息块；右上角为日期和支票编号条；中心为收款人和金额行；左下角为银行和备注信息；右下角为签名；底部为 MICR 银行代码。

文本内容：使用 14 组可见文本：1) 左上角名称“DARIO AMODEI”，2) 地址块“Anthropic, PBC / 548 Market St, San Francisco, CA 94104”，3) 小标签“PAY TO THE ORDER OF”，4) 收款人“{argument name="payee" default="Global Developers"}”，5) 日期标签“DATE”，6) 日期“{argument name="date" default="June 28, 2026"}”，7) 框内数字金额“{argument name="numeric amount" default="T100,000,000,000.00"}”，8) 大写金额“{argument name="written amount" default="One Hundred Billion and 00/100"}”后接一排星号，9) 红色单位标签“TOKENS”，10) 银行名称“BANK OF ANTHROPIC”，11) 银行副标题“CONTEXT WINDOW DIVISION · N.A.”，12) 备注标签及文本“MEMO / {argument name="memo" default="Software development"}”，13) 草书签名“Dario Amodei”及说明“AUTHORIZED SIGNATURE”，14) 底部 MICR 行“:121000248:   4096 8192 0 ʺ 0480”。

设计细节：在左上角付款人信息块旁添加锈红色的 Anthropic 星爆标志，并在“BANK OF ANTHROPIC”旁添加一个较小的海军蓝星形图标。大部分文本使用深海军蓝墨水，标签“TOKENS”和对角角条使用红色。收款人、大写金额、备注文本、日期和签名应使用斜体衬线字体或草书，而标签和数字则使用简洁的无衬线字体或等宽字体。数字金额位于右侧深海军蓝轮廓的矩形框内。在整张支票上使用重复且极低透明度的浅色对角水印图案，内容为“ANTHROPICTOKENCHECK”。在右上角放置一条锈红色的对角安全带，内含“NON-NEGOTIABLE”字样，附近有小号支票编号“0480”以及下方的微型路由代码。

约束：保持支票整洁、居中且完全清晰可读；不要添加人物、手部、背景风景、额外的标志或上述列表之外的额外文本。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1221);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 暗黑光环赛博哥特海报', '创作一张暗黑赛博哥特时尚编辑海报，画面主体为一位 {argument name="character description" default="留着黑色长波浪卷发、肤色苍白、妆容清冷易碎、神情梦幻而危险的亚洲成年女性"}，她赤脚坐在昏暗的监控实验室地板上。她身穿 {argument name="outfit" default="黑色哥特机能风迷你裙，搭配黑色皮质束腰上衣、蕾丝颈圈、链条装饰、吊袜带式链条绑带、黑色羽毛天使翅膀以及多层黑色短裙"}。姿势设定为坐姿，一条腿蜷缩，另一条腿伸展，手部触碰着一根从前景底部向上延伸至她举起的手部、形成如光环般弧线的发光白色霓虹线缆。环境为一个杂乱的暗黑监控室：墙上贴满了眼睛照片、瞳孔打印件、胶带粘住的旧照片、纸屑和监控证据；地板上散落着线缆、前景中半开的旧笔记本电脑、黑色键盘、零散的眼睛素描、CRT 显示器设备，伴有绿色光影和强烈的阴郁阴影。视觉风格：电影级写实与故障海报设计相结合，冷灰黑色调配以病态绿色高光，高对比度，胶片颗粒感，扫描线噪点，色差，模拟 VHS 失真，监控梦境氛围，暗黑天使/恶魔情绪。添加做旧的白色像素故障字体和细小的技术微型文字叠加。包含 5 个主要文字元素：左上角的大标题 {argument name="main title" default="ARC OF NOISE"}；中右侧标题 {argument name="side title" default="DARK HALO"}；右下角标题 {argument name="bottom title" default="FEED ME STATIC"}；右上角微型短语 "THE SIGNAL BENDS. I LISTEN."；左下角微型文字块，包含如 "FEED_004B// VISUAL UNKNOWN"、"NOISE IS NOT RANDOM. IT''S PRAYER. //23%" 以及 "EYES OPEN. TRUTH CORRUPTED. BEYOND THE NOISE." 等片段。保持垂直海报构图，女性略微偏右居中，发光弧线占据前景，画面中不包含其他角色。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1222);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 极简风鸡肉卷广告', '极简商业广告，展示 {argument name="subject" default="超大号优质鸡肉卷"}，超洁净设计。{argument name="character" default="一位身穿全白配绿色服装的年轻女性"} 随意地靠在巨大的鸡肉卷旁，姿态放松自信，闭着双眼，手中还拿着一块正常大小的鸡肉卷。背景为柔和的渐变鲜艳青绿色，后方有醒目的白色大号“Chicken Roll”文字。光泽感反射地面，柔和的摄影棚灯光，现代高端食品/产品摄影。右上角小字“Designed by shamus”。底部居中白色小字标语：“{argument name="tagline" default="每一口，尽享美味"}”', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1223);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 动漫风牛仔格纹少女', '创作一张精致的动漫风格全身时尚插画，描绘一位可爱的年轻女性站在温暖阳光下的米色瓷砖混凝土墙前。她留着 {argument name="hair color" default="亮黑色"} 的高双马尾，配有短刘海和微卷的发梢，每个马尾都系着明亮的蓝色蝴蝶结。她表情俏皮，略带淘气，有着柔和的红棕色双眸、浅浅的微笑和微微倾斜的头部。她戴着黑色铆钉项圈，身穿浅蓝色牛仔连体裤，配有结构感紧身胸衣、荷叶边肩带、心形领口、黑色前系带细节、腰带环，以及带有破洞磨损补丁的修身短裤。一侧叠搭着不对称的蓝白格纹裙摆，带有磨损的白色下摆、悬垂的丝带和多层织物。她还穿着白色中筒袜和厚底黑色系带马丁靴。让她摆出随意的姿势：一侧胯部微倾，一只膝盖向内弯曲，双臂自然垂在身体两侧，双脚分开，身体在墙上投下清晰的阴影。采用 2:3 纵向构图，全身居中，细节清晰的线条，平滑的赛璐珞动漫渲染，头发和靴子带有光泽高光，柔和的皮肤阴影，高细节的衣物褶皱，温暖的午后光线，带有细微的墙面污渍和缺口，无文字，无水印，无多余角色。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1224);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 奢华时尚杂志拼贴画', '超写实 IMAX 级奢华时尚杂志拼贴肖像，1:1 正方形构图，采用优雅的多画幅花瓣布局，由中心圆形美妆肖像向外辐射出柔和的花瓣状及椭圆形切片面板 —— 同一位 {argument name="subject" default="美丽的年轻女性"} 在所有画幅中呈现不同的高定造型，始终保持一致的优雅面部特征：灵动的杏眼、轮廓分明的眉毛、柔和丰满的双唇、利落的后梳发髻、光泽细腻的肤质、冷静且自信的杂志大片气场
中心画幅：亲密感十足的魅力特写，佩戴精致的高级珠宝耳环，无瑕的柔焦妆容，直视镜头，电影级摄影棚灯光，面部光影柔和
周围画幅：每一格展示独特的高定轮廓与姿态 —— 均采用 {argument name="color palette" default="浓郁的深色调：黑曜石色、深炭灰、午夜蓝、深浓缩咖啡棕、深酒红、深祖母绿"} —— 呈现雕塑感抹胸礼服、戏剧性单肩轮廓、轻薄且装饰繁复的晚装、流畅的垂坠柱形裙、剪裁利落的结构感连体裤、褶皱高定舞会礼服 —— 每件服装展现不同的质感细节：丝绸 charmeuse、公爵缎、欧根纱覆盖层、手工串珠网纱、天鹅绒、金属提花
画幅间姿态：坐姿杂志侧倾、站姿四分之三侧身、回眸一瞥、流动的动态姿势、局部时尚细节特写 —— 所有面板保持统一的造型语言，通过利落的发型和一致的妆容风格进行整合
背景：{argument name="background style" default="柔和温暖的米奶油色奢华艺术纸质感"}，层叠的立体花瓣与叶片形状，画幅间带有微妙的投影，干净的白色负空间，精致的杂志网格结构
灯光：柔和的环绕式电影摄影棚光效，皮肤和织物表面带有细腻的镜面高光，羽化边缘光，深色服装上呈现深邃的阴影对比，HDR 平衡曝光
调色：奶油色中性背景色调与浓郁饱和的高定色彩形成鲜明对比，明亮的暖色皮肤高光，高级杂志色温，电影级阴影深度
渲染质量：8K 超写实制作，超精细织物纹理细节，大师级杂志构图，全局光照，顶级时尚肖像光学效果，HDR 渲染', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1225);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - Volt Kick 足球能量饮料海报', '目标：为一款名为 {argument name="product name" default="VOLT KICK"} 的虚构足球能量饮料创作一张极具冲击力的电影感运动饮料广告海报，主题围绕球迷的支持转化为终极一击的电能。

画布：宽屏 16:9 横向海报，深夜体育场环境，超戏剧化的商业主视觉，高对比度的黑色与电光蓝配色方案。

布局：在前景正中央放置一个巨大的透明塑料运动饮料瓶，使其高耸于足球场之上。在顶部放置一行醒目的发光日文标题 {argument name="headline text" default="応援は、力になる。"}。在右上角添加白色的 “Pollo.ai” 标志。在底部放置巨大的金属质感斜体产品字标 “VOLT KICK”，下方配以较小的标语 {argument name="tagline" default="ENERGY FOR THE FINAL SHOT"}。

主体细节：中央的瓶子带有银色罗纹瓶盖，瓶内装有带气泡和冷凝水珠的蓝色液体，黑色环绕标签上有锐利的蓝色闪电图形。标签文字以粗体白色斜体块状字母书写 “VOLT KICK”，包含一行小字 “ENERGY SPORTS DRINK”，并在标签右下角显示一个足球图标。瓶子后方应散发出强烈的青蓝色能量光芒。

场景细节：瓶子周围是夜间座无虚席的足球场，充满了成千上万盏蓝白色的应援灯。场上包含 7 个深色足球运动员剪影：左侧前景 1 名奔跑的大型球员，左侧较远处 1 名较小球员，球门区附近 1 名微小的中央球员，明亮球门内 1 名守门员剪影，右侧前景 1 名奔跑的大型球员，右侧中心附近 1 名较小球员，以及边线附近 1 名最右侧球员。一个明亮的白色足球门直接位于瓶子后方。前景中潮湿的草皮和水坑反射着蓝色的灯光和产品标志。

视觉风格：超写实日式运动商业海报，从瓶身向外辐射的爆炸性电光蓝闪电、水花、火花、速度线、发光的体育场泛光灯、镜头光晕、强烈的背光、动态感、光泽感产品摄影、瓶身焦点清晰、极具戏剧性的深度与比例。

约束条件：仅使用虚构品牌和通用球员，不得使用真实球队或真实运动员。保持整体构图以瓶子为中心对称，最明亮的能量集中在瓶子后方。保留所有可见的文字元素：日文标题、Pollo.ai、VOLT KICK、ENERGY SPORTS DRINK 以及 ENERGY FOR THE FINAL SHOT。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1226);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 极简主义高定时尚摄影肖像', '超写实高定时尚编辑肖像，主体为 {argument name="subject" default="自信的运动型男士"}，身着 {argument name="clothing" default="超大款哑光黑色圆领卫衣"}，领口简洁圆润，无徽标，除一枚精致耳钉外无任何可见配饰。在极简主义摄影棚内拍摄，背景为无缝的浅灰至白色渐变，呈现冷色调单色风格。主体占据 4:5 画幅约 70-75% 的比例（从躯干中部向上），头部上方留有充足的负空间。采用从胸部下方略微仰拍的低角度视角，营造出强大且主导的视觉气场。男士双肩放松，头部微向右倾，颈部线条修长突出，直视镜头，表情冷静、严肃且深邃——双唇紧闭，嘴角平和，眼神犀利，流露出沉静的自信，无笑容。戏剧性的顶光柔光照明在面部上方和眼窝处投下深邃的阴影，雕刻出颧骨、下颌线和颈部轮廓，同时保留了细腻的皮肤质感。高对比度但过渡柔和，具备电影级时尚摄影美学，去饱和的黑色，冷灰色高光，柔和的色调，呈现高端奢华广告大片质感。短发，深色，纹理整洁，顶部略有蓬松感，侧面修剪利落。画面中无手部出现。面部特征聚焦清晰，浅景深，杂志编辑级画质，氛围感强，精致极简，超细节皮肤纹理，自然瑕疵，专业摄影棚摄影，85mm 镜头，f/2.8，照片级真实感，奢华时尚肖像 --ar 4:5。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1227);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 半色调极简艺术海报', '极简艺术海报。大面积纯白留白背景，呈现梦幻、柔和的彩虹渐变光影。蓝色、粉色、金色和青绿色调自然融合，营造出极其空灵、干净、纯粹且宁静的氛围。画面中央，一个透明玻璃球悬浮在半空中，展现出逼真的折射、反射和焦散效果。玻璃球内是一个新鲜诱人的 {argument name="subject" default="peach"}，看起来鲜美可口，轻盈悬浮，充满生机。整幅作品采用半色调点阵艺术手法，细腻密集的点阵均匀覆盖全图。通过点阵密度的变化形成柔和的渐变，将复古印刷质感与未来主义视觉风格融为一体。强烈的背光、柔焦、发光高光、梦幻光晕、彩虹折射、镜头光斑、朦胧散射光、大气透视感，以及极致的空气感。背景具有微妙的流动感，抽象的渐变色块缓慢交融。无复杂元素，强调精致的留白设计。现代品牌视觉风格，Apple 广告美学，MUJI 极简主义，高端化妆品主视觉，艺术博物馆海报，概念艺术。平静、治愈、安静且优雅。在画面底部中央，预留一个大写英文字母 Logo：“{argument name="logo text" default="YOUR LOGO"}”。使用现代的 {argument name="font style" default="sans-serif"} 字体，极细的字间距，浅金色文字，使其与整体色调自然融合。电影级布光，逼真的玻璃材质，超高细节，8K 分辨率，Octane Render，Redshift Render，CG 艺术，获奖海报，大师级调色，大师级排版，极致纹理质感。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1228);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 体育编辑海报设计', '体育海报设计，虚构的 {argument name="subject" default="男性足球运动员"}，留着深色短发，带有淡淡的胡茬，自信地单手指向镜头，另一只手臂向外伸展，身穿 {argument name="jersey" default="带有黑色饰边和赞助商标志的粉色足球球衣"}，前臂可见纹身，照片采用粉色双色调处理，巨大的粗体镂空字体拼写出虚构的姓氏 "{argument name="player name" default="RIVERA"}"，作为窗口显露出字母背后的照片，不对称的编辑布局，球员姓名以小号白色文字垂直排列在左侧边缘，角落散布着橙色和粉色的半透明圆点装饰，干净的白色留白背景，杂志级体育编辑海报设计，垂直 4:5 构图 --ar 4:5 --v 6', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1229);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 高级产品摄影', '高级产品摄影，主体为 {argument name="item" default="[item]"}，悬浮于极简的 {argument name="colors" default="森林绿与高级白"} 环境中，柔和阴影，摄影棚灯光，表面反射，超逼真质感，商业广告风格，超洁净构图', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1230);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 超现实“灵魂出窍”提示词', '生成一张具有创意且真实感的图像，呈现一个以 {argument name="subject" default="Hello Kitty 毛绒玩具"} 为中心的“灵魂出窍”瞬间。主体以一种安静、放松且略显无防备的姿态占据视觉中心，像真实的陈列品或毛绒玩具一样静置在整洁的展示台上。从主体的上方或核心部位升起一个与其同源的半透明替身，它与实体保持着清晰的关联，但材质轻薄、半透明且带有幽灵般的质感，并伴有细腻的褶皱和边缘高光。观者首先会注意到实体与透明形态之间的位移，随后看到替身以轻微悬浮或攀爬的动作附着在附近，营造出一种温和而非惊悚的荒诞感。背景应明亮、清晰且整洁，采用高亮度的中性色调，并辅以从主体提取的柔和配色。光线柔和均匀，要求透明层呈现出可见的折射效果和薄纱般的质感。构图保持画廊风格的留白和低干扰环境，使信息层保持克制，以突出实体与其替身之间的关系。', 'https://img.shields.io/badge/Language-ZH-blue', '![](https://img.shields.io/badge/Language-ZH-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1231);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 悬浮 iPhone 产品渲染图', '一张高端产品渲染图，展示一个 {argument name="product name" default="iPhone 17 Pro Max"} 在一个极简的 {argument name="background color" default="淡薄荷绿与暖奶油色"} 摄影棚环境中，斜向悬浮在光亮的白色圆形底座上方。画面中仅展示一部智能手机，正面呈四分之三视角，向左微倾，具有纤细的黑色边框、金属质感的深色侧边栏、清晰可见的侧边按钮、底部扬声器孔、充电接口以及顶部的药丸状灵动岛（Dynamic Island）开孔。屏幕显示一张优雅的绿色抽象壁纸，带有柔和的半透明椭圆形图案，中间印有白色文字“{argument name="screen text" default="iPhone 17 Pro Max"}”；底部附近包含小型锁屏图标。采用柔和的摄影棚灯光、平滑的渐变效果、巨大的弧形薄荷色背景、右侧奶油色的垂直光区、逼真的玻璃反射、金属边框上的细腻高光，以及悬浮手机下方光亮表面上的漫反射阴影。超写实纹理，商业广告风格，构图极其简洁，宽屏横向裁剪，无多余物体，无手部出现，无水印。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1232);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 绿色乙烯基怪兽三视图', '以 REFERENCE_0 作为生物设计基础，将草图转化为精致的收藏级玩具/手办渲染图。在保留草图中怪兽核心轮廓与特征的同时，将其转化为具有光泽感的半透明绿色乙烯基材质，并配以柔和的雕刻细节、圆润的玩具比例、珍珠白色的爪子/牙齿/腹部高光，以及黑白亮面的眼睛。

制作一张简洁的产品三视图，包含 3 个由白色间隙分隔的垂直面板：1) 正视图，2) 左侧侧视图，3) 右侧/后方四分之三侧视图。保持角色以相同的姿态直立，将角、多眼、小翅膀、多条手臂、分段式腹部、粗壮的腿、尾巴、爪子、凸起、鳞片以及怪兽玩具质感转化为精细的 3D 雕塑效果。

风格：{argument name="toy material" default="半透明祖母绿光泽乙烯基"}，摄影棚产品摄影，柔和均匀的灯光，细腻的阴影，中性浅灰色背景，高细节，趣味十足的日式 sofubi 怪兽美学。请勿包含文字、标志、手部、工具或草图线条。最终图像应呈现为物理原型的渲染照片，适用于 3D 建模或雕塑参考。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1233);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 收藏级玩具包装设计师', '创建一个风格化的收藏级玩具包装，主角为 {argument name="character name" default="[角色名称]"}。

包装颜色：{argument name="packaging color" default="[颜色]"}
顶部文字："{argument name="title" default="[标题]"}"
人偶风格：可爱的乙烯基设计师玩具，大头，简化比例。
姿势：[姿势]
表情：[表情]

配件：
• [物品 1]
• [物品 2]
• [物品 3]
• [物品 4]
• [物品 5]

服装：
[服装描述]

专业产品摄影，模塑塑料托盘，豪华收藏级包装，正面视图，对称布局，柔和阴影，哑光质感，超精细 3D 渲染。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1234);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 动漫角色薯片包装', '请使用输入图像作为 {argument name="character" default="角色"} 的参考。创建一个比例为 3:4 的照片级图像，展示一个放置在逼真木桌上的虚构品牌银色薯片袋。将输入图像中的角色转换为直接印在银色包装袋上的黑白手绘漫画风格插图。插图应占据包装袋下半部分空白区域的很大一部分。保留角色的面部、发型、服装、标志性装饰以及任何搭档角色。薯片必须来自虚构品牌；请勿使用真实公司名称、徽标或产品设计。根据输入图像中角色的主题、氛围、种族、服装和搭档元素来确定薯片的产品名称。产品名称应简短、易记，听起来像是在便利店中能看到的名字。尽可能使用类似“{argument name="product name" default="OO 薯片"}”、“OO Chips”或“OO Age”这样的短名称。薯片的口味名称也应根据角色的印象自然确定，从 {argument name="flavor" default="日式、盐味、海苔、黑胡椒、高汤或甜辣味"} 等适合日本零食的口味中进行选择。包装袋的上半部分应展示产品包装设计，包含醒目的产品名称、口味名称、宣传语、粗体黑白文字、手绘对话气泡以及俏皮的星星或涂鸦装饰。下半部分应展示黑白手绘角色插图。包装袋应看起来像带有金属银色薄膜、褶皱、反光、粗体印刷文字和限量版联名风格装饰的日本零食。背景和包装袋应保持写实，仅包装袋上的角色采用粗犷的钢笔画、漫画线条或手绘草图风格。整体氛围应可爱、俏皮，看起来像是一款自然的联名产品。请生成图像。', 'https://img.shields.io/badge/Language-JA-blue', '![](https://img.shields.io/badge/Language-JA-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1235);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 祖母绿戒指植物奢华微距摄影', '创作一张方形奢华微距产品摄影图，展示 {argument name="jewelry type" default="祖母绿单钻戒指"}，呈现出珍贵的植物炼金术质感。将一枚戒指置于画面中下部中心，水平放置在形成浅托的卷曲光泽绿叶上。戒指拥有抛光的黄金戒圈、四个圆润的金爪，以及一颗垂直椭圆切割的 {argument name="gemstone" default="深祖母绿宝石"}，切面清晰，内部闪烁光芒。周围环绕三片大型背景叶片或花瓣：一片从左前景向戒指延伸的弯曲绿叶，一片在右侧边缘升起的卷曲绿叶，以及背景上方一团模糊的勃艮第酒红色花瓣。下方表面为湿润的黑色火山石或漆面岩石，带有小水洼和镜面般的高光。在叶片和岩石上添加可见的水滴，包括右侧叶片附近几颗明亮的水珠和左侧叶片上的细小水点。光影应具有戏剧性和电影感：右上方的温暖金色轮廓光，宝石上的柔和正面反射，深邃的阴影，高对比度，浅景深，呈现奢华的编辑类珠宝广告风格。使用祖母绿、黄金、勃艮第酒红和亮黑色的深沉色调。相机角度为叶片水平面的特写，1:1 方形裁剪，戒指焦点清晰锐利，背景花瓣和前景边缘呈现奶油般的虚化效果。无文字，无手部，无包装，无额外珠宝，无标志，无水印。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1236);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 情侣锁屏 iPhone 平铺摄影', '创作一张超写实的奢华苹果风格平铺摄影照片，展示两部并排摆放在暖米色亚麻布上的 iPhone 15 Pro，背景为黄金时段的阳光，带有柔和的对角线窗影和逼真的手机倒影。左侧手机略微偏左，右侧手机略微偏右，均以竖屏方向放置，带有黑色圆角边框、钛金属边缘、灵动岛（Dynamic Island）切口、锁屏状态图标、底部的闪光灯和相机按钮，以及白色的主屏幕指示条。两部手机的锁屏均显示日期“6 月 20 日，星期日”和醒目的时间“05:30”；左侧运营商标签显示为 {argument name="left carrier label" default="Smart"}，右侧运营商标签显示为 {argument name="right carrier label" default="DITO"}。锁屏壁纸在两块独立的屏幕间形成无缝的情侣互动效果：左侧屏幕上，一位留着棕色长发的年轻女性穿着黑色 T 恤，上面印有醒目的白色文字 {argument name="left shirt text" default="I’M HIS"} 和一个红色爱心；她的手臂从左侧手机壁纸中水平延伸出来，并在视觉上延伸至右侧手机，俏皮地戳向或按压着年轻男性的脸颊。右侧屏幕上，一位留着凌乱深色头发的年轻男性穿着黑色连帽衫，上面印有醒目的白色文字 {argument name="right shirt text" default="I’M HERS"} 和一个红色爱心，对她的俏皮动作做出微妙反应。画面中仅包含两名人物、两部手机、两颗红色爱心图标，并确保姿势在屏幕间隙处完美对齐，使手臂看起来像是一张连续的图像。人物面部应保持匿名或柔和模糊处理，同时保留真实的肤色、发质、衣物纹理和光影效果。采用浅景深效果，呈现 8K 级超高清摄影细节，高端智能手机产品摄影风格，暖米色与黑色调配色，画面中不包含额外设备，除锁屏和 T 恤文字外无其他文字，无水印。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1237);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 电影级蒸饺摄影', '电影级美食摄影，展示了新鲜的 {argument name="food item" default="蒸饺 (momo)"} 堆叠在 {argument name="surface" default="质朴的旧木质项目"} 上。饺子皮光泽诱人，手工褶皱精致细腻，表面泛着淡淡的油光，浓郁的蒸汽升腾而起。分屏场景展示了解构视角：悬浮的饺子皮、香料肉馅球以及散落在空中的新鲜香草。

定格瞬间效果，空气中弥漫着面粉颗粒，香料处于动态静止状态，并伴有戏剧性的慢动作飞溅效果。袅袅升腾的蒸汽和飘落的香草叶增添了氛围感。

{argument name="setting" default="昏暗而富有质感的乡村厨房环境"}。质朴的木质切菜项目，纹理和裂痕清晰可见。

电影级影棚灯光，色调温暖诱人，高对比度和深邃的阴影营造出专业的杂志大片质感。微距摄影，8K 分辨率，超精细纹理，浅景深效果，背景虚化，食材焦点清晰锐利。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1238);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 职业清单平铺剪影', '一张 {argument name="profession" default="[PROFESSION]"} 装备的俯视平铺摄影图，Knolling 风格::5 排列：将实物工具、装备和配件精心排列在 {argument name="background" default="米色背景"} 上，完美构成 {argument name="shape" default="[SHAPE]"} 的实心剪影::5 清单：AI_INFER（高度逼真、触感真实的工具、织物以及 [PROFESSION] 日常生活中的特定物品），统一的色彩分级::4 排版：左下角带有标注职业的简洁优雅文字::3 灯光：摄影棚柔光箱，零透视畸变，8k 分辨率，商业产品摄影::3 杂乱、重叠的物体、3D 透视、房间背景、手::-3', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1239);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 乐高风格人偶收藏品', '一款高度精细的收藏级玩具人偶，灵感源自乐高风格人偶，置于专业摄影棚中。人偶拥有 {argument name="face features" default="写实年轻女性面孔，瓷器般细腻的皮肤，直顺的乌黑长发，齐刘海，以及一缕醒目的白色挑染"}。她佩戴着精致的银色耳环，表情沉稳自信。身体为光泽感塑料积木人偶，身着 {argument name="outfit" default="印有 10 号的足球球衣"}，搭配同款短裤及 {argument name="theme" default="国家队风格配色"}。全身构图，居中取景，浅景深效果，高级产品摄影，超洁净布光，反光塑料质感，逼真阴影，焦点清晰，奢华收藏品美学，高端商业广告风格，写实面部与玩具身体无缝融合，8K 分辨率，鲜艳色彩分级，与球衣配色相呼应的摄影棚背景。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1240);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 创作者桌上的定制手办', '创建一个逼真的方形商业产品摄影场景，展示一个 1/7 比例的 {argument name="character name" default="身穿黑色刺绣传统服饰的年轻女性"} 定制手办，陈列在明亮的收藏家工作室的白色电脑桌上。真人创作者站在桌子右侧，造型与手办完全一致：留着深棕色长发并编成粗侧辫，身穿黑色及踝长裙，配有透视袖子、金色刺绣饰边、黑色打底裤、黑色鞋子和垂坠耳环；她的面部经过柔和的隐私模糊处理。她一只手拿着细画笔，另一只手拿着小工具或触控笔，姿势仿佛正在修补手办。手办居中放置在圆形透明亚克力底座上，穿着同样的服装，留着同样的发型，面部经过柔和模糊处理，具有逼真的 PVC 收藏品质感、细腻的织物纹理和精致的金色饰边。桌子左侧是一个零售手办包装盒，正面带有大开窗，印有相同角色的全身艺术图，设计风格如同商业玩具包装，带有小型标志块和产品名称 {argument name="box product name" default="BASHEEQA DOLL"}。手办后方是一台桌面显示器，显示着数字角色艺术软件，上面有该女性的全身参考图。除包装盒、显示器、键盘和手办外，请包含 2 个桌面艺术品/办公用品：一个装满铅笔和画笔的网格笔筒，以及一个靠在显示器旁的带框插画。房间墙壁为白色，配有白色浮动搁板，整体呈现简洁的马卡龙色系收藏家美学。请清点并包含 18 个可见的搁板收藏品/艺术品：左上层搁板上有 2 个穿着粉色裙子的时尚人偶和 6 个小型 Q 版/动漫手办；右上墙面/搁板区域有 2 个带框动漫女孩画作和 3 个穿着马卡龙色裙子的小人偶；中右层搁板上有 2 个小型马卡龙色人偶；右下层搁板上有 2 个大头小人偶；最右下角有 1 幅带框公主风插画。使用柔和的日光、浅景深、逼真的相机视角、清晰的产品细节，背景玩具带有微妙的虚化效果，除玩具包装盒上的品牌名称外，不添加任何额外文字。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1241);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 基于参考图的服装迁移', '请将 {argument name="reference person" default="第一张"} 参考图像中的人物，换上 {argument name="clothing" default="第二张"} 图像中展示的服装。关于配饰的放置位置，请参考 {argument name="accessories" default="第三张"} 图像。', 'https://img.shields.io/badge/Language-JA-blue', '![](https://img.shields.io/badge/Language-JA-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1242);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 超写实商业汽水罐广告', '一张超写实的商业广告摄影作品，展示了一个巨大的 {argument name="beverage brand" default="Coca-Cola"} 汽水罐，放置在现代超市的货架区。一位穿着职业装的年轻 {argument name="person" default="businessman"} 从罐身正面浮现，仿佛与包装设计融为一体。该男子留着整洁的黑色短发，面带自信而温暖的微笑，身穿剪裁合身的炭灰色西装，搭配挺括的白色衬衫和 {argument name="tie color" default="deep red"} 领带。他双手捧着一座细节极其丰富的金色 FIFA 世界杯奖杯。巨大的 Coca-Cola 罐身上布满了逼真的冷凝水珠，印有鲜艳的红色品牌标识、优雅的金色丝带图案以及 2026 年 FIFA 世界杯徽标。背景货架上摆满了多个 Coca-Cola 罐，营造出空间深度和品牌重复的视觉效果。

使用全画幅专业相机拍摄，85mm 镜头，平视视角，浅景深，电影级超市灯光，主体与奖杯超清晰对焦，自然的皮肤纹理，金属表面逼真的反射效果，精准的阴影，光泽感铝罐材质，照片级水珠效果，高端广告构图，HDR，全局光照，光线追踪反射，体积光，背景虚化，极致细节，杂志级产品摄影，商业品牌美学，色彩鲜艳，高对比度，逼真的超市环境，完美的五官，超精细纹理，获奖广告大片风格。

8K UHD，超写实，照片级真实，杰作，超精细，极致清晰度，专业调色，影棚级灯光，清晰对焦，真实比例，电影级景深，奢华商业广告，竖构图（4:5 纵横比）。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1243);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - Midnight Aurora 奢华香水广告', '创建一个超高端奢华产品摄影场景，采用竖屏格式，以名为“{argument name="product name" default="MIDNIGHT AURORA"}”的虚构小众香水作为主角。

香水瓶身采用时尚的几何轮廓，由 {argument name="material" default="深蓝宝石色水晶玻璃"} 精制而成，配有拉丝铂金装饰和雕塑感金属瓶盖。将香水瓶放置在抛光的黑色黑曜石底座上，周围环绕着发光的水晶碎片和淡淡的薄雾。

环境营造出北极极光下神秘的 {argument name="environment" default="北极之夜"} 氛围。背景中，充满活力的极光波纹在场景中流转，伴随着柔和的绿色、蓝色和紫色光迹。漂浮的冰晶、闪烁的微粒和半透明的霜雪纹理营造出一种梦幻般的氛围。

灯光：背部戏剧性的电影级轮廓光，左侧冷蓝色主光，瓶身微妙的铂金反射，体积光束，奢华商业灯光设置，高端香水广告美学。

色调：午夜蓝、翡翠绿、冰青色、银色、紫色。

相机：全画幅专业相机，85mm 微距镜头，f/2.8 光圈，浅景深，超逼真的玻璃反射，高端产品摄影，极其锐利的瓶身细节，柔和细腻的焦外成像。

构图：简洁的居中构图，香水瓶占据视觉焦点，平衡的留白，奢华品牌美学，杂志封面级品质，照片级真实感，8K 分辨率，杰作，商业广告大片。

重要提示：请保留上传产品的确切形状和标签位置，并将其无缝融入奢华的北极极光环境中。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-gpt-image-2', '["gpt-image-2","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-gpt-image-2', 1, 1244);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
