INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('元旦特辑：2026 祝福四格拼图', '[关键：保持精确的面部特征，保留原始面部结构，图像中的人物必须与上传的参考图像完全一致] 高端照相馆 2x2 网格照片。左上角面板（海军蓝背景）：人物身穿海军蓝制服式连衣裙，饰有金色纽扣，复古卷发，戴蓝色贝雷帽和珍珠耳环。她双手举起一块巨大的拼图（左上角拼图，上面有数字“20”），将其移向画面中心。她的目光聚焦在中央拼图区域，表情严肃，略带微笑。背景是海军条纹、一个锚和文字“扬帆新年”。右上角面板（樱花粉背景）：同一位女士身穿粉色蕾丝连衣裙，戴珍珠项链，公主发型，戴粉色玫瑰发夹和水晶耳环。她双手举起右上角拼图（上面有数字“26”），将其移向中心，与左上角拼图连接。她的目光看向拼图接缝处，表情专注而期待，身体前倾。背景是粉色樱花、文字“美丽邂逅”、蝴蝶和花瓣。左下角面板（薄荷绿背景）：同一位女士身穿薄荷绿棉麻连衣裙，艺术风格，自然长发，戴绿色发带和木质耳环。她双手举起左下角拼图（上面有文字“元旦”），将其向上移动，与左上角拼图连接。她的目光看向拼图，表情严肃，嘴唇微抿。背景是绿色植物、文字“希望生长”、新芽和树叶。右下角面板（柠檬黄背景）：同一位女士身穿带有向日葵图案的黄色连衣裙，扎着黄色蝴蝶结的辫子。她将最后一块右下角拼图（上面有文字“快乐”）推入，完成拼图。四块拼图完美地在画面中心形成了完整的图案“2026 元旦快乐”。她向后仰头，看着完成的拼图，脸上洋溢着成功喜悦的笑容。画面中心爆发出金色光芒和五彩纸屑。背景是黄色太阳、文字“圆满成功”、笑脸和向日葵。拼图从四个角落汇聚到中心，形成一幅完整的画面。清晰的妆容，明亮的环形灯，85mm 镜头，f/1.8 光圈，四格构图，拼图互动，时尚杂志风格。', 'https://img.shields.io/badge/Language-ZH-blue', '![](https://img.shields.io/badge/Language-ZH-blue)

![](https://img.shields.io/badge/⭐-Featured-gold)', 'youmind-nano-banana-pro', '["nano-banana-pro"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1259);
