INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('个人资料 / 头像 - 电影感音乐制作人肖像', '一张中景特写电影感肖像，主体为 {argument name="subject" default="一位身体前倾、下巴抵在交叉双手上的男士"}，置于专业的 {argument name="musical instrument" default="电子音乐键盘"} 之上。他的手上戴着多枚银戒指。键盘按键在前景中清晰可见，纹理锐利。
