INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 芒果冰沙信息图与商业摄影', '- 一张高端饮品产品摄影图，主体为一杯 {argument name="fruit" default="mango"} 冰沙，放置在明亮的纯色热带黄色摄影棚背景中心，装在透明的高玻璃杯中。冰沙呈现出浓郁的奶油芒果质感，配有新鲜芒果片装饰、冷凝水珠和鲜艳的色彩。柔和的商业灯光营造出干净的反射效果，并在玻璃杯下方投下逼真的阴影。超清晰对焦，高端饮品广告风格，超写实，8K 分辨率。
长宽比：1:1

创作一张超写实的芒果冰沙爆炸式垂直信息图构图。
从上到下的结构：
奶油泡沫层（轻盈透气的奶油质感）
→ 芒果果泥层（浓郁鲜艳的芒果质感）
→ 新鲜芒果块（多汁的水果细节）
→ 冰块层（清晰逼真的冰块质感）
→ 玻璃杯底（极简透明玻璃）
完美对齐，热带黄色背景，柔和逼真的阴影，高端饮品信息图设计。
使用以下确切标签，添加带有细指示线的简洁信息图文字标签：
“Cream”（奶油）
“Mango Puree”（芒果果泥）
“Mango”（芒果）
“Ice”（冰块）
“Glass”（玻璃杯）
超写实饮品细节，高端商业摄影，8K 分辨率。
长宽比：1:1', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-nano-banana-pro', '["nano-banana-pro","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1301);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 男性年龄演变肖像', '创建一个超写实的年龄演变肖像序列，展示同一位男性在 {argument name="stages" default="4 个主要生命阶段：儿童（6 岁）、青年（25 岁）、中年（45 岁）和老年（75 岁以上）"} 的变化。使用附带的儿童面部照片作为最年轻阶段的精确身份参考，确保每个年龄阶段看起来都是同一个人随时间自然衰老的结果，并在所有年龄段中保持一致的面部结构、鼻型、眼睛颜色、下颌线、肤色、眉形、嘴唇和面部比例。将四张面孔以紧凑的重叠侧向堆叠构图排列，呈现出专业的摄影年龄演变阵列效果。每张面孔均应正面朝向、紧凑裁剪，并从前到后依次略微错位排列，形成从最年轻到最年长的平滑分层演变。保持所有阶段的面部比例基本一致，且透视畸变最小。面孔应自然重叠并紧密靠拢，间距简洁，类似于摄影棚肖像的堆叠构图。无几何面板，无电影场景构图，无过度的深度效果，无夸张的透视。纯白色无缝摄影棚背景，柔和的中性摄影棚灯光，真实的皮肤纹理，自然的衰老细节，简洁的中性服装，超写实，高细节，清晰对焦，专业肖像摄影，所有年龄段身份高度一致。无公司标识。宽高比 4:5，无文字，无 Logo。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-nano-banana-pro', '["nano-banana-pro","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1302);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图 / 教育视觉图 - 功能性外套设计规格表', '一份 {argument name="collection name" default="AMZ Collection"} 时尚设计规格表与产品布局，以长图信息图形式呈现，展示男士功能性外套。左侧为全身照，模特为 32 岁男性，留短须，剪渐变发型，身穿深橄榄绿与板岩灰配以亮橙色点缀的硬核多口袋机能夹克及配套工装裤。页面顶部醒目地展示了标题 "{argument name="title" default="AMZLECTION - URBAN FRONTIER SERIES"}" 和 "AERO SHELL PARKA SYSTEM"，采用粗体、简洁的无衬线字体，并附有其作为系统工程师和城市探险家的职业简介。右侧为技术性的 "关节与分层研究" 分解图，展示了多个背部和前部轮廓角度，详细说明了拉链系统、关节袖设计及兜帽收纳方式。中心部分提供宏观特写镜头，突出展示了科技感材质，包括防撕裂科技面料、密封拉链以及防滑衬里袖口。下方 "模块化造型" 一栏展示了该服装的多种穿搭方式，例如全防护系统或轻量化城市外壳。布局底部设有标注为 "模块化配件" 的网格区域，展示了多功能腰带、触屏兼容科技手套、EDC 多功能工具和头灯等配件。旁边是 "城市调色板与材质" 色卡条，显示了板岩灰、橄榄绿、夜空黑、烈焰橙和科技象牙白，随后是一个全面的 "技术规格" 模块，概述了该高性能装备的面料、保暖层、闭合方式、口袋及功能特性。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-nano-banana-pro', '["nano-banana-pro","信息图","教育视觉图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1303);
