INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('YouTube 缩略图 - 雄伟象群云朵摄影', '超写实摄影，巨大的体积云形成了雄伟的 {argument name="animal" default="大象"} 形状，云层结构细节丰富且解剖学准确，拥有巨大的象牙和高扬的象鼻，柔软而致密的积云具有逼真的深度和质感，戏剧性的黄金时刻光影，阳光穿透云层，微妙的阴影和高光增强了形态感。
前景：广阔的 {argument name="landscape" default="非洲稀树草原草甸"}，带有逼真的干草、大气透视和电影级的景深。多只 {argument name="wildlife" default="斑马"} 在田野中自然地吃草。空中：一群鸟在巨大的大象云周围盘旋，增加了比例感和动感。
环境：电影级天空，带有温暖的橙色和蓝色渐变色调，轻微的雾气，自然色彩分级，超写实光照，全局光照，体积雾，物理精确的阴影。
风格：DSLR 摄影，85mm 镜头，f/2.8 光圈，浅景深，HDR，8K 分辨率，锐利对焦，错综复杂的细节，照片级真实感，无 CGI 感。
氛围：雄伟、平静、超现实但可信，野生动物纪录片的真实感。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-nano-banana-pro', '["nano-banana-pro","youtube 缩略图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1305);
