INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('漫画 / 故事板 - 超现实木偶大师社论摄影', '{"vibe_title_en": "The Puppet Master Severing Her Own Strings", "master_prompt": "一张超写实主义的超现实社论摄影作品，捕捉“精心策划的威胁”。主角位于画面中心，采用 20 度眩晕式荷兰角（Dutch Angle）拍摄，地平线剧烈倾斜，营造出强烈的心理不稳定性。使用 Hasselblad H6D-100c 相机搭配 80mm f/2.8 镜头，采用 Kodak Portra 800 胶片以获得丰富、真实的颗粒感和模拟暖色调。主体的双臂具有超写实、抛光的红木球窝关节，与高度精细的人类皮肤（可见毛孔和细小绒毛）无缝融合。他们的双手举过头顶，握着一个沉重的、上过漆的木制木偶控制十字架。他们的姿态具有掠夺性且纹丝不动。主体留着长长的深红褐色波浪卷发，造型结构感强且富有光泽。社论妆容包括深色亮面深红色唇妆、锐利的图形眼线，以及每只眼睛下方各有一道醒目的金属金箔条，模拟凝固的结构化泪痕。他们穿着一件纹理厚重的深红色皮质紧身胸衣，在腰部无缝消融成浓厚的干冰烟雾。场景设定在一个古老、昏暗的玩偶制作工坊中，背景是手绘的深青色画布。灯光采用强烈的明暗对照法：一道严苛的定向琥珀色主光从左上方切入，投下深邃的阴影，而微妙的冷色补光确保了木质纹理的闪耀。对主体虹膜的锐利对焦揭示了强烈、针尖般的眼神光，放大了他们安静而受控的力量感。", "meta": {"intent": "超现实社论镜像与心理张力", "priorities": "高预算实拍特效真实感、触感十足的木材与皮革纹理、荷兰角构图、掠夺性的眼神接触、明暗对照法照明", "device_profile": "中画幅胶片模拟"}, "frame": {"aspect": "3:4", "composition": "中心构图，主体握住头顶元素，尽管轴线倾斜，仍占据画面的上方三分之一", "layout": "垂直人像，重点强调双手、木制十字架与强烈面部表情之间的相互作用", "camera_angle": "眩晕式荷兰角", "tilt_roll_degrees": "20 度"}, "subject": {"gender": "女性", "identity": "作为自我意识木偶的主角", "demographics": "年龄不详，神秘莫测", "face": "超精细皮肤纹理，带有天然毛孔，社论妆容，亮面深红色嘴唇，锐利的图形眼线，眼睛下方贴有金属金箔泪痕", "hair": "长长的深红褐色波浪卷发，造型结构感强且富有光泽", "body": "人类躯干，肘部和肩部被超写实的抛光红木球窝关节无缝替换", "expression": "精心策划的威胁，掠夺性，不眨眼，展现出安静而受控的力量", "pose": "双臂高举过头顶，握着木制木偶控制十字架，姿态紧绷，如同等待出击的掠食者"}, "wardrobe_accessories": {"garments": [{"item": "结构化紧身胸衣", "material": "厚实、陈旧的深红色皮革", "color": "深红色/牛血色", "fit": "紧身，贴合身形，在腰线处消融成浓烟"}], "accessories": [{"item": "木偶控制十字架与线", "color": "深色漆面，黄褐色线", "material": "抛光红木，厚蜡棉线", "brand_style": "古董手工风"}]}, "environment": {"setting": "一个废弃的古董玩偶制作工坊，被改造成临时摄影棚", "surfaces": "手绘深青色画布背景，地面被干冰烟雾遮蔽", "depth": "浅景深，背景淡入深邃、浓郁的青色阴影中", "atmosphere": "沉重、安静，充满漂浮的尘埃，带有迫在眉睫的危险感", "lens_interaction": "角落有轻微的光学暗角，捕捉烟雾的物理密度"}, "lighting": {"key": "来自左上方的严苛定向琥珀色聚光灯", "fill": "阴影中深邃、忧郁的青色环境补光", "rim": "勾勒木质关节和发丝边缘的锐利金色轮廓光", "shadows": "深邃、剧烈、高对比度的明暗对照法阴影", "color_temperature": "温暖的琥珀色与深邃的冷青色形成对比", "sensor_flare": "无，严格控制的摄影棚灯光"}, "camera": {"lens_type": "中画幅定焦", "focal_length": "80mm", "aperture": "f/2.8", "focus": "对虹膜和金箔泪痕进行锐利对焦", "sensor_format": "中画幅 (Hasselblad H6D-100c)", "perspective_distortion": "由于 20 度荷兰角导致的失真，产生坠落感"}, "post_processing": {"color": "丰富、饱和的电影级调色，强烈的互补琥珀色/青色推移", "tonality": "高对比度，压暗黑色，上漆木材上有发光的亮部", "texture": "真实的 Kodak Portra 800 胶片颗粒，皮革和皮肤上的触感微对比度", "digital_sharpening": "极小，依赖中画幅镜头的光学锐度", "chromatic_aberration": "仅在倾斜画面的极端边缘有细微的有机色差"}, "negative_specifications": ["无霓虹灯", "无短发", "无寸头", "无平光", "无数字绘画伪影", "无卡通比例", "无现代建筑元素", "无柔和、梦幻的表情"]}', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)', 'youmind-nano-banana-pro', '["nano-banana-pro","漫画","故事板"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1330);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('漫画 / 故事板 - 身着和服的动漫动作少女', '插画，主体为 {argument name="subject" default="少女"}，中长 {argument name="hair color" default="红色"} 发，红瞳，身着 {argument name="outfit" default="和服"}。线条流畅，色彩干净，采用赛璐珞风格阴影。高速剑术动作场景，正向观众挥剑。强烈的强制透视，武士刀在前景中显得格外巨大。挥砍动作进行中。强调躯干的扭转、重心的前移，头发和衣物因惯性而剧烈飘动，以传达速度感和动量。明亮的能量流从剑身涌出，划出一道巨大的弧线。角色、剑和发光的轨迹是主要视觉焦点。表情严肃，对比强烈，面容精致。3:4', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-nano-banana-pro', '["nano-banana-pro","漫画","故事板"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1331);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('漫画 / 故事板 - 女性白色礼服制服细节', '她身着一件 {argument name="uniform top" default="挺括的白色正式礼服上衣，配有蓝金镶边"}，领口为硬挺的海军蓝高领。肩章为指挥官级别。左胸前佩戴着两排密集的悬挂式全尺寸勋章，上方饰有一个 {argument name="badge" default="红色流星徽章，配有一对金色翅膀"}。领章和肩章上均有红色流星图案，肩章背景为黑色太空，流星正进入一颗蓝色行星的大气层。她的右肩上系有一根金红相间的编织肩带。她穿着一条 {argument name="skirt" default="长及小腿中部的海军蓝半身裙，侧面带有贯穿全长的白色条纹，并设有便于活动的开叉"}。白色及膝靴配以低跟抛光鞋跟，使整套制服更显完整。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-nano-banana-pro', '["nano-banana-pro","漫画","故事板"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1332);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('漫画 / 故事板 - 未来主义新插画海报', '超精细的新未来主义插画风格，融合了富有表现力的 {argument name="aesthetic" default="复古人物雕版美学"}。大胆的 {argument name="design" default="赛博朋克街头服饰"} 设计，采用锐利的矢量风格轮廓、简洁的几何线条以及高对比度的赛璐珞光影，并结合了有机的绘画感面部细节。浓郁的日本平面海报风格，配以超大字体排版、抽象的汉字元素、城市贴纸以及极简的工业背景构图。主色调为 {argument name="colors" default="深哑光黑、米白色、柔和棕褐色以及强烈的霓虹红点缀"}，营造出引人注目的编辑级对比效果。面部渲染运用了木刻版画灵感的切面、戏剧性的皱纹拓扑结构、棱角分明的解剖线条，以及流畅的手绘胡须/发丝，并带有细腻的墨迹纹理。服装和机械配件呈现出层次丰富的机能风细节，包括模块化面板、补丁、绑带、线缆以及未来主义工业设计语言。笔触在干脆利落的图形填充与带有手工瑕疵的纹理绘画阴影之间交替。整体美学融合了赛博朋克动画海报艺术、复古宣传图形、图像小说插画、浮世绘风格的线条简化，以及具有强烈视觉叙事能量的电影级概念肖像画。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-nano-banana-pro', '["nano-banana-pro","漫画","故事板"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1333);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('漫画 / 故事板 - 古埃及开罗上空的星际女神', '一个超现实、超写实的巨型奇幻场景，背景位于 {argument name="location" default="古埃及开罗"} 上空。一位美丽的年轻女性（使用上传的照片）化身为巨大的星际女神，轻柔地坐在城市上方的洁白云层中。她小心翼翼地将手指放在一座宏伟清真寺的尖塔顶端，仿佛在摆弄一件微缩的建筑杰作。在她下方，是一座广阔的历史悠久的伊斯兰城市，布满了宏伟的清真寺、圆顶、尖塔、庭院和细节丰富的砂岩建筑。远处，吉萨大金字塔从金色的沙漠中升起，映衬在 {argument name="sky color" default="明亮的蓝色"} 天空下。小鸟掠过地平线，为场景增添了生机与比例感。这位年轻女性表情平静而深思，面容优雅，长发飘逸，气质高贵。她巨大的身躯与下方的城市形成了强烈的对比，突显出一种神性而宁静的氛围。浓厚的云层在建筑之间和她身边穿梭，营造出梦幻般的天堂环境。温暖的阳光照亮了建筑，展现出复杂的雕刻、逼真的纹理和电影般的深度。超写实摄影，奇幻现实主义，巨型女性比例错觉，微缩城市效果，震撼的航拍视角，大气云层，体积光，高度精细的建筑，照片级皮肤纹理，清晰对焦，HDR，电影级构图，景深，杰作级品质，8K 分辨率，史诗级规模，超现实视觉叙事，专业数字艺术，宏伟而令人敬畏的氛围。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-nano-banana-pro', '["nano-banana-pro","漫画","故事板"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1334);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('漫画 / 故事板 - 情感动漫分镜页面', '故事

第 1 镜

细雨过后的温暖多云傍晚。

一个小区的公园在金色的夕阳下闪烁着光芒。

孩子们在欢笑嬉戏。

远处，长发女孩独自坐在秋千上。

她身旁空荡荡的秋千在风中缓缓摆动。

镜头备注：
广角定场镜头。

⸻

第 2 镜

特写。

女孩远远地看着其他孩子，安静地转动着手中的手工纸风车。

嘴角浮现出一抹淡淡的忧伤微笑。

镜头备注：
缓慢推镜头。

⸻

第 3 镜

一阵突如其来的风将纸风车从她手中卷走。

风车飞向公园另一侧。

女孩起身追赶。

镜头备注：
跟拍镜头。

⸻

第 4 镜

风车落在了一群玩耍的孩子附近。

女孩犹豫了一下，僵在原地。

她太害羞了，不敢靠近他们。

从她的视角看去，那群孩子显得既遥远又令人生畏。

镜头备注：
低角度情感 POV 镜头。

⸻

第 5 镜

其中一个孩子注意到了风车。

他们没有直接归还，而是细心地修补了破损的角落，并用彩色的图画和寄语进行了装饰。

女孩惊讶地看着这一幕。

镜头备注：
中景情感镜头。

⸻

第 6 镜

最友善的孩子带着温暖的笑容走向她，轻轻地将风车递还给她。

大家邀请她加入他们。

镜头备注：
柔和特写。

⸻

第 7 镜

女孩眼中泛起泪光。

她第一次露出了灿烂的笑容。

她紧紧握着修好的风车，向大家跑去。

镜头备注：
带有夕阳逆光的动态奔跑镜头。

⸻

第 8 镜

最终情感广角镜头。

女孩和她的新朋友们在绚烂的晚霞下欢笑。

背景中，那个曾经空荡的秋千在轻轻晃动。

修好的风车在温暖的晚风中旋转。

氛围：
苦乐参半，暖心，令人难忘。

镜头备注：
宏大的电影感结局画面。

最终目标

创建一个令人惊叹的高级动漫电影开发项目，讲述一个关于孤独、善良与寻找友谊的深刻感人故事。

画面应呈现出经典剧场版动漫工作室遗珠般的质感，拥有精美的背景绘图、富有表现力的人物表演、动人的视觉叙事，以及一个能留下持久情感冲击的感人结局。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)', 'youmind-nano-banana-pro', '["nano-banana-pro","漫画","故事板"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1335);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
