INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 电影感极光之心恋人摄影', '超写实电影感摄影。{argument name="subject" default="一对恋人"} 彼此伸手，一个由 {argument name="light effect" default="流动极光"} 形成的发光心形悬浮在他们双手之间。紫色、青色和翡翠色的光芒柔和地照亮了他们的脸庞。{argument name="time of day" default="暮色天空"}，背景中模糊的远方城市天际线，深情对视，梦幻氛围，自然的皮肤纹理，体积光，8K HDR，奢华时尚编辑风格。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

