INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 南亚女性与活力集市', '"subject": {"person": {"appearance": "{argument name="person appearance" default="年轻南亚女性，面带温暖笑容，面部轮廓与以往版本略有不同，发型为优雅的后盘发髻。"}","attire": "身穿深栗色（酒红色）长袖连衣裙，领口、袖口和下摆处绣有精致的金色传统图案。"},"animal": {"type": "{argument name="cat breed" default="毛茸茸的长毛白波斯猫"}","action": "被女子温柔地抱在怀中"}},"setting": {"location": "{argument name="market location" default="传统的中东或南亚户外集市（Bazaar），带有狭窄的石板路。"}","background_elements": ["头顶提供遮阳的织物天篷","摊位上摆满了色彩鲜艳的纺织品、地毯和挂毯","桌上陈列着碗装的各色香料以及传统的黄铜/铜制金属器皿","远处模糊的人影"],"lighting": "温暖的黄金时刻阳光透过集市顶棚滤入，营造出柔和的高光和丰富、诱人的氛围。"},"technical_specifications": {"style": "电影感肖像摄影","quality": "4k 分辨率，高度细腻的纹理","focus": "主体清晰对焦，浅景深，背景柔和虚化","composition": "全身照，展示主体坐在木凳上的姿态"}', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

