INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 赛博朋克都市时尚人像', '一位 {argument name="subject" default="留着齐肩棕色波浪卷发的自信年轻女性"}，身穿 {argument name="clothing" default="纯白色超大款 T 恤，佩戴小巧金质圆环耳饰"}，站在繁忙的城市街道中央，四周高楼林立，低角度人像，电影级构图。 {argument name="aesthetic style" default="充满活力的赛博朋克美学，带有霓虹洋红色、酸橙绿和青色的涂鸦风格手绘线条"} 勾勒出她的人物轮廓和服饰。抽象的全息铬合金漂浮物体、半透明几何形状、RGB 故障效果、色差、梦幻朦胧感、模拟胶片颗粒、漏光、鲜艳的色彩分级、超现实数字艺术与写实摄影的融合、编辑时尚大片、超精细、面部特征清晰、浅景深、高对比度、8K、高端杂志封面、未来感街头风格。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

