INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 地中海奢华时尚肖像', '创作一张超写实的奢华生活方式时尚肖像，采用 4:5 竖构图，灵感源自地中海编辑风格摄影的精致优雅与高端设计师眼镜广告。画面应体现“静奢风”、毫不费力的精致感与当代男性风格，捕捉国际奢华商业广告的氛围。模特为一名身材精瘦、健美的地中海裔欧洲男性，年龄在 {argument name="age range" default="26 到 34"} 岁之间，拥有棱角分明的椭圆形脸庞、轮廓鲜明的男性下颌线、突出的方形下巴，以及温暖的橄榄米色皮肤，呈现出带有自然毛孔的柔和哑光质感，并被温暖的地中海阳光照亮。他的表情冷静、深沉、内敛且充满自信，双唇微松，目光看向镜头之外。他的双眼隐藏在经典的矩形太阳镜后，镜框采用高级哑光黑色醋酸纤维材质，搭配偏光炭黑色镜片，并带有微妙的日光反射，使眼镜成为构图的核心元素。他的头发为中长款深巧克力棕色，带有自然的柔软波浪卷，头顶发量丰盈，呈现出略微被风吹乱的效果。修剪整齐的短胡茬增强了男性美感，同时保持了自然的编辑摄影质感。为他搭配一件 {argument name="clothing" default="剪裁合身的黑色细针织美利奴羊毛或高级棉质毛衣"}，采用高圆领设计，体现低调的奢华与永恒的欧洲男装风格。整体服装应传达出静奢风、高端休闲时尚以及老钱地中海生活方式，无需依赖正式的剪裁。模特姿势为四分之三侧身站立，头部转向肩后。肖像取景范围从头部到上半身，肩膀放松，肢体语言自然，传达出毫不费力的自信与永恒的精致感。采用紧凑的编辑构图，将主体略微置于画面右侧，通过干净的建筑墙面留出充足的负空间。视觉重心应自然地强调太阳镜、侧脸轮廓、发丝质感和黑色针织衫。场景拍摄于户外，背景为 {argument name="background" default="温暖的米色石灰岩或灰泥墙"}，带有微妙的抹灰纹理，营造出极简且无干扰的地中海建筑环境。通过简约的设计，使环境显得高级、精致且奢华。使用来自相机左侧的柔和午后地中海阳光进行照明，并辅以浅色石墙反射的自然补光。光影应产生雕塑般的面部阴影、皮肤上的温暖高光，以及具有中等对比度的自然商业质感。使用 105mm 肖像镜头，在 f/2.8 光圈下从视平线拍摄，以营造强烈的肖像压缩感、浅景深，并精准对焦于太阳镜、面部和发丝纹理，同时将背景柔化处理。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-nano-banana-pro', '["nano-banana-pro","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1350);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 工业风足球更衣室主题大片', '超写实运动时尚编辑大片，主角为 {argument name="subjects" default="一位年轻男性和一位年轻女性"}，身着 {argument name="clothing" default="正版葡萄牙国家队足球球衣"}，置身于 {argument name="setting" default="粗犷的工业风更衣室"} 中。男子自信地坐在前景冰冷的混凝土地面上，双手交握，身体微微前倾；女子则在背景中随意地靠在磨损的钢制更衣室长椅上。两人表情严肃而深邃，营造出一种强大的决心感与沉稳的自信。原始的混凝土墙面、斑驳的金属储物柜、散落的足球装备、磨损的球鞋、地面上细微的水渍以及电影质感的工业纹理，进一步增强了现场氛围。采用戏剧性的伦勃朗光影，伴有柔和的体积光束，深邃的阴影与冷灰色调形成了鲜明对比，衬托出葡萄牙球衣鲜艳的红色。奢华街头风格，现代足球文化美学，Vogue Sports 编辑风格，Nike 广告大片质感，高端时尚摄影，浅景深，面部细节锐利，自然皮肤纹理，逼真的布料褶皱，超精细刺绣，写实比例，细腻胶片颗粒，HDR，85mm 镜头，f/1.8，全画幅相机，高动态范围，丰富对比度，照片级真实感，超写实，杰作，8K，获奖商业摄影，电影级构图，杂志封面品质，无文字，无水印，除球衣队徽外无任何 Logo。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-nano-banana-pro', '["nano-banana-pro","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1351);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 专业健身房镜面自拍人像', '一张高质量、专业编辑风格的人像照片，主角是 {argument name="subject" default="一位年轻女性"}，正坐在 {argument name="setting" default="现代健身房"} 的瑜伽垫上。她穿着 {argument name="clothing" default="一件柔软的薄荷绿针织连帽衫和白色长裤"}。她正拿着智能手机进行镜面自拍。画面应呈现出干净、明亮且通透的氛围，采用电影级的 8K 光效，背景带有柔和的焦外成像效果。使用 85mm 镜头以获得更具美感的人像视角。确保构图平衡，在捕捉人物腰部以上画面的同时，保留健身房环境的宽敞视野。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-nano-banana-pro', '["nano-banana-pro","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1352);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 高端男装室内时尚图册', '一位三十多岁、充满自信的男性，身体呈 45 度角站立，重心平稳，双肩水平。他的发型两侧采用高渐变修剪，顶部留有 3 到 4 英寸的后梳蓬松发型，使用哑光造型产品，展现出自然的纹理和细微的碎发。他身穿一件 {argument name="clothing" default="深炭灰色纹理西装"}，内搭一件解开扣子的挺括白衬衫。他表情深沉从容，嘴部自然闭合，没有笑容，眉毛放松，双眼被 {argument name="accessory" default="圆形玳瑁太阳镜"} 遮住，视线投向左侧。他的左手佩戴着银色手表和金戒指，手指微曲，抓着西装的左翻领。他的右手佩戴着银色和黑色手链以及银戒指，轻轻搭在西装扣子附近的右侧边缘，形成了一种不对称的视觉层次，引导视线顺着敞开的领口向下移动至他的双手和珠宝。他站在一个中等空间深度的纯净奢华室内，脚下是 {argument name="setting" default="带有灰色纹理的纯白大理石地砖"}。左侧中景处，一座由同款灰纹白大理石建造的醒目楼梯配有玻璃扶手和优雅的黄铜装饰。他右后方悬挂着质感极佳的暖奶油色透光窗帘，柔和的垂直褶皱在哑光面料上形成了纵向的光影条纹。单一柔和的自然窗光从相机左侧 90 度射入，营造出一种温暖、精致且奢华的氛围。这种中等方向性的光线在他的面部和身体右侧投下柔和、渐变且短促的灰色阴影，而纯净的高光则照亮了他的左脸颊、挺括的白衬衫领口以及金属珠宝。环境补光平衡了中等对比度，突显出以西装的炭灰色、衬衫与楼梯的纯白色、暖奶油色窗帘以及自然肤色为主的暖色调。该作品采用高端男装杂志图册和奢华生活方式摄影风格，使用 85mm 镜头，光圈 f/2.8，快门 1/200s，ISO 100。这张写实的数字图像在主体上保持了极高的对焦清晰度，背景具有轻微的景深虚化，后期经过细腻的暖色调处理、精致的对比度增强，并对脸部和珠宝进行了局部锐化，以确保整体美感，并以 4:5 的比例完美构图。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-nano-banana-pro', '["nano-banana-pro","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1353);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 城市天台日落肖像', '参考照片中的人物坐在金属天台栏杆上，俯瞰城市景观，时间为 {argument name="time of day" default="日落"}，躯干略微向右倾斜，脊柱挺直但姿态放松。双手轻轻握住胸前的马克杯。双膝弯曲，左脚踩在较低的金属横杆上，右脚略微向前放置在同一横杆上，呈现出一种随意且平衡的坐姿。头部略微向左转，目光投向地平线，表情平静而沉思。佩戴着带有细金属框的深色墨镜，使整体造型更加完整。

他们身穿 {argument name="jacket" default="炭灰色休闲西装外套"}，内搭 {argument name="top" default="黑色圆领上衣"}，下身搭配修身黑色长裤。黑色低帮运动鞋配白色袜子，与城市天台的环境相得益彰。

环境是日落时分朦胧且色调温暖的城市天际线，背景中的高楼大厦在空气中逐渐模糊。下方的一条长街上布满了虚化的交通灯光，向地平线延伸。天空呈现出柔和的金色，将温暖的漫射光洒满整个场景。金属栏杆结构略显风化，为氛围增添了一丝工业气息。

全身肖像，竖构图，以平视视角拍摄，带有轻微的四分之三侧面透视。人物居中，城市景观在身后戏剧性地展开。景深控制使得主体清晰锐利，同时让城市灯光和天际线平滑地融入朦胧的远景中。

专业编辑摄影，照片级真实感。使用 Canon EOS 5D Mark IV 相机搭配 85mm f/1.8 镜头拍摄；光圈约为 f/2.0，以获得明显的背景虚化效果和强力的主体分离感。自然的物理景深，具有真实的模糊效果；主体焦点清晰。物理上合理的温暖日落光影，带有柔和的阴影和细腻的色调过渡。色彩真实，具有与城市日落相符的温暖朦胧色调。微妙的摄影师风格后期处理，真实的色彩分级，中等对比度。高分辨率，超细节，图像质量锐利（8k）。自然的哑光皮肤质感，可见毛孔，微妙的微观细节；无塑料感平滑处理。

负面提示词 (NEGATIVE PROMPT)：CGI，3D 渲染，虚假，人工，合成，塑料皮肤，蜡质皮肤，橡胶皮肤，喷枪皮肤，过度平滑，AI 伪影，数字伪影，JPEG 伪影，像素化，解剖结构扭曲，多余肢体，畸形，毁容，变异，浓妆，美颜滤镜，魅力修图，过度年轻/青少年外观，不自然的光泽，虚假光感，极端的电影级灯光，强烈的 HDR，运动模糊，失焦（除非有意为之），畸变，超出画面。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-nano-banana-pro', '["nano-banana-pro","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1354);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('产品营销 - 空灵动态模糊肖像', '一张柔焦、电影感的肖像，描绘了一位五官精致、拥有一头浅金色秀发的年轻女性，捕捉其动态瞬间。她的面部呈现出部分模糊和重影效果，飘逸的发丝在摇曳中被定格，营造出梦幻、空灵的动态感。她神情宁静，略显疏离，双唇微启，双眼轻柔地睁开。整个画面沐浴在金米色和深褐色调中，唤起一种怀旧的油画氛围。光线自然且柔和，来自附近的窗户，在她的皮肤上投下温暖的光泽，并照亮了在画面中舞动的发丝。使用 Canon EOS R5 搭配 85mm 镜头拍摄，光圈 f/1.2，ISO 320，快门速度 1/8 秒，通过刻意的慢速曝光和手持移动来创造艺术化的动态模糊。焦点柔和，浅景深将主体从苍白、奶油色的背景中分离出来。在 Adobe Lightroom 和 Photoshop 中进行后期处理：应用了电影级 LUT，通过分色调（阴影为柔和琥珀色，高光为奶油色）增强了温暖感，降低了清晰度，并使用置换图层和径向模糊滤镜优化了动态条纹。极其细腻的颗粒感增添了电影质感：情感丰富、朦胧、诗意。风格参考：美术肖像摄影、复古社论和模拟梦境序列。4K 超高清分辨率，无刺眼的对比度，保留了平滑的渐变。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)', 'youmind-nano-banana-pro', '["nano-banana-pro","产品营销"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1355);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 极简主义耳机电商产品图', '一张用于 {argument name="product" default="无线降噪耳机"} 的电商主图，采用 {argument name="style" default="极简风格"} 和 {argument name="background color" default="白色背景"}，通过添加卖点文案和图标来突出产品，适用于各类电商平台。', 'https://img.shields.io/badge/Language-ZH-blue', '![](https://img.shields.io/badge/Language-ZH-blue)

