INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 都市夏季街头时尚人像', '超写实的街头时尚人像，一位拥有 {argument name="hair color" default="长直铜红色头发"} 的年轻女性站在城市人行道上，背景是一间现代精品店的店面。她身穿 {argument name="summer outfit" default="一顶黑色棒球帽，一件修身白色罗纹背心，内搭一件淡薄荷绿与奶油色条纹吊带衫，下身穿着柔和淡色调的宽松条纹夏季短裤"}。双手拿着一副蓝色墨镜，并携带一个 {argument name="bag description" default="奶油色与森林绿配色的设计师款行李袋"}。自然妆容，肤色透亮，淡粉色嘴唇，表情从容自信。现代生活方式美学，休闲夏季时尚，Clean Fit 风格，高端街头服饰 Lookbook。她身后是一家时尚设计商店，拥有大面积玻璃窗、温暖的室内灯光、极简主义家居装饰陈列、服装架以及现代零售建筑风格。柔和的自然日光，玻璃上真实的倒影，地道的都市氛围，照片级的皮肤质感，编辑级时尚摄影，高端生活方式广告大片，高细节，奢侈购物区美学，8K 画质。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-nano-banana-pro', '["nano-banana-pro","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1364);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 奢华金茶杯与山间溪流', '为 {argument name="brand" default="Nano Banana Pro"} 打造的超高端电影级广告。一只奢华的金茶杯优雅地放置在纯净山间溪流的流动水龙头下。清澈见底的溪水以慢动作注入杯中，激起迷人的水花和闪烁的水滴。{argument name="logo" default="Nano Banana Pro logo"} 精致地镌刻在杯身上，散发着温暖的金色光芒。周围环绕着圆润的河石、郁郁葱葱的绿植和晨间的薄雾。戏剧性的电影级布光、体积光束、超写实水流物理效果、微距细节、奢华商业广告风格、浅景深、8K HDR、照片级真实纹理、高端品牌营销、慢动作水花特效、抛光金属上的倒影、获奖级广告摄影、电影级调色、大师级品质、超精细细节。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-nano-banana-pro', '["nano-banana-pro","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1365);
