INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 微距奢华饼干牛奶飞溅', '超写实 {argument name="product name" default="[BISCUIT NAME]"} 饼干在半空中动态堆叠，微微破碎以展现丰富质地，奶油夹心 / 黄油层清晰可见，戏剧性的牛奶飞溅在饼干周围形成艺术曲线，细小的饼干碎屑悬浮在空中，光泽的牛奶液滴定格在运动瞬间，{argument name="background" default="深色摄影棚渐变背景"}，电影级专业灯光，微距食品摄影，超清晰对焦，高对比度，高端奢华商业广告风格，戏剧性飞溅效果，超精细纹理，照片级真实感，8K 超高分辨率
