INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('电商主图 - 可食用产品转换', '上传产品的超写实可食用版本，保留精确的原始形状、比例和轮廓，产品完整且未切割，表面转换为柔软的哑光慕斯质感，具有自然的类海绵可食用细节，无光泽或反光表面，带有细腻的丝绒喷砂涂层，正视图，平视相机角度，相机直接放置在产品前方，居中对称构图
来自附近窗户的自然柔和日光，逼真的柔和阴影，放置在木质或米色大理石桌面上，柔和的中性亚麻布背景，明亮的自然光，不过曝，浅景深，微距镜头摄影，高级且自然的甜点造型，手持一把简单的勺子靠近表面但未切割，超写实，8k 高细节，最终图像比例为 3:4。将上传的产品转换为超写实的蛋糕，保留精确的形状和正视图。柔软的哑光慕斯质感，无光泽。自然日光环境。勺子轻轻切开一个边缘，表面柔和地破裂，内部露出分层的海绵蛋糕和奶油。缓慢平滑的动作，微距镜头，超写实。', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)', 'youmind-nano-banana-pro', '["nano-banana-pro","电商主图"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1375);
