INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('游戏素材 - 蒸汽朋克风浅粉色肖像', '一张细节极其精致的蒸汽朋克肖像，主角为 {argument name="subject" default="年轻女性"}，采用半身像构图，居中呈现。她拥有白皙如瓷的皮肤，带有淡淡的雀斑，明亮的蓝绿色双眸，妆容自然柔和。她的头发是蓬松的 {argument name="hair color" default="浅粉色"} 盘发，随意地梳成一个精致凌乱的发髻，几缕发丝散落在脸庞周围，营造出一种既细腻又叛逆的视觉效果。她佩戴着一件复杂的黄铜与青铜机械头饰，融合了工业工程学与维多利亚美学。头饰上装饰着抛光的齿轮、铆钉、微型透镜、压力阀、铜管、金属尖刺，额头上方设有一个大型圆形发光光学装置，散发出冷青色的光芒。较小的发光透镜和精密制作的机械组件增加了复杂感与真实感。脸颊上装饰着一个带有精细花丝的金属心形饰品。她穿着一件质感丰富的酒红色皮夹克，配有夸张的立领、明显的缝线、金属铆钉、搭扣、皮带，肩部附有层叠的蒸汽朋克机械装置。黄铜机构、关节、电缆和雕刻金属板与服装完美融合。灯光具有电影感和氛围感，结合了冷青色的环境光与温暖的铜色高光，突显了纹理、深度和反射表面。背景经过柔焦处理，暗示了先进的复古未来主义飞艇或工业实验室的内部，带有圆形金属结构和模糊的机械轮廓。超写实渲染，非凡的工艺，面部焦点极其锐利，浅景深，高度精细的皮肤纹理，优质材料，体积光，空气中漂浮的微小颗粒，大师级品质，戏剧性氛围，奢华蒸汽朋克时尚，照片级真实感，8K，HDR，完美的构图', 'https://img.shields.io/badge/Language-EN-blue', '![](https://img.shields.io/badge/Language-EN-blue)

![](https://img.shields.io/badge/🚀-Raycast_Friendly-purple)', 'youmind-nano-banana-pro', '["nano-banana-pro","游戏素材"]'::jsonb, 'https://github.com/YouMind-OpenLab/awesome-nano-banana-pro-prompts', 1, 1378);
