INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('插画/艺术', 'An anime-style illustration of a {argument name="action type" default="high-impact martial arts battle"} between two young female fighters in a {argument name="setting" default="traditional wooden martial arts dojo"}. In the foreground, a girl with black hair in a high bun wears a {argument name="character 1 color theme" default="red and white"} Chinese-style martial arts outfit with baggy pants. She is in a dynamic, low, forward-thrusting stance, surrounded by swirling red energy and water splashes. In the background to the right, a girl with light purple hair in twin buns wears a {argument name="character 2 color theme" default="green and purple"} Chinese dress with gold embroidery and black tights. She is leaping through the air in a flying kick pose, surrounded by swirling blue energy. The wooden floorboards are splintering from the intense impact, with debris and dust flying through the air. Above them hangs a weathered wooden sign with the text "{argument name="sign text" default="武術会"}". The scene features dramatic lighting, a low-angle dynamic perspective, and intense action effects.', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/120.jpg', '插画艺术风格创作

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/120.jpg)', 'davidwu-gpt-image2-prompts', '["插画","艺术","illustration","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1502);
