INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图设计', 'A candid, realistic photograph of a young {argument name="subject aesthetic" default="goth"} woman with pale skin, long straight black hair with bangs, heavy black eyeliner, and black lipstick. She has a {argument name="expression" default="deadpan"} expression, looking directly at the camera while sitting on a children''s coin-operated {argument name="ride type" default="unicorn"} ride. She is wearing a black lace-trimmed tank top, black arm warmers, layered necklaces including a choker, black lace tights, and chunky black platform boots with buckles. A large black shoulder bag hangs from her arm. The ride is a white unicorn with a pink mane, gold horn, and purple hooves, mounted on a purple base with a small sticker reading "{argument name="ride cost" default="50¢ PER RIDE"}". The setting is outside a store with a tan cinderblock wall. To the left is a glass door reflecting a person, a brown trash can, and a white sign with red text reading "{argument name="sign text" default="NO PARKING FIRE LANE"}". To the right is a blue vending machine. Overcast, natural daylight.', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/150.jpg', '写实摄影风格创作

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/150.jpg)', 'davidwu-gpt-image2-prompts', '["信息图设计","infographic","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1532);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('UI与界面', '{ "type": "mobile social media app UI mockup", "platform": "Twitter/X dark mode", "header": { "status_bar": "time 19:28, bird icon, signal, wifi, battery", "navigation": "back arrow, ''Tweet'' title" }, "post": { "author": { "avatar": "portrait of a Chinese emperor in red robes and black hat", "display_name": "{argument name=\"display name\" default=\"Emperor Zhu Yuanzhang\"} 👑 [verified badge]", "handle": "{argument name=\"handle\" default=\"@Emperor_Ming\"}" }, "content": { "text": "{argument name=\"tweet text\" default=\"I have ascended to the Dragon Throne! Today, I am proclaimed as the Emperor of the Ming Dynasty. The era of Hongwu has begun. Let us rebuild our great nation together!\"}", "hashtags": "#MingDynasty #HongwuEra #NewBeginning", "media_grid": { "count": 3, "images": [ "emperor seated on an ornate golden throne in red and gold robes", "wide shot of a grand Chinese palace courtyard with a large crowd", "emperor on horseback leading an army with a red dragon banner" ] } }, "metadata": { "timestamp": "{argument name=\"timestamp\" default=\"1:36 PM · Jan 23, 1368\"}", "engagement": "5,432 Retweets, 8,765 Quotes, 20.1K Likes, 102.3K Views" }, "actions": "reply, retweet, like (red heart with ''1''), share, upload" }, "footer": { "reply_bar": { "avatar": "woman in red", "placeholder": "Reply to Emperor Zhu Yuanzhang..." }, "navigation_bar": "home, search, notifications (red ''1'' badge), messages" } }', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/151.jpg', '界面交互设计图

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/151.jpg)', 'davidwu-gpt-image2-prompts', '["ui与界面","ui","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1533);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('UI与界面', 'Flat illustration, high-end oriental fantasy style city poster design, vertical 9:16 composition. The layout uses a diagonal + S-shaped flow extending from the bottom left to top right. The background is deep black grading down to intense dark red, creating strong warm-cool contrast and spatial depth with faint stardust and grain texture. In the center, a flowing golden energy line winds through like a flame, extending upward from the base, featuring fluid texture, particle effects, and gradient highlights, with subtle energy debris and volumetric light. Within the golden flow, the architectural landmarks of {argument name="city" default="Guangzhou"} emerge layer by layer: the Canton Tower is the visual core with prominent proportions, surrounded by the Zhujiang New Town skyline, Liede Bridge, and modern Lingnan architectural elements. Buildings are rendered using "fine line drawing + golden luminous blocks," with clear outlines and rich details, appearing to float in a void against the golden halo, creating a surreal spatial hierarchy with slightly fogged backgrounds for added depth. At the bottom of the frame is an oriental white-haired female figure with flowing hair like mist, naturally connecting and merging with the golden light. Her hair is translucent with gradient light effects; she has a graceful posture, eyes closed, and a serene expression, holding a bouquet of colorful flowers dotted with shimmering particles, symbolizing the spiritual connection between people and city energy. Character details are moderately simplified to emphasize the overall design. Lighting is concentrated on the golden flow, buildings, and character outlines, creating intense chiaroscuro and visual focus. The overall atmosphere is grand, mysterious, imbued with oriental mythology, and slightly healing. Colors use black and dark red as a base with brilliant gold as the main visual emphasis. The gold has rich light-dark layers, complemented by small areas of high-saturation floral colors, maintaining a sophisticated and restrained aesthetic. Integrated text and layout: Centered Songti font at the top reads "{argument name="city" default="Guangzhou"} · China," followed by smaller text "{argument name="date" default="2026/04/20"}" and "{argument name="author" default="LIYUE"}" below. Text uses pale gold or soft warm white, unified with the overall lighting. High-quality details, cinematic lighting, rich volumetric and particle details, clean image without noise, ultra-high 8K resolution, commercial-grade poster quality.', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/152.jpg', '主题海报版式设计

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/152.jpg)', 'davidwu-gpt-image2-prompts', '["ui与界面","ui","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1534);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('UI与界面', '{ "type": "cinematic promotional poster", "style": "3D CGI animation style, highly detailed, dramatic lighting, caricature characters", "characters": [ { "id": "char1", "description": "large shirtless man with long black hair, beard, and glasses" }, { "id": "char2", "description": "elderly woman in a kimono with white hair tied up" }, { "id": "char3", "description": "small man with a topknot, glasses, mustache, wearing a bright green sweater" } ], "layout": { "panels": [ { "position": "top", "scene": "wide shot of a town street with buildings and a city skyline in the background", "characters_present": ["char1", "char2", "char3"], "text_overlays": [ "{argument name=\"intro text\" default=\"ある日ーー\"}", "いつもの日常がーー", "こんばんは" ] }, { "position": "middle left", "scene": "close-up of char1 looking shocked against a dark fiery background", "text_overlays": [ "{argument name=\"shocked text\" default=\"私が出禁？\"}" ] }, { "position": "middle right", "scene": "close-up of char2 looking angry and pointing against a stormy sea background", "text_overlays": [ "{argument name=\"angry text\" default=\"海を荒らすな！\"}" ] }, { "position": "bottom", "scene": "char3 pointing, char1 screaming, a second instance of char3 falling backwards, and char2 sitting angrily against a fiery chaotic background", "text_overlays": [ "全然出ない！" ], "bottom_titles": [ "{argument name=\"main title\" default=\"パチンコ軍団親のイメチェン\"}", "{argument name=\"subtitle\" default=\"LINEスタンプ販売中\"}" ] } ] } }', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/153.jpg', '主题海报版式设计

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/153.jpg)', 'davidwu-gpt-image2-prompts', '["ui与界面","ui","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1535);
