INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('UI与界面', 'A highly detailed anime illustration of a fierce female warrior with long flowing {argument name="hair color" default="black"} hair and piercing {argument name="eye color" default="blue"} eyes, wearing a mix of silver plate armor with gold trim and a {argument name="outfit color" default="blue and white"} tunic. She is captured in a dynamic combat stance, swinging a massive, {argument name="weapon type" default="segmented metallic whip-sword"} that curves dramatically into the extreme foreground. The weapon leaves a sweeping trail of kinetic energy and wind. The scene is set against a {argument name="background setting" default="ruined battlefield with rocky terrain, floating debris, and large blue banners fluttering in the wind"} under a dramatic cloudy sky. The artwork features cinematic lighting, intense action, and a dramatic forced perspective on the weapon.', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/195.jpg', '动漫插画创作图

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/195.jpg)', 'davidwu-gpt-image2-prompts', '["ui与界面","ui","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1577);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('UI与界面', '{ "type": "4-panel vertical comic strip", "style": "{argument name=\"art style\" default=\"black and white pencil sketch, crosshatch shading, satirical caricature comic\"}", "characters": { "subject_1": "{argument name=\"main character\" default=\"Sam Altman\"}, curly hair, casual sweater", "subject_2": "{argument name=\"interviewer\" default=\"Ronan Farrow\"}, suit, tie, holding notepad" }, "layout": { "panels": [ { "panel_number": 1, "top_caption": "SAM ALTMAN THINKS THIS WILL BE A NICE LITTLE PROFILE...", "scene": "subject_1 looking smug with hands steepled; subject_2 looking serious taking notes.", "thought_bubble": "I''LL BE CHARMING. IT''LL BE A GREAT CHARACTER PIECE. PEOPLE WILL LOVE IT.", "center_text": "THE RONAN FARROW INTERVIEW", "inset_portraits": { "count": 2, "labels": ["HARVEY WEINSTEIN EXPOSED", "LESLIE MOONVES EXPOSED"] }, "info_boxes": { "count": 3, "text": [ "RONAN FARROW: PULITZER PRIZE-WINNING REPORTER WHO EXPOSED HARVEY WEINSTEIN AT THE NEW YORKER", "AND LESLIE MOONVES AT CBS.", "POWER. ABUSE. ACCOUNTABILITY." ] } }, { "panel_number": 2, "top_caption": "CUT TO...", "scene": "Close-up of subject_1 looking shocked and horrified.", "article_header": "{argument name=\"publication\" default=\"THE NEW YORKER\"}\nTHE SAM ALTMAN PROFILE\nTHE OPENAI CEO''S COMPLICATED QUEST\nBy Ronan Farrow" }, { "panel_number": 3, "top_caption": "SOON AFTER THE ARTICLE IS PUBLISHED...", "scene": "subject_1 looking extremely stressed, sweating, holding a phone to his ear. Surrounded by 6 hands holding smartphones.", "phone_labels": ["VC", "REPORTER", "EX-STAFFEE", "INVESTOR", "TECH CEO", "FORMER COLLEAGUE"], "shouts": { "count": 8, "text": [ "{argument name=\"main accusation\" default=\"LIAR\"}!", "COMPULSIVE LIAR!", "PATHOLOGICAL LIAR!", "YOU CAN''T STOP LYING!", "LIAR!!!", "SOCIOPATH! (ALLEGEDLY)", "EVERYTHING HE SAYS IS A LIE!", "MANIPULATIVE LIAR!" ] }, "sound_effects": "RING! RING! RING!" }, { "panel_number": 4, "top_caption": "AND THE REPORT CONCLUDES...", "scene": "subject_1 looking utterly defeated and depressed.", "quote_box": "\"ALTMAN FREQUENTLY AND CONSISTENTLY LIES TO INVESTORS, EMPLOYEES, THE BOARD, AND EVEN CLOSE FRIENDS.\"\n\"HE APPEARS TO HAVE NO COMFORT TELLING FALSEHOODS.\"\n\"HE IS, BY MANY ACCOUNTS, A COMPULSIVE LIAR AND A SOCIOPATH.\"\n(ALLEGEDLY)", "thought_bubble": { "scene": "Happy subject_1 holding a ''WORLD''S BEST CEO'' mug.", "text": "I THOUGHT IT WOULD BE A NICE LITTLE PROFILE...", "sparkle_words": { "count": 4, "text": ["GENIUS!", "VISIONARY!", "INSPIRING!", "BRILLIANT LEADER!"] } }, "bottom_caption": "INSTEAD, IT''S THE PROFILE THAT EXPOSES HIM." } ] } }', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/196.jpg', '插画艺术创作图

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/196.jpg)', 'davidwu-gpt-image2-prompts', '["ui与界面","ui","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1578);
