VALUES ('UI与界面', '{ "type": "anime character reference sheet", "character": { "name": "{argument name=\"character name\" default=\"真田大助\"}", "appearance": "young warrior with long brown hair, wearing samurai-inspired armor, {argument name=\"main color\" default=\"red\"} chest plate and guards, {argument name=\"secondary color\" default=\"navy blue\"} pleated hakama, white short cape" }, "layout": { "header": { "title": "{argument name=\"character name\" default=\"真田大助\"}", "subtitle": "{argument name=\"character concept\" default=\"戦国時代を舞台にした物語の主人公。日英クォーターの若き武将。\"}", "badge": "設定資料" }, "right_side": { "main_portrait": "large full-body standing pose, confident smile", "background_elements": { "emblem": "six-coin crest", "quote": "{argument name=\"catchphrase\" default=\"この国を守る。その誇りと共に。\"}", "scenery": "monochrome Japanese castle with army banners at the bottom right" } }, "sections": [ { "title": "プロフィール", "position": "top-left", "content": "table with 6 rows and descriptive text" }, { "title": "三面図", "position": "mid-left", "count": 3, "labels": ["正面", "側面", "背面"] }, { "title": "表情差分", "position": "top-center", "count": 6, "labels": ["通常", "微笑み", "真剣", "怒り", "驚き", "考え中"] }, { "title": "衣装・装備詳細", "position": "bottom-left", "count": 9, "labels": ["胸当て", "肩当て", "腕甲(籠手)", "脚甲(脛当て・膝当て)", "革靴", "白マント(短)", "帯", "袴/着物部分", "打刀"] }, { "title": "カラーパレット", "position": "bottom-center", "count": 8, "labels": ["真田赤", "濃紺", "金", "白", "茶", "茶褐色", "肌色", "銀"] }, { "title": "世界観", "position": "bottom-center-right", "content": "paragraph of text describing the setting" } ] } }', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/205.jpg', '插画艺术创作图

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/205.jpg)', 'davidwu-gpt-image2-prompts', '["ui与界面","ui","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1587);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('海报设计', 'An anime-style key visual poster for a fictional slice-of-life anime. In the foreground left, an energetic blonde anime girl with star hairpins and blue eyes wears an {argument name="main character outfit" default="American flag t-shirt and denim shorts"}, holding tongs with a slice of smoked meat towards the viewer. In the foreground right, a gentle girl with long dark hair and a white sweater sits at a wooden table writing in a notebook. In the background, two more girls are present: one with a brown ponytail carrying firewood, and another with short silver hair holding a blue mug. The scene is a sunny outdoor BBQ area with a large black smoker grill featuring a sign that reads {argument name="background grill sign" default="LONE STAR BBQ"}. In the immediate foreground is a {argument name="food platter" default="massive wooden platter loaded with sliced brisket, ribs, sausages, burnt ends, and pickles"}, along with side dishes like coleslaw and bread. In the top left corner, a large, cute, bubbly anime logo reads {argument name="anime title" default="もくもく すもーく ガールズ"} with smoke and grill motifs. In the bottom left corner, there is a {argument name="credits text block" default="staff credits block with names and roles"}. In the bottom right corner, a small text box lists four character names. The overall atmosphere is cheerful, highly detailed, and vibrant.', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/206.jpg', '主题海报版式设计

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/206.jpg)', 'davidwu-gpt-image2-prompts', '["海报设计","poster","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1588);
