VALUES ('UI与界面', '{ "type": "anime production layout sheet", "style": "traditional colored pencil genga, key animation drawing", "subject": { "character": "{argument name=\"character name\" default=\"ナズナ 七草\"}", "appearance": "anime girl with {argument name=\"hair color\" default=\"light purple\"} hair styled in twin braids and bangs, blue eyes, wearing a dark oversized coat", "pose_and_expression": "{argument name=\"expression\" default=\"smug with a small fang, resting chin on hand\"}" }, "background": "{argument name=\"background scene\" default=\"nighttime city skyline with a railing\"}, soft focus", "layout": { "top_edge": "standard animation paper peg holes", "left_margin": { "series_title": "{argument name=\"anime title\" default=\"よふかしのうた\"}", "production_codes": ["#05 C.", "[A] (1)"], "circled_note": "髪のハイライト 色トレスです" }, "right_margin": { "red_box": "002.normal", "timing_layers": ["A (1)", "B (1) (2) (3)", "C (1) (2) END"], "background_notes": ["BL 夜景", "BG 市街地夜景 色トレス"] } } }', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/207.jpg', '电商商品展示设计

