INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('UI与界面', 'An anime-style light novel cover illustration featuring two characters in an intimate pose. On the left, a young woman with short dark hair, purple eyes, wearing a white hat, a frilly white dress with a pink bow tie, white gloves, and two white flower hairpins. She has an affectionate, teasing smile and is gently touching the chin of the man next to her. On the right, an adult man with {argument name="man''s hair color" default="red"} hair parted in the middle, purple eyes, and a light goatee. He is wearing a black button-down shirt and has a slightly annoyed, reluctant expression with a sweat drop on his cheek. The scene features soft, romantic lighting with out-of-focus purple flower petals in the foreground corners. The image includes several Japanese text elements: a large stylized main title at the bottom reading {argument name="main title" default="ちかつば"}, a subtitle below it reading {argument name="subtitle" default="ーその溺愛、独占欲の裏返し。ー"}, vertical text on the top left reading {argument name="left quote" default="可愛いだけじゃ、許さない。"}, and vertical text on the top right reading {argument name="right quote" default="その不機嫌、俺だけに向けろよ。"}.', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/208.jpg', '插画艺术风格创作

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/208.jpg)', 'davidwu-gpt-image2-prompts', '["ui与界面","ui","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1590);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('UI与界面', '{ "type": "manga page", "style": "anime illustration, full color", "characters": { "woman": { "appearance": "long {argument name=\"hair color\" default=\"black\"} hair, purple eyes", "outfit": "{argument name=\"shirt color\" default=\"grey\"} long-sleeve shirt, dark grey skinny jeans, barefoot" }, "delivery_man": { "appearance": "bald, older man, thick eyebrows", "outfit": "blue work jacket over a grey shirt" } }, "layout": { "description": "Page split vertically. Left side contains 4 stacked horizontal panels. Right side is a single tall vertical panel.", "left_column_panels": [ { "panel_number": 1, "scene": "Woman sitting on a grey sofa in a living room, holding a white mug.", "text_elements": [ { "type": "speech_bubble", "text": "?" }, { "type": "sound_effect", "text": "ピンポーン♪", "description": "doorbell ringing" } ] }, { "panel_number": 2, "scene": "Woman opening the front door. Delivery man standing outside holding a cardboard box, smiling.", "text_elements": [ { "type": "speech_bubble", "speaker": "delivery_man", "text": "{argument name=\"delivery greeting\" default=\"こんにちは〜！宅配便で〜す！\"}" }, { "type": "speech_bubble", "speaker": "woman", "text": "は、はい…ありがとうございます" } ] }, { "panel_number": 3, "scene": "Close-up of the delivery man laughing enthusiastically with a sparkly pink background.", "text_elements": [ { "type": "speech_bubble", "speaker": "delivery_man", "text": "{argument name=\"creepy compliment\" default=\"おや〜？いや〜美人さんですなあ！こんな綺麗な方がお一人でお住まいなんて、もったいないなあ〜♪\"}" } ] }, { "panel_number": 4, "scene": "Close-up of the woman looking disgusted and uncomfortable, sweating slightly. The back of the delivery man''s head is visible in the foreground.", "text_elements": [ { "type": "speech_bubble", "speaker": "delivery_man", "text": "それにしてもお肌が綺麗！スタイルも抜群だし〜モデルさんみたいですよ！" }, { "type": "thought_bubble", "speaker": "woman", "text": "{argument name=\"woman reaction\" default=\"え…？何この人…ちょっと気持ち悪いかも…\"}" }, { "type": "caption_box", "text": "この後も延々と褒め続ける配達員だった…" } ] } ], "right_column_panel": { "panel_number": 5, "scene": "Full-body portrait of the woman standing indoors, looking annoyed and suspicious with her arms crossed.", "text_elements": [ { "type": "thought_bubble", "speaker": "woman", "text": "誰かしら…？" } ] } } }', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/209.jpg', '建筑空间场景图

