INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('UI与界面', '{ "type": "fashion product catalog layout", "theme": "A cohesive fashion collection featuring a specific pattern: {argument name=\"pattern description\" default=\"overlapping circular floral mandala motifs in purple, green, blue, orange, and pink\"}", "layout": { "structure": "2x2 grid with a full-width bottom banner", "sections": [ { "id": "01", "title": "{argument name=\"product 1\" default=\"Flared Dress\"}", "subtitle": "フレアワンピース", "main_image": "Woman in patterned flared dress holding white handbag.", "swatch_count": 3, "swatch_descriptions": ["purple variant", "green/blue variant", "orange/yellow variant"], "description_text": "華やかなフレアシルエット。軽やかな素材が優雅な動きを演出します。" }, { "id": "02", "title": "{argument name=\"product 2\" default=\"Silk Scarf\"}", "subtitle": "シルクスカーフ", "main_image": "Woman in white blouse with patterned silk scarf.", "swatch_count": 2, "swatch_descriptions": ["flat pattern detail", "tied knot detail"], "description_text": "首元に彩りを添えるシルクスカーフ。上品な光沢と滑らかな肌ざわり。" }, { "id": "03", "title": "{argument name=\"product 3\" default=\"Tote Bag\"}", "subtitle": "トートバッグ", "main_image": "Woman carrying patterned tote bag.", "swatch_count": 3, "swatch_descriptions": ["purple variant", "blue variant", "orange/yellow variant"], "description_text": "A4サイズも入る収納力。軽くて丈夫、毎日使いたくなるトートバッグ。" }, { "id": "04", "title": "{argument name=\"product 4\" default=\"Pouch\"}", "subtitle": "ポーチ", "main_image": "Patterned zip pouch on table with magazine and vase.", "swatch_count": 3, "swatch_descriptions": ["green/purple variant", "orange variant", "pink variant"], "description_text": "バッグの中を彩る華やかなポーチ。細部まで美しいデザインが魅力です。" } ], "bottom_banner": { "title": "Pattern Design", "description_text": "細やかな線と豊かな色彩が織りなす、唯一無二のパターンデザイン。日常に優雅な彩りを。", "image": "Horizontal strip showing the seamless pattern." } } }', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/220.jpg', '封面排版设计图

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/220.jpg)', 'davidwu-gpt-image2-prompts', '["ui与界面","ui","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1602);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图设计', '{ "type": "Japanese promotional landing page poster", "style": "hyper-energetic, explosive typography, vibrant colors, amusement park night festival aesthetic", "layout": { "top_section": { "background": "night sky, fireworks, ferris wheel, roller coaster", "subjects": "4 young adults cheering, raising fists, dynamic lighting", "typography": [ "{argument name=\"main headline\" default=\"究極の楽しい!!\"}", "{argument name=\"sub headline\" default=\"やばい!!共感してもらいたい!!\"}", "この一枚が、あなたの人生を最高に塗り替える!!" ], "badges": [ "累計販売枚数 {argument name=\"sales badge\" default=\"252,000\"} 枚突破!!!" ] }, "middle_section": { "title": "究極の楽しい体験を実現する5つの超快楽ポイント", "points_count": 5, "points": [ {"number": 1, "label": "爆笑覚醒", "image": "people laughing"}, {"number": 2, "label": "ドキドキMAX", "image": "roller coaster loop"}, {"number": 3, "label": "感動の渦", "image": "fireworks explosion"}, {"number": 4, "label": "超解放ゾーン", "image": "silhouettes jumping at sunset"}, {"number": 5, "label": "無限リピート", "image": "group of people cheering"} ] }, "bonus_section": { "title": "今だけ！超豪華 5大特典付き!!!", "items_count": 5, "items": [ "① 限定デザインポスター", "② 楽しい名言ブックレット(PDF)", "③ 超楽しいプレイリスト(MP3)", "④ スマホ壁紙セット", "⑤ 楽しいシークレット映像" ] }, "bottom_section": { "product_info": { "name": "究極の楽しいポスター", "variants_count": 3, "variants": ["全力全開ver.", "笑顔爆発ver.", "感動絶頂ver."] }, "pricing": { "label": "魂の価格", "amount": "{argument name=\"price\" default=\"¥2,980\"}", "shipping": "送料無料" } }, "footer": { "text": "{argument name=\"footer call to action\" default=\"人生を最高に楽しみ尽くせ!! さぁ、今すぐ手に入れろ!!\"}", "background_color": "magenta" } } }', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/221.jpg', '主题海报版式设计

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/221.jpg)', 'davidwu-gpt-image2-prompts', '["信息图设计","infographic","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1603);
