INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图设计', '{ "type": "promotional banner design set", "theme": "strawberry advertisement campaign", "style": "anime illustration, bright, cheerful, commercial graphic design", "color_palette": "{argument name=\"primary color theme\" default=\"pastel pink and vibrant red\"}", "character": "{argument name=\"character description\" default=\"anime girl with brown side ponytail and bunny ears, wearing a pastel blue and pink jacket\"}", "product": "{argument name=\"product\" default=\"fresh red strawberries\"}", "layout": { "sections": [ { "type": "large landscape banner", "position": "top left", "visuals": "character winking and holding a strawberry next to a large basket of strawberries", "main_text": "{argument name=\"main headline\" default=\"いちごたっぷり\"}", "sub_text": ["笑顔あふれる、甘〜いひととき♪", "とびきりおいしい！", "ひと粒で、しあわせ広がる♡", "あまっ♡", "旬のおいしさをお届け！"], "badges": { "count": 3, "labels": ["あま〜くてジューシー！", "いろんなサイズを楽しめる♪", "新鮮朝採れ！"] } }, { "type": "vertical banner", "position": "right", "visuals": "character eating a strawberry with a pile of strawberries below", "main_text": "いちごたっぷり", "sub_text": ["旬のいちごをお届け！", "{argument name=\"secondary headline\" default=\"あま〜くて、ジューシー！\"}", "とろけるおいしさ〜♡"], "badges": { "count": 3, "labels": ["朝採れ新鮮！", "いろんなサイズを楽しめる♪", "甘くてジューシー！"] } }, { "type": "wide horizontal banner", "position": "middle", "visuals": "character with closed eyes eating a strawberry, flanked by strawberries", "main_text": "いちごたっぷり！", "sub_text": ["あまくて、ジューシーな幸せ♡", "旬の美味しさをお届けします！", "おいし〜っ♡"] }, { "type": "small square banner", "position": "bottom left", "visuals": "character smiling holding strawberry", "text": ["いちごたっぷり", "あま〜くてジューシー！"] }, { "type": "small square banner", "position": "bottom mid-left", "visuals": "pile of strawberries with one cut in half", "text": ["旬のいちご！", "あまくてとろけるおいしさ♡"] }, { "type": "small horizontal banner", "position": "bottom mid-right", "visuals": "character holding strawberry", "text": ["いちごたっぷり", "朝採れ新鮮！", "あまくてジューシー！"] }, { "type": "circular icons", "position": "bottom right", "count": 4, "items": [ { "visual": "basket of strawberries", "label": "朝採れ新鮮！" }, { "visual": "half strawberry", "label": "あまくてジューシー！" }, { "visual": "whole strawberry", "label": "いろんなサイズ！" }, { "visual": "character face", "label": "とろけるおいしさ♡" } ] } ] } }', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/223.jpg', '电商商品展示设计

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/223.jpg)', 'davidwu-gpt-image2-prompts', '["信息图设计","infographic","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1605);
