![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/227.jpg)', 'davidwu-gpt-image2-prompts', '["产品展示图","product","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1609);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('UI与界面', '{ "type": "mobile livestream e-commerce interface mockup", "subject": { "person": "Elon Musk", "clothing": "black t-shirt with SPACEX logo", "pose": "gesturing towards camera with both hands, explaining enthusiastically", "watermark": "@Proof AI" }, "background": { "setting": "large display screen", "image": "Mars landscape with Starship rocket and dome habitats", "text": [ "SPACEX", "{argument name=\"background title\" default=\"移民火星计划\"}" ] }, "ui_layout": { "header": { "broadcaster_info": { "name": "{argument name=\"broadcaster name\" default=\"ElonMusk\"}", "stats": "75.8万本场点赞", "follow_button": "关注" }, "viewer_stats": { "avatars_count": 3, "text": "10万+", "close_button": "X" }, "tags": [ "带货总榜第1名", "更多直播 >" ] }, "product_card": { "position": "mid-right", "status": "讲解中", "image": "Mars dome habitats", "title": "{argument name=\"product title\" default=\"火星移民基础套餐\"}", "price": "{argument name=\"product price\" default=\"¥99.00\"}", "action_button": "抢" }, "chat_overlay": { "position": "bottom-left", "join_alert": "星辰大海 加入了直播间", "messages_count": 7, "messages": [ "{argument name=\"top chat message\" default=\"梦想家: 支持马斯克！！🚀\"}", "火星弟弟: 多少钱一位？", "科技迷: 太酷了！想去火星！", "未来已来: 如何报名？", "小火箭: 🌹🌹🌹", "宇宙无敌: 讲解一下细节", "东方不败: 老马牛逼！👍👍👍" ] }, "bottom_action_bar": { "input_placeholder": "说点什么...", "icons_count": 4, "icons": ["shopping cart", "gift box", "heart planet", "plus sign"] }, "floating_reactions": { "position": "bottom-right", "elements": "stack of floating hearts, thumbs up, and laughing emojis" } } }', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/228.jpg', '直播界面设计图

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/228.jpg)', 'davidwu-gpt-image2-prompts', '["ui与界面","ui","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1610);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('信息图设计', 'A bright, summery commercial product photography shot featuring a refreshing beverage on a weathered wooden table. In the sharp foreground, there is 1 tall glass filled with a golden, bubbly iced drink garnished with 1 lemon slice and a sprig of rosemary, sitting next to 1 silver aluminum can covered in cold condensation. The can prominently displays the English text {argument name="product name" default="TOKYO HIGHBALL"} below a small gold star logo, featuring a graphic of the drink itself and the Japanese text "アルコール分 7%" near the bottom. To the right of the can, 2 cut lemon wedges rest on the table. In the softly blurred background, a sunny beach scene unfolds with sparkling turquoise water and a clear blue sky. Standing to the left in the background is 1 young woman with long brown hair, wearing a white sleeveless top and a light blue skirt, looking out toward the ocean. Floating elegantly in the sky above the scene is the Japanese text {argument name="catchphrase" default="夏、これがいい。"}. The overall lighting is radiant and inviting, with sparkling bokeh and lens flares emphasizing the crisp, cold, and refreshing atmosphere of a perfect summer day.', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/229.jpg', '品牌徽标设计图

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/229.jpg)', 'davidwu-gpt-image2-prompts', '["信息图设计","infographic","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1611);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('UI与界面', '{ "type": "2x2 advertising banner grid", "layout": "4 distinct quadrants, each featuring a different industry advertisement", "quadrants": [ { "position": "top-left", "industry": "skincare", "visuals": "Asian woman touching cheek, floating water droplets, white pump bottle", "brand": "BALANCÉE", "copy": { "headline": "{argument name=\"skincare headline\" default=\"素肌が、目覚める。\"}", "subheadline": "透明感あふれる、新しいわたしへ。", "features_count": 3, "features_labels": ["高保湿", "肌荒れ予防", "美白ケア*"] } }, { "position": "top-right", "industry": "restaurant food", "visuals": "close-up of spaghetti bolognese with grated cheese and parsley, dark moody lighting", "brand": "Trattoria Luce", "copy": { "headline": "{argument name=\"food headline\" default=\"このパスタ、事件級。\"}", "badge": "期間限定", "description": "黒毛和牛のボロネーゼ 〜トリュフの香り〜" } }, { "position": "bottom-left", "industry": "travel", "visuals": "woman with backpack facing a scenic mountain lake, bright daylight", "brand": "NATURE JOURNEY", "copy": { "headline": "{argument name=\"travel headline\" default=\"わたしを、解き放つ旅へ。\"}", "subheadline": "自然の中で、心が動き出す。", "script": "Find your freedom.", "banner_details": ["初夏の特別キャンペーン", "6.1 SAT - 6.30 SUN", "最大 20%OFF", "今だけの特別プラン多数！"] } }, { "position": "bottom-right", "industry": "SaaS app", "visuals": "smartphone displaying a task management app interface with 4 schedule items", "brand": "{argument name=\"app brand name\" default=\"Taskme\"}", "copy": { "headline": "{argument name=\"app headline\" default=\"タスク管理を、もっとシンプルに、スマートに。\"}", "circle_badge": "1日を、デザインしよう。", "features_count": 3, "features_labels": ["直感的な操作性", "チームで共有可能", "どこでもアクセス"], "bottom_banner": "7日間無料トライアル実施中！" } } ] }', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/230.jpg', '界面交互设计图

