INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('UI与界面', '[中文] 为中国古代诗人设计一套游戏卡片，并按照SSR SR R 分级，重点卡片有放大展示的效果，包括卡面设计和人物介绍，有很高级的游戏卡片质感，稀有卡片还会有特色的光影例如镭射效果 需要有套卡设计和技能设计，并附带较为详细的说明 [English] Design a set of game cards for ancient Chinese poets, classified by SSR SR R grades, with key cards having an enlarged display effect, including card face design and character introduction, having a very high-end game card texture, rare cards will also have special light and shadow effects such as holographic laser effects, requiring set card design and skill design, along with relatively detailed descriptions', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/367.jpg', '古风诗人镭射典藏卡牌

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/367.jpg)', 'davidwu-gpt-image2-prompts', '["ui与界面","ui","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1749);
