INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('UI与界面', '[中文] { "master_prompt_type": "超精细8K AI图像生成", "global_settings": { "resolution": "8K UHD", "aspect_ratio": "2:3 竖版", "render_quality": "极致锐度、超微细节、电影级光效", "style": "超现实商业产品摄影", "color_profile": "温暖金调搭配柔和琥珀高光", "environment": { "location": "古老中东市场走廊", "architecture": { "walls": "岁月痕迹的粗糙石墙与可见纹理", "arches": "背景巨型石拱", "floor": "暖棕色石材地面" }, "background_elements": [ "装满香料的木架", "袋装与碗装干货", "悬挂草药束", "散发暖黄光的传统金属灯笼" ], "lighting": { "primary": "柔和金色环境光", "secondary": "两侧暖灯笼辉光", "atmosphere": "薄雾增强光线漫射" } }, "main_subject": { "type": "香水瓶", "position": "中心前景", "placement": "置于华丽木桌之上", "material": { "bottle": "透明清玻璃", "cap": "黄金金属矩形瓶盖", "liquid": "淡金香水液体" }, "design": { "shape": "圆角矩形瓶身", "finish": "高光反射表面", "label": "无可见标签" }, "table": { "material": "深色雕花木材", "shape": "方形台面", "details": [ "繁复花卉与几何雕刻", "金色镶嵌装饰", "抛光表面映光" ] }, "floating_elements": { "composition_style": "竖向成分堆叠", "motion": "成分悬浮并伴随旋转金光", "effects": [ "发光粒子", "闪耀尘埃", "柔光尾迹连接元素" ], "elements_order_top_to_bottom": [ { "ingredient": "琥珀树脂", "appearance": "半透明金棕树脂块", "glow": "温暖内发光" }, { "ingredient": "大马士革玫瑰", "appearance": "盛放粉色玫瑰", "details": [ "柔软层叠花瓣", "自然绿叶", "轻飘附近花瓣" ] }, { "ingredient": "白麝香", "appearance": "光滑白水晶状石块", "additional": "石下细白粉末" }, { "ingredient": "陈年沉香", "appearance": "深棕木片", "texture": "粗糙纤维木纹", "effect": "缕缕白烟上升" } ] }, "text_elements": { "title": { "text": "精致叙利亚香水", "font_style": "优雅衬线体", "color": "金色", "position": "顶部中央" }, "subtitle": { "text": "奢华叙利亚香水", "font_style": "较小衬线体", "color": "金色", "position": "主标题下方" }, "ingredient_labels": [ { "title": "纯琥珀", "description": "来自自然深处的珍贵树脂" }, { "title": "大马士革玫瑰", "description": "美丽与叙利亚传承的象征" }, { "title": "白麝香", "description": "干净、粉感、永恒优雅的香氛" }, { "title": "陈年沉香", "description": "深邃温暖、浓郁烟熏木香" } ], "typography_details": { "connector_lines": "细弯金线连接文字与成分", "icons": "线末端小圆点标记" }, "opacity": "轻微半透明" } }, "overall_mood": { "tone": "奢华、温暖、优雅", "theme": "传承香水工艺", "visual_feel": "浓郁、高端、电影级广告" } } } [English] { "master_prompt_type": "Ultra-detailed 8K AI image generation", "global_settings": { "resolution": "8K UHD", "aspect_ratio": "2:3 vertical", "render_quality": "extreme sharpness, ultra-fine detail, cinematic lighting", "style": "hyper-realistic commercial product photography", "color_profile": "warm golden tones with soft amber highlights", "environment": { "location": "ancient Middle Eastern market corridor", "architecture": { "walls": "aged stone walls with visible texture and wear", "arches": "large stone archway in background", "floor": "stone flooring, warm brown tone" }, "background_elements": [ "wooden shelves filled with spices", "sacks and bowls of dried goods", "hanging bundles of herbs", "traditional metal lanterns emitting warm yellow light" ], "lighting": { "primary": "soft golden ambient light", "secondary": "warm lantern glow from both sides", "atmosphere": "slight haze enhancing light diffusion" "main_subject": { "type": "perfume bottle", "position": "center foreground", "placement": "on top of an ornate wooden table", "material": { "bottle": "transparent clear glass", "cap": "gold metallic rectangular cap", "liquid": "light golden perfume liquid" }, "design": { "shape": "rectangular bottle with rounded edges", "finish": "glossy reflective surface", "label": "no visible label" "table": { "material": "dark carved wood", "shape": "square top", "details": [ "intricate floral and geometric carvings", "golden inlay accents", "polished surface reflecting light" "floating_elements": { "composition_style": "vertical ingredient stack", "motion": "ingredients appear suspended with swirling golden light", "effects": [ "glowing particles", "sparkling dust", "soft light trails connecting elements" ], "elements_order_top_to_bottom": [ { "ingredient": "amber resin", "appearance": "translucent golden-brown resin chunks", "glow": "warm internal glow" "ingredient": "damask rose", "appearance": "fully bloomed pink rose", "details": [ "soft layered petals", "natural green leaves", "petals gently floating nearby" ] "ingredient": "white musk", "appearance": "smooth white crystal-like stone", "additional": "fine white powder beneath the stone" "ingredient": "aged agarwood", "appearance": "dark brown wooden pieces", "texture": "rough, fibrous wood grain", "effect": "thin white smoke rising upward" "text_elements": { "title": { "text": "Exquisite Syrian Perfume", "font_style": "elegant serif", "color": "gold", "position": "top center" }, "subtitle": { "text": "Luxury Syrian Perfume", "font_style": "smaller serif", "color": "gold", "position": "below main title" }, "ingredient_labels": [ { "title": "Pure Amber", "description": "Precious resin from the depths of nature" } "title": "Damask Rose", "description": "Symbol of beauty and Syrian heritage" }, { "title": "White Musk", "description": "Clean, powdery scent of timeless elegance" }, { "title": "Aged Agarwood", "description": "Rich, smoky wood with deep warmth" } ], "typography_details": { "connector_lines": "thin curved golden lines connecting text to ingredients", "icons": "small circular markers at line endpoints" } "opacity": "slightly translucent" } "overall_mood": "tone": "luxurious, warm, elegant", "theme": "heritage perfume craftsmanship", "visual_feel": "rich, premium, cinematic ads', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/404.jpg', '沉香玫瑰悬浮幻景

