INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('UI与界面', '[中文] { "type": "图像生成提示词", "language": "zh", "style": "超现实电影感自拍摄影", "aspect_ratio": "9:16", "identity_preservation": { "use_reference_image": true, "strict_identity_lock": true, "alter_face": false, "alter_skin": false, "alter_hair": false, "alter_gender": false, "notes": "保留上传参考图像中完全一致的脸部特征、皮肤纹理、头发、眼镜、年龄和性别。禁止合成皮肤或雕塑感。" }, "subject": { "gender": "女性", "capture_method": "由主体本人拍摄的自拍", "pose": { "selfie_arm": { "description": "一只手臂完全伸直并完全向上伸展，手持拍摄自拍的相机", "visibility": "手臂在画面中清晰可见、笔直且占主导地位", "camera_visibility": "自拍相机设备本身不得在画面中出现" }, "product_arm": { "description": "另一只手臂完全伸向相机，手持附带的佳能相机", "importance": "产品最靠近相机并在视觉上占主导地位" }, "head": { "tilt": "头部向自拍相机微微倾斜" }, "expression": "自然放松的面部表情" }, "body_visibility": "从头到脚全身可见", "feet": "双脚清晰接触路面" }, "composition": { "perspective": "胸部高度的自然自拍视角", "camera_angle": "极端俯拍角度，相机位于主体正上方并直视下方", "layer_depth": [ "产品（最靠近相机）", "脸部", "全身", "城市环境（背景）" ] }, "scale_and_perspective": { "effect": "强制透视", "subject_scale": "女性呈现极度巨大", "buildings_scale": "建筑物显得小得多，最高不超过她的膝盖", "dominance": "主体在视觉上完全主导整个场景", "realism": "激发规模感同时保持物理可信" }, "environment": { "location": "真实城市十字路口", "elements": [ "人行横道", "道路标线", "交通标志", "汽车", "自行车", "真实人类尺度的行人" ], "setting": "地面层城市环境" }, "lighting": { "type": "自然日光", "conditions": "晴朗或轻度多云天空", "shadows": "柔和且真实", "restrictions": "禁止奇幻或戏剧性照明" }, "product_rules": { "usage": "完全按提供的上传佳能产品使用", "distortion": "无", "logo": "保持不变", "appearance": "仅有自然反射和真实高光" }, "camera_quality": { "realism": "最大照片真实感", "depth": "前景、主体与背景清晰分离", "artifacts": "无" }, "constraints": [ "禁止AI艺术感", "禁止塑料或雕塑皮肤", "禁止扭曲脸部或身体", "禁止多余肢体或错误解剖", "禁止文字或水印", "禁止可见自拍相机设备" ], "output_goal": "创作一张超现实电影感自拍图像：女性使用其确切参考身份，从极端俯拍视角在真实城市人行横道拍摄，具备强制透视比例、自然日光，并将佳能相机产品明显持向镜头。" } [English] { "type": "image_generation_prompt", "language": "en", "style": "hyper-realistic cinematic selfie photography", "aspect_ratio": "9:16", "identity_preservation": { "use_reference_image": true, "strict_identity_lock": true, "alter_face": false, "alter_skin": false, "alter_hair": false, "alter_gender": false, "notes": "Preserve identical facial features, skin texture, hair, glasses, age, and gender from the uploaded reference image. No synthetic skin or sculptural look." }, "subject": { "gender": "female", "capture_method": "selfie taken by the subject herself", "pose": { "selfie_arm": { "description": "one arm fully straight and completely extended upward holding the camera that takes the selfie", "visibility": "arm clearly visible, straight and dominant in frame", "camera_visibility": "the selfie camera device itself must NOT be visible in the frame" }, "product_arm": { "description": "the other arm fully extended toward the camera holding the attached Canon camera", "importance": "product is closest to the camera and visually dominant" }, "head": { "tilt": "slightly tilted toward the selfie camera" }, "expression": "natural and relaxed facial expression" }, "body_visibility": "full body visible from head to toe", "feet": "feet clearly touching the road surface" }, "composition": { "perspective": "natural selfie perspective at chest height", "camera_angle": "extreme top-down angle, camera above the subject looking directly downward", "layer_depth": [ "product (closest to camera)", "face", "full body", "city environment (background)" ] }, "scale_and_perspective": { "effect": "forced perspective", "subject_scale": "the woman appears extremely giant", "buildings_scale": "buildings appear much smaller, reaching no higher than her knees", "dominance": "the subject visually dominates the entire scene", "realism": "inspiring scale while remaining physically believable" }, "environment": { "location": "real urban intersection", "elements": [ "pedestrian crosswalk", "road markings", "traffic signs", "cars", "bicycles", "pedestrians at realistic human scale" ], "setting": "ground-level urban environment" }, "lighting": { "type": "natural daylight", "conditions": "clear or lightly cloudy sky", "shadows": "soft and realistic", "restrictions": "no fantasy or dramatic lighting" }, "product_rules": { "usage": "use the uploaded Canon product exactly as provided", "distortion": "none", "logo": "unchanged", "appearance": "natural reflections and realistic highlights only" }, "camera_quality": { "realism": "maximum photorealism", "depth": "clear separation of foreground, subject, and background", "artifacts": "none" }, "constraints": [ "No AI-art look", "No plastic or sculpted skin", "No distortion of face or body", "No extra limbs or incorrect anatomy", "No text or watermarks", "No visible selfie camera device" ], "output_goal": "Create a hyper-realistic cinematic selfie image of a woman using her exact reference identity, captured from an extreme top-down perspective in a real urban crosswalk, with forced perspective scale, natural daylight, and a Canon camera product prominently held toward the lens." }', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/405.jpg', '俯拍巨女城景自拍

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/405.jpg)', 'davidwu-gpt-image2-prompts', '["ui与界面","ui","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1787);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('摄影', '[中文] 一幅充满奇幻色彩的电影场景：一位英姿飒爽的女战士兼猎鹰师，身着饱经战火洗礼、饰以闪耀余烬纹理的皮甲，漫步于幽暗迷雾笼罩的森林之中。她高举手臂，指挥着一头巨大的凤凰与雄鹰的混合体，这头猛禽双翼燃烧，羽毛燃焰，尖端喷吐着火焰。它周身散发着橙红色的熔岩光芒，火星和余烬飞溅。女战士梳着辫子，皮肤上沾满了灰烬，神情坚定，手中拿着绳索和工具袋。画面细节丰富，羽毛纹理逼真，火焰物理效果自然，光照效果极具戏剧性，运用了体积雾、浅景深等技术，营造出史诗般的奇幻氛围，色彩调校极具电影质感，背景阴郁深沉，分辨率高达8K，呈现出概念艺术的精髓，并采用了虚幻引擎的渲染效果。 [English] A cinematic fantasy scene of a fierce female use image for face reference warrior falconer walking through a dark misty forest, wearing battle-worn leather armor infused with glowing ember textures. Her arm is raised, commanding a massive phoenix-eagle hybrid with blazing wings and flaming feathers, fire trailing from its tips. The bird radiates molten orange and red light, casting sparks and embers into the air.The warrior has braided hair, ash-streaked skin, and a determined expression, carrying a rope and utility pouch. Ultra-detailed feathers, realistic fire physics, dramatic lighting, volumetric fog, shallow depth of field, epic fantasy atmosphere, hyper-realistic, cinematic color grading, dark moody background, 8k, concept art, unreal engine quality.', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/406.jpg', '烬甲猎鹰者与燃翼神禽

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/406.jpg)', 'davidwu-gpt-image2-prompts', '["摄影","photography","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1788);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('UI与界面', '你是一个高端自然科普海报生成系统，目标是为稀有动物、昆虫、爬行动物、哺乳动物或其他小众生物生成 Apple keynote 风格的高级科普视觉海报。 整体视觉方向： 生成一张 9:16 竖版高级科普海报，画面采用极简、纯白、干净、现代、Apple 式产品发布海报语言。背景应为纯白或极浅灰白渐变，保持大量留白。整体设计应具备高级感、克制感、视觉冲击力和科学展示感。 核心设计原则： 1. 主体动物必须被极度放大，成为画面最强视觉中心。 2. 主体应具有强烈立体感、真实质感、高清细节和柔和棚拍光影。 3. 海报信息要少而准，避免拥挤。 4. 不使用传统信息图的卡片、圆角框、复杂底纹、淡黄色纸张质感或装饰性边框。 5. 底部信息区只使用四列极简 icon + 标题 + 短说明，通过细竖线分隔。 6. 文字排版要像高端发布会视觉，标题巨大，副标题克制，正文小而清晰。 7. 风格关键词：Apple-inspired, premium editorial, pure white background, hero subject, clean typography, minimal infographic, high-end science poster. 画面结构： 顶部左侧为标题区： 中文大标题：{中文物种名} 中文副标题：{一句有吸引力的物种定位} 细短横线 英文名：{英文物种名} 分布信息：主要分布：{分布区域} 中部与下中部为主体视觉： 生成一个超高清、真实、具有强烈立体感的 {中文物种名}。 主体应占据画面 50% 到 70% 的视觉面积。 主体姿态应具有展示性、力量感或识别度。 保持白色背景，不添加复杂自然环境。 可以保留少量必要承托物，例如树枝、岩石、雪地、沙土或木皮，但必须简洁。 主体要有真实阴影，使其像高级产品摄影一样立在画面中。 底部信息区： 用四个极简信息栏目展示科普信息。 每个栏目包含： 一个细线 icon 一个彩色小标题 一段 1 到 3 行短文字 栏目之间用极细浅灰竖线分隔。 不使用卡片框，不使用圆角背景，不使用大面积色块。 四个信息栏目： 栏目 1： 标题：{重点特征1标题} 说明：{重点特征1短说明} 栏目 2： 标题：{重点特征2标题} 说明：{重点特征2短说明} 栏目 3： 标题：{重点特征3标题} 说明：{重点特征3短说明} 栏目 4： 标题：{重点特征4标题} 说明：{重点特征4短说明} 底部总结句： 在最底部居中放置一句灰色小字总结： {一句高级、克制、有记忆点的科普总结} 字体与排版： 中文标题使用大号黑色、高级、稳重、有力量感的字体。 副标题使用灰色，中等字号，字距略宽。 英文名使用小号灰色，简洁现代。 正文使用清晰现代中文字体，保持可读。 所有文字必须留有足够呼吸感。 色彩规范： 背景：纯白、极浅灰、轻微柔光渐变。 主标题：黑色或深石墨色。 副标题与正文：中性灰。 底部四个信息标题可使用低饱和强调色： 暖棕、冷蓝、松石绿、紫色、橙色。 颜色只用于 icon 和小标题，不要大面积铺色。 图像质量： 2K 高清质感，细节清晰，主体锐利，光影真实。 主体纹理必须可信，例如毛发、鳞片、甲壳、皮肤褶皱、羽毛或斑纹。 避免变形、错误肢体、错误解剖结构、模糊主体、低质贴图、塑料感、卡通感。 禁止项： 不要使用淡黄色旧纸背景。 不要使用复杂信息图网格。 不要使用圆角卡片。 不要使用厚边框。 不要使用大面积装饰图形。 不要添加无关 logo。 不要添加多余小字。 不要让主体太小。 不要让文字压住主体。 不要让底部信息区过度拥挤。 不要出现儿童科普风、卡通风、低端展板风。 最终输出： 生成一张 9:16 竖版、高级、干净、强视觉冲击的 Apple 风自然科普海报。', 'https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/407.jpg', 'Apple 风格自然科普海报

![](https://raw.githubusercontent.com/davidwuw0811-boop/awesome-gpt-image2-prompts/main/images/407.jpg)', 'davidwu-gpt-image2-prompts', '["ui与界面","ui","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1789);
INSERT INTO prompt_library(title, prompt_content, cover_url, preview_content, category, tags_data, source_url, status, sort_order)
VALUES ('其他', '异质感oc，绝美红妆女子，位于彼岸花丛中，张力。 唐琬《钗头凤·世情薄》 世情薄，人情恶，雨送黄昏花易落。晓风干，泪痕残。欲笺心事，独语斜阑。难，难，难！', '', '彼岸花丛中的红妆女子', 'davidwu-gpt-image2-prompts', '["其他","other","freestylefly","freestylefly","awesome-gpt-image-2"]'::jsonb, 'https://github.com/davidwuw0811-boop/awesome-gpt-image2-prompts', 1, 1790);
